    descs=set()
    for a in n.get('input_arguments',[])+n.get('output_arguments',[])+n.get('input_output_arguments',[]):
        descs.add(a['description'])
    cols=set()
    for L in lines:
        for dd in descs:
            idx=L.find(dd)
            if idx>=0: cols.add(idx)
    print(' '.join(p), sorted(cols))
