{"command": "cd /tmp && cat > join.py <<'PYEOF'
import json,re
d=json.load(open('usage.json'))
spec=json.load(open('spec.json'))
ucomps={}
def walk(n,path):
    name=n.get('name','')
    p=path+([name] if name else [])
    ucomps[tuple(p)]=n
    for c in n.get('sub_algorithms',[]): walk(c,p)
walk(d,[])
FRAME={"help","json-usage","config","version"}
out=[]
for c in spec['commands']:
    p=tuple(c['path']); un=ucomps.get(p,{})
    jsonargs=un.get('input_arguments',[])+un.get('output_arguments',[])+un.get('input_output_arguments',[])
    byname={}
    for a in jsonargs: byname[a['name']]=a
    helpentries=[]
    for sec in c['sections']:
        for e in sec['entries']:
            helpentries.append((sec['title'],e))
    used=set()
    res=[]
    for sec,e in helpentries:
        names=[x.lstrip('-') for x in e['names']]
        if names[0] in FRAME or (len(names)==1 and names[0] in FRAME):
            ja=None
        else:
            ja=None
            for nn in names:
                if nn in byname: ja=byname[nn]; break
            if ja is None:
                # try hyphen/underscore variants
                for nn in names:
                    for jn in byname:
                        if jn.replace('-','_')==nn.replace('-','_'): ja=byname[jn]; break
                    if ja: break
        if ja: used.add(id(ja))
        res.append({"section":sec,"help":e,"json":ja})
    unmatched=[a['name'] for a in jsonargs if id(a) not in used]
    if unmatched: print('UNMATCHED','/'.join(c['path']),unmatched)
    out.append({"path":c['path'],"usage":c['usage'],"description":c.get('description'),"subcommands":c.get('subcommands'),"args":res,"json_no_help":unmatched})
json.dump(out,open('spec2.json','w'),indent=1)
PYEOF
python3 join.py"}

