#!/usr/bin/env python3
"""Generate the CLI specification tables (C++ source) from observed behaviour data."""
import json,re,sys,os

USAGE=json.load(open('/tmp/usage.json'))
SPEC=json.load(open('/tmp/spec2.json'))

def get_cmd(path):
    n=USAGE
    for k in path:
        n=[x for x in n['sub_algorithms'] if x['name']==k][0]
    return n

def enc(s):
    """Encode a string for embedding in a C++ string literal (records use \n and \x01)."""
    out=[]
    for ch in s:
        o=ord(ch)
        if ch=='\n': out.append('\\n')
        elif ch=='\t': out.append('\\t')
        elif ch=='"': out.append('\\"')
        elif ch=='\\': out.append('\\\\')
        elif ch=='\r': out.append('\\r')
        elif o<0x20 or o==0x7f: out.append('\\x%02x'%(o & 0xff))
        elif o>126: out.append('\\x%02x\\x%02x'%(o>>8 & 0xff, o&0xff)) if False else out.append(ch)
        else: out.append(ch)
    return ''.join(out)

# ---- gather commands -------------------------------------------------------
commands=[]
seen={}
for c in SPEC['commands']:
    path=tuple(c['path'])
    un=get_cmd(list(path))
    rec={'path':list(path), 'name':path[-1], 'desc':un['description'],
         'short_url':un['short_url'], 'url':un['url'],
         'children':[x['name'] for x in un.get('sub_algorithms',[])],
         'ia':[a['name'] for a in un.get('input_arguments',[])],
         'oa':[a['name'] for a in un.get('output_arguments',[])],
         'ioa':[a['name'] for a in un.get('input_output_arguments',[])],
         'so':un.get('supports_streamed_output'),
         'usage':c['usage'],
         'description_help':c.get('description'),
         'subcommands':c.get('subcommands'),
         'args':c['args']}
    commands.append(rec)
    seen[path]=rec

# alias map from help subcommand descriptions
alias={}
for c in commands:
    for sub in (c.get('subcommands') or []):
        m=re.search(r' \(alias: ([^)]*)\)$', sub[1])
        if m:
            alias[(tuple(c['path']),sub[0])]=m.group(1)
PYEOF
echo ok"}

