# ---- derive help description from JSON -------------------------------------
def upper_name(name):
    return name.upper().replace('-','-')

def derive_help_desc(a, jsonname):
    d=a['description']
    if a.get('choices'):
        d = d + '. ' + upper_name(jsonname) + '=' + '|'.join(a['choices'])
    if 'default' in a and a['type']!='boolean':
        dv=a['default']
        if a['type'].endswith('_list'):
            pass
        d = d + ' (default: ' + json.dumps(dv) if False else d + ' (default: ' + str(dv) + ')'
    grp=a.get('mutual_exclusion_group')
    if grp:
        others=[]
        # filled later: needs group membership
        d = d + '\n@EXCL@' + grp + '|' + jsonname
    return d
PYEOF
