{"command": "mkdir -p /workspace/src && cat > /workspace/src/spec.h <<'EOF'
/* Command line specification tables and rendering of help / JSON usage. */
#ifndef GDALCLI_SPEC_H
#define GDALCLI_SPEC_H

#include <string>
#include <vector>

struct ArgDef {
    std::string name;      /* canonical (JSON) name, empty for framework-only args */
    std::string names;     /* option spellings: "-i, --dataset, --input" */
    std::string metavar;
    std::string type;
    std::string desc;
    std::string choices;   /* '|'-separated */
    std::string def;
    std::string minValue, minIncl, maxValue, maxIncl;
    std::string required;
    std::string packed, repeated, minCount, maxCount;
    std::string category;
    std::string datasetType;
    std::string inputFlags, outputFlags;
    std::string metadata;
    std::string excl;
    std::string section;
    std::string positional;
    std::string helpDesc;
    std::string derived;

    bool isList() const { return type.size() > 5 && type.substr(type.size() - 5) == "_list"; }
    bool isBoolean() const { return type == "boolean"; }
    bool isPositional() const { return positional == "1"; }
    bool isRequired() const { return required == "1"; }
};

struct CmdDef;

struct SubInfo {
    std::string name;
    std::string desc;
};

struct CmdDef {
    std::string name;
    std::string path;      /* "raster/info" ; empty for root */
    std::string desc;
    std::string shortUrl;
    std::string url;
    std::string children;  /* '|'-separated child names */
    std::string ia, oa, ioa;
    std::string supportsStreamed;
    std::string usage;     /* exact "Usage: ..." line */
    int firstArg = 0;
    int nArgs = 0;
    std::string subs;      /* name\x03desc ... \x02 */
    std::string root;
    std::vector<ArgDef> args;
    std::vector<SubInfo> subInfos;
    CmdDef *parent = nullptr;
    std::vector<std::string> childNames() const;
    std::string fullPathCli() const; /* e.g. "gdal raster info" */
    bool isRoot() const { return root == "1"; }
    bool hasChildren() const { return !children.empty(); }
    ArgDef *findArg(const std::string &name);
    ArgDef *findOption(const std::string &spelling);
};

/* Load the specification tables. */
void SpecLoad();
CmdDef *SpecRoot();
CmdDef *SpecFind(const std::string &path); /* "raster/info" */
std::vector<CmdDef *> &SpecAll();

/* Rendering */
std::string RenderHelp(CmdDef *c);
std::string RenderUsageForError(CmdDef *c);
std::string RenderJsonUsage(CmdDef *c, bool top);
void SpecVerify();

extern const char *const kSpecRecords[];

#endif
EOF
echo ok"}

