            size_t q = n.find(", ", p);
            std::string tok = n.substr(p, q == std::string::npos ? std::string::npos : q - p);
            tok = tok.substr(tok.find_first_not_of('-'));
            if (tok == sp) return &a;
            p = (q == std::string::npos) ? n.size() : q + 2;
        }
    }
    return nullptr;
}

void SpecLoad()
{
    static bool loaded = false;
    if (loaded) return;
    loaded = true;
    std::vector<std::string> recs;
    {
        const char *p = kSpecRecords;
        std::string cur;
        while (*p) {
            if (*p == '\n') { recs.push_back(cur); cur.clear(); ++p; }
            else cur += *p++;
        }
        if (!cur.empty()) recs.push_back(cur);
    }
    CmdDef *curCmd = nullptr;
    for (auto &r : recs) {
        std::vector<std::string> f;
        size_t p = 0;
        while (true) {
            size_t q = r.find('\x01', p);
            if (q == std::string::npos) { f.push_back(r.substr(p)); break; }
            f.push_back(r.substr(p, q - p));
            p = q + 1;
        }
        if (f[0] == "C") {
            curCmd = new CmdDef();
            curCmd->name = f[1];
            curCmd->path = f[2];
            curCmd->desc = f[3];
            curCmd->shortUrl = f[4];
            curCmd->url = f[5];
            curCmd->children = f[6];
            curCmd->ia = f[7];
            curCmd->oa = f[8];
            curCmd->ioa = f[9];
            curCmd->supportsStreamed = f[10];
            curCmd->usage = f[11];
            curCmd->firstArg = atoi(f[12].c_str());
            curCmd->nArgs = atoi(f[13].c_str());
            curCmd->subs = f[14];
            curCmd->root = f[15];
            for (auto &s : split(f[14], '\x02')) {
                SubInfo si;
                size_t q = s.find('\x03');
                if (q == std::string::npos) continue;
                si.name = s.substr(0, q);
                si.desc = s.substr(q + 1);
                curCmd->subInfos.push_back(si);
            }
            g_all.push_back(curCmd);
            if (curCmd->isRoot()) g_root = curCmd;
        } else if (f[0] == "A" && curCmd) {
            ArgDef a;
            a.name = f[1];
            a.names = f[2];
            a.metavar = f[3];
            a.type = f[4];
            a.desc = f[5];
            a.choices = f[6];
            a.def = f[7];
            a.minValue = f[8];
            a.minIncl = f[9];
            a.maxValue = f[10];
            a.maxIncl = f[11];
            a.required = f[12];
            a.packed = f[13];
            a.repeated = f[14];
            a.minCount = f[15];
            a.maxCount = f[16];
            a.category = f[17];
            a.datasetType = f[18];
            a.inputFlags = f[19];
            a.outputFlags = f[20];
            a.metadata = f[21];
            a.excl = f[22];
            a.section = f[23];
            a.positional = f[24];
            a.helpDesc = f[25];
            a.derived = f[26];
            curCmd->args.push_back(a);
