    }
}

CmdDef *SpecRoot() { SpecLoad(); return g_root; }

CmdDef *SpecFind(const std::string &path)
{
    SpecLoad();
    for (auto *c : g_all) if (c->path == path) return c;
    return nullptr;
}

std::vector<CmdDef *> &SpecAll() { SpecLoad(); return g_all; }

/* ------------------------------------------------------------------ */
/* Help rendering                                                      */
/* ------------------------------------------------------------------ */

static const char *kWarning[] = {
    "WARNING: the gdal command is provisionally provided as an alternative interface to GDAL and OGR command line utilities.",
    "The project reserves the right to modify, rename, reorganize, and change the behavior of the utility",
    "until it is officially frozen in a future feature release of GDAL."
};
static const char *kShortcuts =
    "'gdal <FILENAME>' can also be used as a shortcut for 'gdal info <FILENAME>'.\n"
    "And 'gdal read <FILENAME> ! ...' as a shortcut for 'gdal pipeline <FILENAME> ! ...'.";

static std::string OptionSpec(const ArgDef &a)
{
    std::string s = a.names;
    if (!a.metavar.empty()) s += " " + a.metavar;
    return s;
}

static std::string HelpDescription(const ArgDef &a)
{
    if (a.name.empty()) return a.desc;   /* framework only args carry their text */
    return a.derived;
}

/* category -> section title */
static std::string SectionOf(const ArgDef &a)
{
    if (a.isPositional()) return "Positional arguments";
    if (a.category == "Common") return "Common Options";
    if (a.category == "Base") return "Options";
    if (a.category == "Advanced") return "Advanced Options";
    if (a.category == "Esoteric") return "Esoteric Options";
    return a.section;
}

static int SectionRank(const std::string &t)
{
    if (t == "Positional arguments") return 0;
    if (t == "Common Options") return 1;
    if (t == "Options") return 2;
    if (t == "Advanced Options") return 3;
    if (t == "Esoteric Options") return 4;
    return 5;
}

std::string RenderHelp(CmdDef *c)
{
    std::string out;
    if (c->hasChildren()) {
        out = "Usage: " + c->usage + "\n";
        out += "where <SUBCOMMAND> is one of:\n";
        size_t m = 0;
        for (auto &s : c->subInfos) m = std::max(m, s.name.size());
        int col = 2 + 2 + (int)m + 2;
        for (auto &s : c->subInfos) {
            std::string line = "  - " + s.name + ":";
            while ((int)line.size() < col) line += ' ';
            out += line + s.desc + "\n";
        }
        out += "\n";
        /* options sections (framework + extra) */
        std::vector<ArgDef *> entries;
        for (auto &a : c->args) if (SectionOf(a) == "Options") entries.push_back(&a);
        int cm = 0;
        std::vector<ArgDef *> common;
        for (auto &a : c->args) if (SectionOf(a) == "Common Options") common.push_back(&a);
        for (auto *a : common) cm = std::max(cm, (int)OptionSpec(*a).size());
        for (auto *a : entries) cm = std::max(cm, (int)OptionSpec(*a).size());
        int col2 = 2 + cm + 2;
        auto emit = [&](const std::string &title, const std::vector<ArgDef *> &v) {
            if (v.empty()) return;
            out += title + ":\n";
            for (auto *a : v) {
                std::string line = "  " + OptionSpec(*a);
                while ((int)line.size() < col2) line += ' ';
                out += line + a->desc + "\n";
            }
            out += "\n";
        };
        emit("Common Options", common);
        emit("Options", entries);
        if (c->url.empty()) {
            /* footer omitted */
        } else {
            out += "For more details, consult " + c->url + "\n\n";
        }
        for (auto *l : kWarning) out += std::string(l) + "\n";
        return out;
    }

    out = c->usage + "\n\n";
    out += c->desc + "\n\n";

    /* group args per section */
    std::vector<std::vector<const ArgDef *>> bySec(6);
    for (auto &a : c->args) bySec[SectionRank(SectionOf(a))].push_back(&a);
    int cm = 0;
    for (auto &v : bySec) for (auto *a : v) cm = std::max(cm, (int)OptionSpec(*a).size());
    int col = 2 + cm + 2;
    for (int i = 0; i < 6; ++i) {
        if (bySec[i].empty()) continue;
        out += (i == 0 ? std::string("Positional arguments") : bySec[i][0]->section) + ":\n";
        for (auto *a : bySec[i]) {
            std::string line = "  " + OptionSpec(*a);
            while ((int)line.size() < col) line += ' ';
            out += line + HelpDescription(*a) + "\n";
        }
        out += "\n";
    }
    if (!c->url.empty()) out += "For more details, consult " + c->url + "\n\n";
    for (auto *l : kWarning) out += std::string(l) + "\n";
    return out;
}

/* The usage block printed along with errors. */
std::string RenderUsageForError(CmdDef *c)
{
    std::string out = "Usage: " + c->usage + "\n";
