#include "spec.h"
#include "port.h"

#include <cstdio>
#include <cstring>
#include <algorithm>

static std::vector<CmdDef *> g_all;
static CmdDef *g_root = nullptr;

static std::vector<std::string> split(const std::string &s, char sep)
{
    std::vector<std::string> r;
    if (s.empty()) return r;
    size_t p = 0;
    while (true) {
        size_t q = s.find(sep, p);
        if (q == std::string::npos) { r.push_back(s.substr(p)); break; }
        r.push_back(s.substr(p, q - p));
        p = q + 1;
    }
    return r;
}

std::vector<std::string> CmdDef::childNames() const { return split(children, '|'); }

std::string CmdDef::fullPathCli() const
{
    std::string p = path;
    for (auto &ch : p) if (ch == '/') ch = ' ';
    return p.empty() ? std::string("gdal") : "gdal " + p;
}

ArgDef *CmdDef::findArg(const std::string &n)
{
    for (auto &a : args) if (a.name == n) return &a;
    return nullptr;
}

ArgDef *CmdDef::findOption(const std::string &sp)
{
    for (auto &a : args) {
        size_t p = 0;
        std::string n = a.names;
        while (p < n.size()) {
            size_t q = n.find(", ", p);
            std::string tok = n.substr(p, q == std::string::npos ? std::string::npos : q - p);
            tok = tok.substr(tok.find_first_not_of('-'));
            if (tok == sp) return &a;
            p = (q == std::string::npos) ? n.size() : q + 2;
        }
    }
    return nullptr;
}

void SpecLoad()
{
    static bool loaded = false;
    if (loaded) return;
    loaded = true;
    std::vector<std::string> recs;
    {
        const char *p = kSpecRecords;
        std::string cur;
        while (*p) {
            if (*p == '\n') { recs.push_back(cur); cur.clear(); ++p; }
            else cur += *p++;
        }
        if (!cur.empty()) recs.push_back(cur);
    }
    CmdDef *curCmd = nullptr;
    for (auto &r : recs) {
        std::vector<std::string> f;
        size_t p = 0;
        while (true) {
            size_t q = r.find('\x01', p);
            if (q == std::string::npos) { f.push_back(r.substr(p)); break; }
            f.push_back(r.substr(p, q - p));
            p = q + 1;
        }
        if (f[0] == "C") {
            curCmd = new CmdDef();
            curCmd->name = f[1];
            curCmd->path = f[2];
            curCmd->desc = f[3];
            curCmd->shortUrl = f[4];
            curCmd->url = f[5];
            curCmd->children = f[6];
            curCmd->ia = f[7];
            curCmd->oa = f[8];
            curCmd->ioa = f[9];
            curCmd->supportsStreamed = f[10];
            curCmd->usage = f[11];
            curCmd->firstArg = atoi(f[12].c_str());
            curCmd->nArgs = atoi(f[13].c_str());
            curCmd->subs = f[14];
            curCmd->root = f[15];
            for (auto &s : split(f[14], '\x02')) {
                SubInfo si;
                size_t q = s.find('\x03');
                if (q == std::string::npos) continue;
                si.name = s.substr(0, q);
                si.desc = s.substr(q + 1);
                curCmd->subInfos.push_back(si);
            }
            g_all.push_back(curCmd);
            if (curCmd->isRoot()) g_root = curCmd;
        } else if (f[0] == "A" && curCmd) {
            ArgDef a;
            a.name = f[1];
            a.names = f[2];
            a.metavar = f[3];
            a.type = f[4];
            a.desc = f[5];
            a.choices = f[6];
            a.def = f[7];
            a.minValue = f[8];
            a.minIncl = f[9];
            a.maxValue = f[10];
            a.maxIncl = f[11];
            a.required = f[12];
            a.packed = f[13];
            a.repeated = f[14];
            a.minCount = f[15];
            a.maxCount = f[16];
            a.category = f[17];
            a.datasetType = f[18];
            a.inputFlags = f[19];
            a.outputFlags = f[20];
            a.metadata = f[21];
            a.excl = f[22];
            a.section = f[23];
            a.positional = f[24];
            a.helpDesc = f[25];
            a.derived = f[26];
            curCmd->args.push_back(a);
        }
    }
    /* link parents */
    for (auto *c : g_all) {
        if (c->isRoot()) continue;
        std::string p = c->path;
        size_t q = p.rfind('/');
        if (q == std::string::npos) c->parent = g_root;
        else c->parent = SpecFind(p.substr(0, q));
    }
}

CmdDef *SpecRoot() { SpecLoad(); return g_root; }

CmdDef *SpecFind(const std::string &path)
{
    SpecLoad();
    for (auto *c : g_all) if (c->path == path) return c;
    return nullptr;
}

std::vector<CmdDef *> &SpecAll() { SpecLoad(); return g_all; }

/* ------------------------------------------------------------------ */
/* Help rendering                                                      */
/* ------------------------------------------------------------------ */

static const char *kWarning[] = {
    "WARNING: the gdal command is provisionally provided as an alternative interface to GDAL and OGR command line utilities.",
    "The project reserves the right to modify, rename, reorganize, and change the behavior of the utility",
    "until it is officially frozen in a future feature release of GDAL."
};
static const char *kShortcuts =
    "'gdal <FILENAME>' can also be used as a shortcut for 'gdal info <FILENAME>'.\n"
    "And 'gdal read <FILENAME> ! ...' as a shortcut for 'gdal pipeline <FILENAME> ! ...'.";

static std::string OptionSpec(const ArgDef &a)
{
    std::string s = a.names;
    if (!a.metavar.empty()) s += " " + a.metavar;
    return s;
}

static std::string HelpDescription(const ArgDef &a)
{
    if (a.name.empty()) return a.desc;   /* framework only args carry their text */
    return a.derived;
}

/* category -> section title */
static std::string SectionOf(const ArgDef &a)
{
    if (a.isPositional()) return "Positional arguments";
    if (a.category == "Common") return "Common Options";
    if (a.category == "Base") return "Options";
    if (a.category == "Advanced") return "Advanced Options";
    if (a.category == "Esoteric") return "Esoteric Options";
    return a.section;
}

static int SectionRank(const std::string &t)
{
    if (t == "Positional arguments") return 0;
    if (t == "Common Options") return 1;
    if (t == "Options") return 2;
    if (t == "Advanced Options") return 3;
    if (t == "Esoteric Options") return 4;
    return 5;
}

std::string RenderHelp(CmdDef *c)
{
    std::string out;
    if (c->hasChildren()) {
        out = "Usage: " + c->usage + "\n";
        out += "where <SUBCOMMAND> is one of:\n";
        size_t m = 0;
        for (auto &s : c->subInfos) m = std::max(m, s.name.size());
        int col = 2 + 2 + (int)m + 2;
        for (auto &s : c->subInfos) {
            std::string line = "  - " + s.name + ":";
            while ((int)line.size() < col) line += ' ';
            out += line + s.desc + "\n";
        }
        out += "\n";
        /* options sections (framework + extra) */
        std::vector<ArgDef *> entries;
        for (auto &a : c->args) if (SectionOf(a) == "Options") entries.push_back(&a);
        int cm = 0;
        std::vector<ArgDef *> common;
        for (auto &a : c->args) if (SectionOf(a) == "Common Options") common.push_back(&a);
        for (auto *a : common) cm = std::max(cm, (int)OptionSpec(*a).size());
        for (auto *a : entries) cm = std::max(cm, (int)OptionSpec(*a).size());
        int col2 = 2 + cm + 2;
        auto emit = [&](const std::string &title, const std::vector<ArgDef *> &v) {
            if (v.empty()) return;
            out += title + ":\n";
            for (auto *a : v) {
                std::string line = "  " + OptionSpec(*a);
                while ((int)line.size() < col2) line += ' ';
                out += line + a->desc + "\n";
            }
            out += "\n";
        };
        emit("Common Options", common);
        emit("Options", entries);
        if (c->url.empty()) {
            /* footer omitted */
        } else {
            out += "For more details, consult " + c->url + "\n\n";
        }
        for (auto *l : kWarning) out += std::string(l) + "\n";
        return out;
    }

    out = c->usage + "\n\n";
    out += c->desc + "\n\n";

    /* group args per section */
    std::vector<std::vector<const ArgDef *>> bySec(6);
    for (auto &a : c->args) bySec[SectionRank(SectionOf(a))].push_back(&a);
    int cm = 0;
    for (auto &v : bySec) for (auto *a : v) cm = std::max(cm, (int)OptionSpec(*a).size());
    int col = 2 + cm + 2;
    for (int i = 0; i < 6; ++i) {
        if (bySec[i].empty()) continue;
        out += (i == 0 ? std::string("Positional arguments") : bySec[i][0]->section) + ":\n";
        for (auto *a : bySec[i]) {
            std::string line = "  " + OptionSpec(*a);
            while ((int)line.size() < col) line += ' ';
            out += line + HelpDescription(*a) + "\n";
        }
        out += "\n";
    }
    if (!c->url.empty()) out += "For more details, consult " + c->url + "\n\n";
    for (auto *l : kWarning) out += std::string(l) + "\n";
    return out;
}

/* The usage block printed along with errors. */
std::string RenderUsageForError(CmdDef *c)
{
    std::string out = "Usage: " + c->usage + "\n";
    if (c->hasChildren()) {
        out += "where <SUBCOMMAND> is one of:\n";
        size_t m = 0;
        for (auto &s : c->subInfos) m = std::max(m, s.name.size());
        int col = 2 + 2 + (int)m + 2;
        for (auto &s : c->subInfos) {
            std::string line = "  - " + s.name + ":";
            while ((int)line.size() < col) line += ' ';
            out += line + s.desc + "\n";
        }
        out += "\n";
        if (!c->url.empty()) out += "For more details, consult " + c->url + "\n\n";
        for (auto *l : kWarning) out += std::string(l) + "\n";
    }
    return out;
}
EOF
echo ok"}

