{"command": "cat > /workspace/src/port.cpp <<'EOF'
#include "port.h"

#include <unistd.h>
#include <sys/stat.h>
#include <dirent.h>
#include <errno.h>
#include <stdint.h>
#include <cstdarg>
#include <set>

/* ------------------------------------------------------------------ */
static std::map<std::string, std::string> g_config;
static std::vector<std::map<std::string, std::string> > g_configStack;
static bool g_quiet = false;
static int g_errors = 0;

void CPLSetConfigOption(const std::string &k, const std::string &v) { g_config[k] = v; }
std::string CPLGetConfigOption(const std::string &k, const std::string &def)
{
    auto i = g_config.find(k);
    if (i != g_config.end()) return i->second;
    if (!def.empty()) return def;
    return std::string();
}
bool CPLTestConfigOption(const std::string &k, const std::string &def)
{
    std::string v = CPLGetConfigOption(k, def);
    if (v.empty()) v = def;
    return !(v == "NO" || v == "FALSE" || v == "OFF" || v == "0");
}
void CPLPushErrorContext() { g_configStack.push_back(g_config); }
void CPLPopErrorContext() { if (!g_configStack.empty()) { g_config = g_configStack.back(); g_configStack.pop_back(); } }

void CPLSetQuiet(bool q) { g_quiet = q; }
bool CPLGetQuiet() { return g_quiet; }
int CPLGetErrorCount() { return g_errors; }

void CPLLError(int num, const std::string &msg) { g_errors++; fprintf(stderr, "ERROR %d: %s\n", num, msg.c_str()); }
void CPLWarning(int num, const std::string &msg) { if (g_quiet) return; fprintf(stderr, "Warning %d: %s\n", num, msg.c_str()); }
void CPLInfo(const std::string &msg) { fprintf(stdout, "%s\n", msg.c_str()); }

/* ------------------------------------------------------------------ */
static bool g_progressQuiet = false;
static double g_progressLast = -1.0;
void CPLProgressInit() { g_progressLast = -1.0; }
void CPLProgressUpdate(double pct)
{
    if (g_progressQuiet) return;
    int v = (int)(pct * 100 + 0.5);
    if (v < 0) v = 0;
    if (v > 100) v = 100;
    if (v == g_progressLast) return;
    fprintf(stdout, "%s%d", (g_progressLast < 0) ? "" : "...", v);
    fflush(stdout);
    g_progressLast = v;
}
void CPLProgressDone()
{
    if (g_progressQuiet) return;
    if (g_progressLast < 0) return;
    fprintf(stdout, " - done.\n");
    fflush(stdout);
    g_progressLast = -1.0;
}

/* ------------------------------------------------------------------ */
std::string Trim(const std::string &s)
{
    size_t a = s.find_first_not_of(" \t\r\n");
    if (a == std::string::npos) return std::string();
    size_t b = s.find_last_not_of(" \t\r\n");
    return s.substr(a, b - a + 1);
}
std::string TrimStart(const std::string &s)
{
    size_t a = s.find_first_not_of(" \t\r\n");
    if (a == std::string::npos) return std::string();
    return s.substr(a);
}
std::string ToLower(const std::string &s) { std::string r(s); for (auto &c : r) c = (char)tolower((unsigned char)c); return r; }
std::string ToUpper(const std::string &s) { std::string r(s); for (auto &c : r) c = (char)toupper((unsigned char)c); return r; }

std::vector<std::string> StrSplit(const std::string &s, char sep)
{
    std::vector<std::string> r;
    if (s.empty()) return r;
    size_t p = 0;
    while (true) {
        size_t q = s.find(sep, p);
        if (q == std::string::npos) { r.push_back(s.substr(p)); break; }
        r.push_back(s.substr(p, q - p));
        p = q + 1;
    }
    return r;
}
std::vector<std::string> StrSplitStr(const std::string &s, const std::string &sep)
{
    std::vector<std::string> r;
    if (s.empty()) return r;
    size_t p = 0;
    while (true) {
        size_t q = s.find(sep, p);
        if (q == std::string::npos) { r.push_back(s.substr(p)); break; }
        r.push_back(s.substr(p, q - p));
        p = q + sep.size();
    }
    return r;
}
std::string StrJoin(const std::vector<std::string> &v, const std::string &sep)
{
    std::string r;
    for (size_t i = 0; i < v.size(); ++i) { if (i) r += sep; r += v[i]; }
    return r;
}
bool StrStartsWith(const std::string &s, const std::string &p) { return s.size() >= p.size() && s.compare(0, p.size(), p) == 0; }
bool StrEndsWith(const std::string &s, const std::string &p) { return s.size() >= p.size() && s.compare(s.size() - p.size(), p.size(), p) == 0; }

static int levMin(int a, int b, int c) { return a < b ? (a < c ? a : c) : (b < c ? b : c); }
int LevDistance(const std::string &a, const std::string &b)
{
    size_t n = a.size(), m = b.size();
    std::vector<int> prev(m + 1), cur(m + 1);
    for (size_t j = 0; j <= m; ++j) prev[j] = (int)j;
    for (size_t i = 1; i <= n; ++i) {
        cur[0] = (int)i;
        for (size_t j = 1; j <= m; ++j) {
