    if (q == std::string::npos) return p;
    return p.substr(q + 1);
}
bool RemoveFile(const std::string &p)
{
    if (IsDirectory(p)) { for (auto &f : ListDir(p)) RemoveFile(p + "/" + f); return ::rmdir(p.c_str()) == 0; }
    return ::remove(p.c_str()) == 0;
}
bool RenameFile(const std::string &a, const std::string &b) { return ::rename(a.c_str(), b.c_str()) == 0; }

std::string ReadWholeFile(const std::string &p, bool &ok)
{
    ok = false;
    FILE *f = fopen(p.c_str(), "rb");
    if (!f) return std::string();
    std::string data;
    char buf[65536];
