bool ParseInt(const std::string &s, long long &v)
{
    std::string t = Trim(s);
    if (t.empty()) return false;
    char *end = nullptr;
    errno = 0;
    long long r = strtoll(t.c_str(), &end, 10);
    if (end == t.c_str() || *end != '\0') return false;
    v = r;
    return true;
}
bool ParseDouble(const std::string &s, double &v)
{
    std::string t = Trim(s);
    if (t.empty()) return false;
    if (t == "nan" || t == "NAN") { v = std::nan(""); return true; }
    if (t == "inf" || t == "INF") { v = INFINITY; return true; }
    if (t == "-inf" || t == "-INF") { v = -INFINITY; return true; }
    char *end = nullptr;
    errno = 0;
    double r = strtod(t.c_str(), &end);
    if (end == t.c_str() || *end != '\0') return false;
    v = r;
    return true;
}
GIntBig ParseByteSize(const std::string &s)
{
    std::string t = Trim(s);
    GIntBig mult = 1;
    if (!t.empty()) {
        char c = (char)toupper((unsigned char)t[t.size() - 1]);
        if (c == 'K') { mult = 1024; t = t.substr(0, t.size() - 1); }
        else if (c == 'M') { mult = 1024 * 1024; t = t.substr(0, t.size() - 1); }
        else if (c == 'G') { mult = 1024LL * 1024 * 1024; t = t.substr(0, t.size() - 1); }
    }
    double v = 0;
    if (!ParseDouble(t, v)) return -1;
    return (GIntBig)(v * mult);
}
