        }
        if (!out.empty() && out[out.size() - 2] == ',') out = out.substr(0, out.size() - 2) + "\n";
        out += "  ],\n";
    };
    (void)emitArgs;
    /* inline arg emission */
    auto emitList = [&](const char *title, const std::vector<std::string> &names) {
        out += "  \"" + std::string(title) + "\":[\n";
        bool any = false;
        for (auto &n : names) {
            ArgDef *a = c->findArg(n);
            if (!a) continue;
            any = true;
            out += "    {\n" + RenderArgJson(*a, 6) + "\n    },\n";
        }
        if (any) out = out.substr(0, out.size() - 2) + "\n";
        out += "  ],\n";
    };
    emitList("input_arguments", StrSplit(c->ia, ','));
    emitList("output_arguments", StrSplit(c->oa, ','));
    emitList("input_output_arguments", StrSplit(c->ioa, ','));
    if (!out.empty() && out[out.size() - 2] == ',') out = out.substr(0, out.size() - 2) + "\n";
    if (c->supportsStreamed == "1") out += "  \"supports_streamed_output\":true\n";
    else if (!out.empty() && out[out.size() - 2] == ',') out = out.substr(0, out.size() - 2) + "\n";
    out += "}";
    return out;
}
