/* ------------------------------------------------------------------ */
/* Help rendering                                                      */
/* ------------------------------------------------------------------ */

static const char *kWarning[] = {
    "WARNING: the gdal command is provisionally provided as an alternative interface to GDAL and OGR command line utilities.",
    "The project reserves the right to modify, rename, reorganize, and change the behavior of the utility",
    "until it is officially frozen in a future feature release of GDAL."
};

static std::string OptionSpec(const ArgDef &a)
{
    std::string s = a.names;
    if (!a.metavar.empty()) s += " " + a.metavar;
    return s;
}

static std::string HelpDescription(const ArgDef &a)
{
    if (a.name.empty()) return a.desc;
    return a.derived;
}

static std::string SectionOf(const ArgDef &a)
{
    if (a.isPositional()) return "Positional arguments";
    if (a.category == "Common") return "Common Options";
    if (a.category == "Base") return "Options";
    if (a.category == "Advanced") return "Advanced Options";
    if (a.category == "Esoteric") return "Esoteric Options";
    return a.section;
}

static int SectionRank(const std::string &t)
{
    if (t == "Positional arguments") return 0;
    if (t == "Common Options") return 1;
    if (t == "Options") return 2;
    if (t == "Advanced Options") return 3;
    if (t == "Esoteric Options") return 4;
    return 5;
}

static std::string SubList(const CmdDef *c)
{
    std::string out = "where <SUBCOMMAND> is one of:\n";
    size_t m = 0;
    for (auto &s : c->subInfos) m = std::max(m, s.name.size());
    int col = (int)m + 6;
    for (auto &s : c->subInfos) {
        std::string line = "  - " + s.name + ":";
        while ((int)line.size() < col) line += ' ';
        out += line + s.desc + "\n";
    }
    return out;
}

std::string RenderHelp(CmdDef *c)
{
    std::string out;
    if (c->hasChildren()) {
        out += "Usage: " + c->usage + "\n";
        out += SubList(c);
        out += "\n";
        std::vector<const ArgDef *> common, opts;
        for (auto &a : c->args) {
            std::string sec = SectionOf(a);
            if (sec == "Common Options") common.push_back(&a);
            else if (sec == "Options") opts.push_back(&a);
            else if (sec == a.section) opts.push_back(&a);
        }
        int cm = 0;
        for (auto *a : common) cm = std::max(cm, (int)OptionSpec(*a).size());
        for (auto *a : opts) cm = std::max(cm, (int)OptionSpec(*a).size());
        int col = 2 + cm + 2;
        auto emit = [&](const std::string &title, const std::vector<const ArgDef *> &v) {
            if (v.empty()) return;
            out += title + ":\n";
            for (auto *a : v) {
                std::string line = "  " + OptionSpec(*a);
                while ((int)line.size() < col) line += ' ';
                out += line + a->desc + "\n";
            }
            out += "\n";
        };
        emit("Common Options", common);
        emit("Options", opts);
        if (!c->url.empty()) out += "For more details, consult " + c->url + "\n\n";
        for (auto *l : kWarning) out += std::string(l) + "\n";
        return out;
    }

    out += c->usage + "\n\n";
    out += c->desc + "\n\n";

    std::vector<std::vector<const ArgDef *>> bySec(6);
    for (auto &a : c->args) bySec[SectionRank(SectionOf(a))].push_back(&a);
    int cm = 0;
    for (auto &v : bySec) for (auto *a : v) cm = std::max(cm, (int)OptionSpec(*a).size());
    int col = 2 + cm + 2;
    for (int i = 0; i < 6; ++i) {
        if (bySec[i].empty()) continue;
        out += bySec[i][0]->section + ":\n";
        for (auto *a : bySec[i]) {
            std::string line = "  " + OptionSpec(*a);
            while ((int)line.size() < col) line += ' ';
            out += line + HelpDescription(*a) + "\n";
        }
        out += "\n";
    }
    if (!c->url.empty()) out += "For more details, consult " + c->url + "\n\n";
    for (auto *l : kWarning) out += std::string(l) + "\n";
    return out;
}

std::string RenderUsageForError(CmdDef *c)
{
    std::string out = "Usage: " + c->usage + "\n";
    if (c->hasChildren()) {
        out += SubList(c);
        out += "\n";
        if (!c->url.empty()) out += "For more details, consult " + c->url + "\n\n";
        for (auto *l : kWarning) out += std::string(l) + "\n";
    }
    return out;
}

/* ------------------------------------------------------------------ */
/* JSON usage rendering                                                */
/* ------------------------------------------------------------------ */

std::string JsonEscape(const std::string &v)
{
    std::string r;
    for (unsigned char c : v) {
        switch (c) {
            case '\\': r += "\\\\"; break;
            case '"': r += "\\\""; break;
            case '/': r += "\\/"; break;
            case '\n': r += "\\n"; break;
            case '\t': r += "\\t"; break;
            case '\r': r += "\\r"; break;
            case '\b': r += "\\b"; break;
            case '\f': r += "\\f"; break;
            default:
                if (c < 0x20) { char b[8]; snprintf(b, sizeof(b), "\\u%04x", c); r += b; }
                else r += (char)c;
        }
    }
    return r;
}

/* Split "key":[ "a", "b" ] metadata text into pairs */
static std::vector<std::pair<std::string, std::vector<std::string>>> MetaPairs(const std::string &body)
{
    std::vector<std::pair<std::string, std::vector<std::string>>> r;
    std::string b = body;
    if (b.size() >= 2 && b[0] == '{') b = b.substr(1, b.size() - 2);
    size_t p = 0;
    while (p < b.size()) {
        size_t q = b.find(":[", p);
        if (q == std::string::npos) break;
        std::string k = b.substr(p, q - p);
        if (k.size() >= 2 && k[0] == '"') k = k.substr(1, k.size() - 2);
        size_t r2 = b.find("]", q);
        std::string arr = b.substr(q + 2, r2 - q - 2);
        std::vector<std::string> items;
        for (auto &it : StrSplit(arr, ',')) {
            std::string t = Trim(it);
            if (t.size() >= 2 && t[0] == '"') t = t.substr(1, t.size() - 2);
            if (!t.empty()) items.push_back(t);
        }
        r.push_back({k, items});
        p = r2 + 2;
    }
    return r;
}

std::string RenderArgJson(const ArgDef &a, int base)
{
    std::string out;
    std::string pad(base, ' ');
    std::string in(base + 2, ' ');
    auto kv = [&](const std::string &k, const std::string &v, bool last = false) {
        out += in + "\"" + k + "\":" + v + (last ? "\n" : ",\n");
    };
    auto kvs = [&](const std::string &k, const std::string &v) { kv(k, '"' + JsonEscape(v) + '"'); };
    auto karr = [&](const std::string &k, const std::string &joined) {
        out += in + "\"" + k + "\":[\n";
        for (auto &t : StrSplit(joined, '|')) out += pad + "  \"" + JsonEscape(t) + "\",\n";
        if (out.size() >= 2 && out[out.size() - 2] == ',') out = out.substr(0, out.size() - 2) + "\n";
        out += in + "],\n";
    };
    kvs("name", a.name);
    kvs("type", a.type);
    kvs("description", a.desc);
    if (!a.metavar.empty()) kvs("metavar", a.metavar);
    if (!a.choices.empty()) karr("choices", a.choices);
    if (!a.def.empty()) {
        if (a.type == "real" || a.type == "integer") kv("default", a.def);
        else kvs("default", a.def);
    }
    if (!a.minValue.empty()) {
        kv("min_value", a.minValue);
        kv("min_value_is_included", a.minIncl == "1" ? "true" : "false");
    }
    if (!a.maxValue.empty()) {
        kv("max_value", a.maxValue);
        kv("max_value_is_included", a.maxIncl == "1" ? "true" : "false");
    }
    kv("required", a.isRequired() ? "true" : "false");
    if (a.isList()) {
        kv("packed_values_allowed", a.packed == "1" ? "true" : "false");
        kv("repeated_arg_allowed", a.repeated == "1" ? "true" : "false");
        kv("min_count", a.minCount.empty() ? "0" : a.minCount);
        kv("max_count", a.maxCount.empty() ? "2147483647" : a.maxCount);
    }
    kvs("category", a.category);
    if (!a.datasetType.empty()) karr("dataset_type", a.datasetType);
    if (!a.inputFlags.empty()) karr("input_flags", a.inputFlags);
    if (!a.outputFlags.empty()) karr("output_flags", a.outputFlags);
    if (!a.metadata.empty()) {
        out += in + "\"metadata\":{\n";
        for (auto &pr : MetaPairs(a.metadata)) {
            out += pad + "  \"" + JsonEscape(pr.first) + "\":[\n";
            for (auto &it : pr.second) out += pad + "    \"" + JsonEscape(it) + "\",\n";
            if (!pr.second.empty()) out = out.substr(0, out.size() - 2) + "\n";
            out += pad + "  ],\n";
        }
        if (out.size() >= 2 && out[out.size() - 2] == ',') out = out.substr(0, out.size() - 2) + "\n";
        out += in + "},\n";
    }
    if (!a.excl.empty()) kvs("mutual_exclusion_group", a.excl);
    if (out.size() >= 2 && out[out.size() - 2] == ',') out = out.substr(0, out.size() - 2) + "\n";
    return out;
}

static std::string EmitArgList(const CmdDef *c, const std::string &names)
{
    std::string out = "  \"" + names + "\":[\n";
    std::vector<const ArgDef *> sel;
    for (auto &n : StrSplit(names, ',')) {
        if (n.empty()) continue;
        ArgDef *a = c->findArg(n);
        if (a) sel.push_back(a);
    }
    for (auto *a : sel) out += "    {\n" + RenderArgJson(*a, 6) + "\n    },\n";
    if (!sel.empty()) out = out.substr(0, out.size() - 2) + "\n";
    out += "  ],\n";
    return out;
}

std::string RenderJsonUsage(CmdDef *c, bool top)
{
    std::string out = "{\n";
    if (!top) {
        out += "  \"name\":\"" + JsonEscape(c->name) + "\",\n";
        out += "  \"full_path\":[\n";
        out += "    \"gdal\",\n";
        for (auto &t : StrSplit(c->path, '/')) out += "    \"" + JsonEscape(t) + "\",\n";
        out = out.substr(0, out.size() - 2) + "\n";
        out += "  ],\n";
    }
    out += "  \"description\":\"" + JsonEscape(c->desc) + "\",\n";
    if (!c->shortUrl.empty()) out += "  \"short_url\":\"" + JsonEscape(c->shortUrl) + "\",\n";
    if (!c->url.empty()) out += "  \"url\":\"" + JsonEscape(c->url) + "\",\n";
    out += "  \"sub_algorithms\":[\n";
    for (auto &n : c->childNames()) {
        std::string p = c->path.empty() ? n : c->path + "/" + n;
        CmdDef *ch = SpecFind(p);
        if (!ch) continue;
        out += RenderJsonUsage(ch, false) + ",\n";
    }
    if (out.size() >= 2 && out[out.size() - 2] == ',') out = out.substr(0, out.size() - 2) + "\n";
    out += "  ],\n";
    out += EmitArgList(c, c->ia);
    out += EmitArgList(c, c->oa);
    out += EmitArgList(c, c->ioa);
    if (out.size() >= 2 && out[out.size() - 2] == ',') out = out.substr(0, out.size() - 2) + "\n";
    if (c->supportsStreamed == "1") out += "  \"supports_streamed_output\":true\n";
    else if (out.size() >= 2 && out[out.size() - 2] == ',') out = out.substr(0, out.size() - 2) + "\n";
    out += "}";
    return out;
}
