#include "cli.h"
#include "spec.h"
#include "port.h"

#include <cstdio>
#include <cstring>
#include <algorithm>

std::string g_progName = "gdal";
std::string g_algName;

AlgValue *Alg::val(const std::string &name)
{
    for (auto &v : vals) if (v.def && v.def->name == name) return &v;
    return nullptr;
}
std::string Alg::str(const std::string &name)
{
    AlgValue *v = val(name);
    if (!v || v->values.empty()) return std::string();
    return v->values.back();
}
std::vector<std::string> Alg::lst(const std::string &name)
{
    AlgValue *v = val(name);
    if (!v) return std::vector<std::string>();
    return v->values;
}
bool Alg::flag(const std::string &name)
{
    AlgValue *v = val(name);
    if (!v) return false;
    if (v->values.empty()) return v->isSet;
    return v->values.back() == "true";
}
double Alg::num(const std::string &name, double dflt)
{
    AlgValue *v = val(name);
    if (!v || v->values.empty()) return dflt;
    double d = dflt;
    ParseDouble(v->values.back(), d);
    return d;
}
long long Alg::integer(const std::string &name, long long dflt)
{
    AlgValue *v = val(name);
    if (!v || v->values.empty()) return dflt;
    long long d = dflt;
    ParseInt(v->values.back(), d);
    return d;
}
void Alg::setUnsetDefaults()
{
    for (auto &v : vals) {
        if (!v.def) continue;
        if (v.values.empty() && !v.def->def.empty()) {
            v.values.push_back(v.def->def);
            v.isSet = true;
        }
    }
}

/* ------------------------------------------------------------------ */
void TmsWarn(int n)
{
    for (int i = 0; i < n; ++i) {
        std::string gd = CPLGetConfigOption("GDAL_DATA");
        if (gd.empty()) {
            CPLWarning(3, "Cannot find tms_NZTM2000.json (GDAL_DATA is not defined)");
        } else if (FileExists(gd + "/tms_NZTM2000.json")) {
            bool ok = false;
            std::string c = ReadWholeFile(gd + "/tms_NZTM2000.json", ok);
            if (!ok || Trim(c).empty() || c.find('{') == std::string::npos)
                CPLLError(1, "JSON parsing error: continue (at offset 0)");
        }
    }
}

/* ------------------------------------------------------------------ */
static void ReportOptionError(Alg &alg, int code, const std::string &msg)
{
    CPLLError(code, g_algName + ": " + msg);
    fputs(RenderUsageForError(alg.cmd).c_str(), stderr);
    fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
}

/* Print the whole error block for a failed parse of a parent command */
static void ReportParentError(CmdDef *c, const std::string &msg)
{
    CPLLError(5, c->name + ": " + msg);
    fputs(RenderUsageForError(c).c_str(), stderr);
    fprintf(stderr, "Try '%s --help' for help.\n", c->fullPathCli().c_str());
}

/* ------------------------------------------------------------------ */
/* Option/positional parsing                                           */
/* ------------------------------------------------------------------ */
static int OptionArity(const ArgDef &a)
{
    if (a.type == "boolean") return 0;
    return 1;
}

static void StoreValue(AlgValue &v, const std::string &val)
{
    const ArgDef &a = *v.def;
    if (a.isList() && a.packed == "1" && val.find(';') != std::string::npos) {
        for (auto &s : StrSplitStr(val, ";")) v.values.push_back(s);
    } else {
        v.values.push_back(val);
    }
    v.isSet = true;
}

int ParseArgs(Alg &alg, const std::vector<std::string> &args)
{
    alg.vals.clear();
    for (auto &a : alg.cmd->args) {
        AlgValue v;
        v.def = &a;
        alg.vals.push_back(v);
    }
    size_t posIdx = 0;
    std::vector<ArgDef *> positionals;
    for (auto &a : alg.cmd->args) if (a.isPositional()) positionals.push_back(&a);
    bool dashdash = false;
    for (size_t i = 0; i < args.size(); ++i) {
        const std::string &t = args[i];
        if (!dashdash && t == "--") { dashdash = true; continue; }
        if (!dashdash && t.size() >= 2 && t[0] == '-' && t[1] == '-') {
            std::string name = t.substr(2);
            std::string inlineVal;
            size_t q = name.find('=');
            bool hasInline = false;
            if (q != std::string::npos) { inlineVal = name.substr(q + 1); name = name.substr(0, q); hasInline = true; }
            ArgDef *a = alg.cmd->findOption(name);
            if (!a) {
                /* suggest closest */
                std::string best; int bestd = 1000;
                for (auto &x : alg.cmd->args) {
                    for (auto &tok : StrSplit(x.names, ", ")) {
                        std::string tt = tok.substr(tok.find_first_not_of('-'));
                        int d = LevDistance(name, tt);
                        if (d < bestd) { bestd = d; best = tt; }
                    }
                }
                std::string msg = "Option '--" + name + "' is unknown.";
                if (bestd <= 2) msg += " Do you mean '--" + best + "'?";
                ReportOptionError(alg, 5, msg);
                return -1;
            }
            AlgValue *v = alg.val(name);
            if (!v) continue;
            if (a->type == "boolean") {
                if (hasInline) { v->values.push_back(inlineVal); v->isSet = true; }
                else { v->values.push_back("true"); v->isSet = true; }
            } else {
                if (hasInline) { StoreValue(*v, inlineVal); }
                else {
                    if (i + 1 >= args.size()) {
                        ReportOptionError(alg, 5, "Expected value for argument '--" + name + "', but ran short of tokens");
                        return -1;
                    }
                    StoreValue(*v, args[++i]);
                }
            }
            continue;
        }
        if (!dashdash && t.size() >= 2 && t[0] == '-' && t[1] != '-') {
            std::string sh = t.substr(1, 1);
            ArgDef *a = nullptr;
            for (auto &x : alg.cmd->args) {
                for (auto &tok : StrSplit(x.names, ", ")) {
                    if (tok.size() >= 2 && tok[0] == '-' && tok[1] != '-' && tok.substr(1) == sh) { a = &x; break; }
                }
                if (a) break;
            }
            if (!a) {
                ReportOptionError(alg, 5, "Short name option '" + sh + "' is unknown.");
                return -1;
            }
            if (a->type != "boolean") {
                if (t.size() > 2) {
                    std::string msg = "Invalid argument '" + t + "'. Option '" + sh + "' is not a boolean option.";
                    ReportOptionError(alg, 5, msg);
                    return -1;
                }
                if (i + 1 >= args.size()) {
                    ReportOptionError(alg, 5, "Expected value for argument '-" + sh + "', but ran short of tokens");
                    return -1;
                }
                StoreValue(*alg.val(a->name), args[++i]);
            } else {
                if (t.size() > 2 && t[2] == '=') {
                    alg.val(a->name)->values.push_back(t.substr(3));
                    alg.val(a->name)->isSet = true;
                } else {
                    alg.val(a->name)->values.push_back("true");
                    alg.val(a->name)->isSet = true;
                }
            }
            continue;
        }
        /* positional */
        if (posIdx >= positionals.size()) {
            std::string msg = "Positional values starting at '" + t + "' are not expected.";
            ReportOptionError(alg, 1, msg);
            return -1;
        }
        ArgDef *a = positionals[posIdx];
        StoreValue(*alg.val(a->name), t);
        long long maxc = a->maxCount.empty() ? 1 : atoll(a->maxCount.c_str());
        long long minc = a->minCount.empty() ? 1 : atoll(a->minCount.c_str());
        long long n = (long long)alg.val(a->name)->values.size();
        if (maxc > 1 && n >= maxc) posIdx++;
        else if (maxc <= 1) posIdx++;
    }
    /* a positional that can take more values must not swallow the next arg */
    return 0;
}

/* ------------------------------------------------------------------ */
int ValidateArgs(Alg &alg)
{
    int rc = 0;
    std::vector<std::string> errs;
    for (auto &a : alg.cmd->args) {
        AlgValue *v = alg.val(a.name);
        if (!v) continue;
        if (a.isRequired() && v->values.empty() && a.def.empty()) {
            errs.push_back("Required argument '" + a.name + "' has not been specified.");
            continue;
        }
        if (v->values.empty()) continue;
        long long minc = a.minCount.empty() ? 1 : atoll(a.minCount.c_str());
        long long maxc = a.maxCount.empty() ? 1 : atoll(a.maxCount.c_str());
        if (a.isList()) {
            if ((long long)v->values.size() < minc) {
                errs.push_back(StrJoin(std::vector<std::string>{a.name}, "") + ": " +
                               std::to_string(v->values.size()) + " values have been specified for argument '" +
                               a.name + "', whereas at least " + std::to_string(minc) + " was expected.");
            }
            if (maxc != 2147483647 && (long long)v->values.size() > maxc) {
                errs.push_back(std::to_string(v->values.size()) + " values have been specified for argument '" +
                               a.name + "', whereas at most " + std::to_string(maxc) + " was expected.");
            }
        }
        /* choices */
        if (!a.choices.empty() && v->values.size() == 1) {
            bool ok = false;
            for (auto &c : StrSplit(a.choices, '|')) if (c == v->values[0]) ok = true;
            if (!ok) {
                errs.push_back("Invalid value '" + v->values[0] + "' for string argument '" + a.name +
                               "'. Should be one among '" + StrJoin(StrSplit(a.choices, '|'), "', '") + "'.");
            }
        }
        if (a.type == "integer" || a.type == "real") {
            double d;
            if (!ParseDouble(v->values.back(), d)) {
                errs.push_back("Invalid value '" + v->values.back() + "' for argument '" + a.name + "'.");
            } else {
                if (!a.minValue.empty()) {
                    double mn; ParseDouble(a.minValue, mn);
                    if (a.minIncl == "1" ? (d < mn) : (d <= mn)) {
                        errs.push_back("Invalid value for '" + a.name + "' argument. Should be between " +
                                       a.minValue + " and " + (a.maxValue.empty() ? "0" : a.maxValue));
                    }
                }
                if (!a.maxValue.empty()) {
                    double mx; ParseDouble(a.maxValue, mx);
                    if (a.maxIncl == "1" ? (d > mx) : (d >= mx)) {
                        errs.push_back("Invalid value for '" + a.name + "' argument. Should be between " +
                                       a.minValue + " and " + a.maxValue);
                    }
                }
            }
        }
    }
    /* mutual exclusion */
    {
        std::map<std::string, std::vector<const ArgDef *>> groups;
        for (auto &a : alg.cmd->args) if (!a.excl.empty()) groups[a.excl].push_back(&a);
        for (auto &kv : groups) {
            int n = 0;
            std::string first;
            for (auto *a : kv.second) {
                AlgValue *v = alg.val(a->name);
                if (v && v->isSet) { n++; if (n == 1) first = a->name; }
            }
            if (n > 1) {
                errs.push_back("Only one of '" + first + "' and others of the mutual exclusion group can be specified");
            }
        }
    }
    if (!errs.empty()) {
        for (auto &e : errs) CPLLError(5, e);
        fputs(RenderUsageForError(alg.cmd).c_str(), stderr);
        fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
        return -1;
    }
    return rc;
}
CEOF
echo ok"}

