int ValidateArgs(Alg &alg)
{
    int rc = 0;
    std::vector<std::string> errs;
    for (auto &a : alg.cmd->args) {
        AlgValue *v = alg.val(a.name);
        if (!v) continue;
        if (a.isRequired() && v->values.empty() && a.def.empty()) {
            errs.push_back("Required argument '" + a.name + "' has not been specified.");
            continue;
        }
        if (v->values.empty()) continue;
        long long minc = a.minCount.empty() ? 1 : atoll(a.minCount.c_str());
        long long maxc = a.maxCount.empty() ? 1 : atoll(a.maxCount.c_str());
        if (a.isList()) {
            if ((long long)v->values.size() < minc) {
                errs.push_back(StrJoin(std::vector<std::string>{a.name}, "") + ": " +
                               std::to_string(v->values.size()) + " values have been specified for argument '" +
                               a.name + "', whereas at least " + std::to_string(minc) + " was expected.");
            }
            if (maxc != 2147483647 && (long long)v->values.size() > maxc) {
                errs.push_back(std::to_string(v->values.size()) + " values have been specified for argument '" +
                               a.name + "', whereas at most " + std::to_string(maxc) + " was expected.");
            }
        }
        /* choices */
        if (!a.choices.empty() && v->values.size() == 1) {
            bool ok = false;
            for (auto &c : StrSplit(a.choices, '|')) if (c == v->values[0]) ok = true;
            if (!ok) {
                errs.push_back("Invalid value '" + v->values[0] + "' for string argument '" + a.name +
                               "'. Should be one among '" + StrJoin(StrSplit(a.choices, '|'), "', '") + "'.");
            }
        }
        if (a.type == "integer" || a.type == "real") {
            double d;
            if (!ParseDouble(v->values.back(), d)) {
                errs.push_back("Invalid value '" + v->values.back() + "' for argument '" + a.name + "'.");
            } else {
                if (!a.minValue.empty()) {
                    double mn; ParseDouble(a.minValue, mn);
                    if (a.minIncl == "1" ? (d < mn) : (d <= mn)) {
                        errs.push_back("Invalid value for '" + a.name + "' argument. Should be between " +
                                       a.minValue + " and " + (a.maxValue.empty() ? "0" : a.maxValue));
                    }
                }
                if (!a.maxValue.empty()) {
                    double mx; ParseDouble(a.maxValue, mx);
                    if (a.maxIncl == "1" ? (d > mx) : (d >= mx)) {
                        errs.push_back("Invalid value for '" + a.name + "' argument. Should be between " +
                                       a.minValue + " and " + a.maxValue);
                    }
                }
            }
        }
    }
    /* mutual exclusion */
    {
        std::map<std::string, std::vector<const ArgDef *>> groups;
        for (auto &a : alg.cmd->args) if (!a.excl.empty()) groups[a.excl].push_back(&a);
        for (auto &kv : groups) {
            int n = 0;
            std::string first;
            for (auto *a : kv.second) {
                AlgValue *v = alg.val(a->name);
                if (v && v->isSet) { n++; if (n == 1) first = a->name; }
            }
            if (n > 1) {
                errs.push_back("Only one of '" + first + "' and others of the mutual exclusion group can be specified");
            }
        }
    }
    if (!errs.empty()) {
        for (auto &e : errs) CPLLError(5, e);
        fputs(RenderUsageForError(alg.cmd).c_str(), stderr);
        fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
        return -1;
    }
    return rc;
}
