#include "cli.h"
#include "spec.h"
#include "port.h"
#include "commands.h"

#include <cstdio>
#include <cstring>
#include <algorithm>

const char *const* kDriverLists[] = {nullptr, nullptr, nullptr, nullptr, nullptr};
#include "drivers_data.inc"

static std::string JoinArgs(int argc, char **argv, int from)
{
    std::vector<std::string> v;
    for (int i = from; i < argc; ++i) v.push_back(argv[i]);
    return StrJoin(v, " ");
}

static int FindInList(const char *const *l, int idx)
{
    (void)idx;
    return l ? 1 : 0;
}

/* Emit the driver listing as JSON */
static void PrintDrivers(int idx)
{
    if (!kDriverLists[idx]) { CPLLError(1, "driver list not available"); return; }
    for (int i = 0; kDriverLists[idx][i]; ++i) fputs(kDriverLists[idx][i], stdout);
    fputs("\n", stdout);
}

static bool IsKnownCommand(const std::string &n)
{
    CmdDef *r = SpecRoot();
    if (n == "info" || n == "convert") return true;
    for (auto &c : r->childNames()) if (c == n) return true;
    return false;
}

/* ------------------------------------------------------------------ */
/* Main dispatch                                                       */
/* ------------------------------------------------------------------ */
static int RunLeaf(CmdDef *c, const std::vector<std::string> &args, bool aliasPath);

static int RunWithChildren(CmdDef *c, const std::vector<std::string> &args)
{
    /* find the sub command among args */
    std::string sub;
    size_t idx = 0;
    for (size_t i = 0; i < args.size(); ++i) {
        const std::string &t = args[i];
        if (t == "-h" || t == "--help") {
            HelpFor(c);
            return 0;
        }
        if (t == "--json-usage") {
            TmsWarnFor(c, true);
            fputs(RenderJsonUsage(c, c->isRoot()).c_str(), stdout);
            fputs("\n", stdout);
            return 0;
        }
        if (t == "--config") { if (i + 1 < args.size()) { HandleConfig(args[i + 1]); i++; } continue; }
        if (t.size() > 1 && t[0] == '-') {
            if (t[1] == '-') {
                if (c->isRoot() && t == "--version") { printf("GDAL %s, released %s\n", GDAL_VERSION, GDAL_RELEASE_DATE); return 0; }
                if (c->isRoot() && t == "--drivers") { TmsWarn(1); PrintDrivers(0); return 0; }
                ReportParentError(c, "Option '" + t + "' is unknown.");
                return 1;
            }
            ReportParentError(c, std::string("Short name option '") + t.substr(1) + "' is unknown.");
            return 1;
        }
        sub = t;
        idx = i;
        break;
    }
    if (sub.empty()) {
        if (c->isRoot()) { HelpFor(c); return 0; }
        ReportParentError(c, "No sub-command has been specified.");
        return 1;
    }
    /* match against child names and aliases */
    std::string childName;
    for (auto &n : c->childNames()) if (n == sub) { childName = n; break; }
    if (childName.empty()) {
        /* alias lookup */
        for (auto &si : c->subInfos) {
            std::string d = si.desc;
            size_t q = d.find(" (alias: ");
            if (q == std::string::npos) continue;
            std::string al = d.substr(q + 9);
            if (StrEndsWith(al, ")")) al = al.substr(0, al.size() - 1);
