cat > /workspace/src/commands.cpp <<'CEOF'
#include "commands.h"
#include "cli.h"
#include "spec.h"
#include "port.h"

#include <cstdio>

void HelpFor(CmdDef *c) { fputs(RenderHelp(c).c_str(), stdout); }

void TmsWarnFor(CmdDef *c, bool jsonMode)
{
    std::string p = c->path;
    if (p == "raster") TmsWarn(jsonMode ? 2 : 1);
    else if (p == "pipeline" || p == "raster/pipeline") TmsWarn(jsonMode ? 1 : 4);
}

void HandleConfig(const std::string &kv)
{
    size_t q = kv.find('=');
    if (q == std::string::npos) {
        CPLSetConfigOption(kv, "YES");
        return;
    }
    CPLSetConfigOption(kv.substr(0, q), kv.substr(q + 1));
}

void ReportCmdError(CmdDef *c, int code, const std::string &msg)
{
    CPLLError(code, c->name + ": " + msg);
    if (c->path == "raster") TmsWarn(1);
    fputs(RenderUsageForError(c).c_str(), stderr);
