import json,re
d=json.load(open('usage.json'))
def get(path):
    n=d
    for k in path: n=[x for x in n['sub_algorithms'] if x['name']==k][0]
    return n
n=get(['raster','info'])
lines=open('help/raster_info.txt').read().split('\n')
jargs={a['name']:a for a in n.get('input_arguments',[])+n.get('output_arguments',[])}
s=lines.index('Positional arguments:'); e=[k for k,L in enumerate(lines) if L.startswith('For more details')][0]
C=0
for L in lines[s:e]:
    if L.startswith('  '):
        j=L.find("  ",2)
        if j>=0: C=max(C, j+2)
print('C',C,'range',s,e)
matched=set()
for L in lines[4:e]:
    if L=='' or not L.startswith('  '): continue
    if C and L[:C].strip()=='': continue
    ns=L[2:C-2].rstrip(); dd=L[C:]
    metav=None
    for a in jargs.values():
        mv=a.get('metavar')
        if mv and ns.endswith(' '+mv):
            metav=mv; ns=ns[:len(ns)-len(mv)-1]; break
    names=[x.lstrip('-') for x in ns.split(', ')]
    ja=None
    for nn in names:
        if nn in jargs: ja=jargs[nn]; break
    if ja: matched.add(ja['name'])
    print(repr(ns), names, metav, ja['name'] if ja else 'NOTFOUND', repr(dd[:40]))
print('unmatched', set(jargs)-matched)
