function.arguments:
{"command": "cd /workspace/src && python3 - <<'PYEOF'
s=open('spec.cpp').read()
a=s.index("std::string RenderJsonUsage(CmdDef *c, bool top)")
new = '''std::string RenderJsonUsage(CmdDef *c, bool top, int base)
{
    std::string pad(base, ' ');
    std::string in(base + 2, ' ');
    std::string el(base + 4, ' ');
    std::string out = pad + "{\\n";
    if (!top) {
        out += in + "\\"name\\":\\"" + JsonEscape(c->name) + "\\",\\n";
        out += in + "\\"full_path\\":[\\n";
        out += el + "\\"gdal\\",\\n";
        for (auto &t : StrSplit(c->path, '/')) out += el + "\\"" + JsonEscape(t) + "\\",\\n";
        out = out.substr(0, out.size() - 2) + "\\n";
        out += in + "],\\n";
    }
    out += in + "\\"description\\":\\"" + JsonEscape(c->desc) + "\\",\\n";
    if (!c->shortUrl.empty()) out += in + "\\"short_url\\":\\"" + JsonEscape(c->shortUrl) + "\\",\\n";
    if (!c->url.empty()) out += in + "\\"url\\":\\"" + JsonEscape(c->url) + "\\",\\n";
    out += in + "\\"sub_algorithms\\":[\\n";
    for (auto &n : c->childNames()) {
        std::string p = c->path.empty() ? n : c->path + "/" + n;
        CmdDef *ch = SpecFind(p);
        if (!ch) continue;
        out += RenderJsonUsage(ch, false, base + 4) + ",\\n";
    }
    if (out.size() >= 2 && out[out.size() - 2] == ',') out = out.substr(0, out.size() - 2) + "\\n";
    out += in + "],\\n";
    auto emitList = [&](const char *title, const std::string &names) {
        out += in + "\\"" + title + "\\": [\\n";
        out = out.substr(0, out.size() - 2) + "[\\n";
        std::vector<const ArgDef *> sel;
        for (auto &n : StrSplit(names, ',')) {
            if (n.empty()) continue;
            ArgDef *a = c->findArg(n);
            if (a) sel.push_back(a);
        }
        for (auto *a : sel) {
            out += el + "{\\n" + RenderArgJson(*a, base + 6) + "\\n" + el + "},\\n";
        }
        if (!sel.empty()) out = out.substr(0, out.size() - 2) + "\\n";
        out += in + "],\\n";
    };
    emitList("input_arguments", c->ia);
    emitList("output_arguments", c->oa);
    emitList("input_output_arguments", c->ioa);
    if (out.size() >= 2 && out[out.size() - 2] == ',') out = out.substr(0, out.size() - 2) + "\\n";
    if (c->supportsStreamed == "1") out += in + "\\"supports_streamed_output\\":true\\n";
    else if (out.size() >= 2 && out[out.size() - 2] == ',') out = out.substr(0, out.size() - 2) + "\\n";
    out += pad + "}";
    return out;
}
'''
s=s[:a]+new+s[a:]
s=s.replace("std::string RenderArgJson(const ArgDef &a, int base)","std::string RenderArgJson(const ArgDef &a, int base)")
open('spec.cpp','w').write(s)
h=open('spec.h').read()
h=h.replace("std::string RenderJsonUsage(CmdDef *c, bool top);","std::string RenderJsonUsage(CmdDef *c, bool top, int base = 0);")
open('spec.h','w').write(h)
PYEOF
cd /workspace && g++ -std=c++17 -O1 -I src -o /tmp/toolj src/spec.cpp src/port.cpp /tmp/toolj.cpp -w 2>&1|head -5; cd /tmp && diff <(/tmp/toolj "dataset") <(/workspace/executable dataset --json-usage 2>/dev/null) | head -10; echo "=== aspect"; diff <(/tmp/toolj "raster aspect") <(/workspace/executable raster aspect --json-usage 2>/dev/null) | head -20"}

