static std::string RenderStepHelp(const StepDef &st, int col, const std::string &name)
{
    std::string out = "* " + name + " " + stSuffixOf(st) + "\\n";
    out += std::string(out.size() - 1, '-') + "\\n\\n";
    out += st.desc + "\\n\\n";
    /* sections in declaration order */
    std::vector<std::string> order;
    for (auto &a : st.args) {
        std::string sec = SectionOf(a);
        if (std::find(order.begin(), order.end(), sec) == order.end()) order.push_back(sec);
    }
    auto rankOf = [&](const std::string &sec) {
        if (sec == "Positional arguments") return 0;
        if (sec == "Common Options") return 1;
        if (sec == "Options") return 2;
        if (sec == "Advanced Options") return 3;
        if (sec == "Esoteric Options") return 1000;
        for (size_t k = 0; k < order.size(); ++k) if (order[k] == sec) return (int)(100 + k);
        return 999;
    };
    std::sort(order.begin(), order.end(), [&](const std::string &x, const std::string &y) { return rankOf(x) < rankOf(y); });
    for (auto &sec : order) {
        std::vector<const ArgDef *> v;
        for (auto &a : st.args) if (SectionOf(a) == sec && !a.names.empty()) v.push_back(&a);
        if (v.empty()) continue;
        out += sec + ":\\n";
