{"command": "cd /tmp && python3 - <<'EOF'
lines=open('help/raster_pipeline.txt').read().split('\n')
starts=[k for k in range(lines.index('Potential steps are:'),len(lines)) if lines[k].startswith('* ')]
starts.append(len(lines))
for a,b in zip(starts[:-1],starts[1:]):
    name=lines[a].split()[1]
    blk=lines[a:b]
    if 'Positional arguments:' in blk:
        j=blk.index('Positional arguments:')
        has=False
        for L in blk[j+1:]:
            if L.strip()=='' : break
            if not L.startswith('  '): break
            has=True
        if not has: print('EMPTY', name, lines[a])
    else:
        print('NOPOS', name, lines[a])
EOF"}

