/* Core GDAL-like data model: raster datasets/bands, vector layers/features,
 * geometry and coordinate reference systems. */
#ifndef GDAL_GDAL_H
#define GDAL_GDAL_H

#include "port.h"

/* ---------------- raster ---------------- */
enum GDataType {
    GDT_Unknown = 0, GDT_Byte, GDT_Int8, GDT_UInt16, GDT_Int16, GDT_UInt32,
    GDT_Int32, GDT_UInt64, GDT_Int64, GDT_Float16, GDT_Float32, GDT_Float64,
    GDT_CInt16, GDT_CInt32, GDT_CFloat32, GDT_CFloat64
};
const char *DataTypeName(GDataType t);
int DataTypeSize(GDataType t);
GDataType DataTypeFromName(const std::string &n);

enum ColorInterp {
    GCI_Undefined, GCI_Gray, GCI_Palette, GCI_Red, GCI_Green, GCI_Blue, GCI_Alpha,
    GCI_Hue, GCI_Saturation, GCI_Lightness, GCI_Cyan, GCI_Magenta, GCI_Yellow, GCI_Black
};
const char *ColorInterpName(ColorInterp c);
ColorInterp ColorInterpFromName(const std::string &n);

struct ColorEntry { int value; int r, g, b, a; bool hasAlpha; };

struct Overview {
    int xSize = 0, ySize = 0;
    std::vector<std::vector<unsigned char> > data;  /* per band, raw bytes */
    GDataType type = GDT_Byte;
};

struct RasterBand {
    GDataType type = GDT_Byte;
    int blockX = 0, blockY = 0;
    bool noDataSet = false;
    double nodata = 0.0;
    ColorInterp interp = GCI_Undefined;
    std::map<std::string, std::string> metadata;   /* IMAGE_STRUCTURE etc. */
    std::vector<ColorEntry> colorTable;
    bool hasColorTable = false;
    std::vector<unsigned char> data;               /* raw bytes, row major */
    double scale = 1.0, offset = 0.0;
    bool hasScale = false, hasOffset = false;
    std::string unitType;
    std::vector<Overview> overviews;
    std::vector<std::string> categoryNames;
    int maskFlags = 0;                             /* 0 none, 1 all valid, 2 nodata mask */

    size_t ValueCount() const { return data.size() / (size_t)DataTypeSize(type); }
    double GetValue(size_t i) const;
    void SetValue(size_t i, double v);
};

struct GNMEdge { /* placeholder for geographic network datasets */ };

struct GDALDataset {
    std::string driverShort, driverLong;
    std::string name;
    std::vector<std::string> files;
    int nx = 0, ny = 0, nbands = 0;
    double geoTransform[6] = {0, 1, 0, 0, 0, 1};
    bool hasGeoTransform = false;
    std::string srsWkt;             /* WKT2 of the CRS */
    std::map<std::string, std::map<std::string, std::string> > metadata;
    std::vector<RasterBand> bands;
    std::vector<std::string> subdatasetNames;
    bool updateMode = false;

    /* multidimensional */
    bool isMultiDim = false;
    struct Dim { std::string name; GIntBig size = 0; std::string type; std::string unit; };
    std::vector<Dim> dims;
    struct MDArray {
        std::string name;
        std::vector<std::string> dimNames;
        std::vector<GIntBig> dimSizes;
        GDataType type = GDT_Float64;
        bool noDataSet = false;
        double nodata = 0.0;
        std::string srsWkt;
        std::map<std::string, std::string> attrs;
        std::vector<unsigned char> data;
    };
    std::vector<MDArray> arrays;
    struct Group { std::string name; std::vector<std::string> arrayNames; std::vector<std::string> groupNames; };
    std::vector<Group> groups;

    double *GetGeoTransform() { return hasGeoTransform ? geoTransform : nullptr; }
    bool IsRaster() const { return nbands > 0 || (nx > 0 && ny > 0); }
};

/* ---------------- vector ---------------- */
enum OFieldType {
    OFT_None = 0, OFT_Integer, OFT_Integer64, OFT_Real, OFT_String, OFT_Date,
    OFT_Time, OFT_DateTime, OFT_IntegerList, OFT_Integer64List, OFT_RealList,
    OFT_StringList, OFT_Binary
};
const char *FieldTypeName(OFIELDTYPE t);
OFIELDTYPE FieldTypeFromName(const std::string &n);

struct FieldDef {
    std::string name;
    OFIELDTYPE type = OFT_String;
    std::string subtype;
    int width = 0, precision = 0;
    std::string justification;
    std::string unique;
    std::string defaultValue;
    bool nullable = true;
};

struct Value {
    bool isNull = true;
    std::string s;
    double d = 0;
    long long i = 0;
};

struct Geometry {
    std::string type = "UNKNOWN";   /* POINT, LINESTRING, ... */
    std::vector<std::vector<double> > pts;  /* flat coords: x,y[,z][,m] */
    int dims = 2;                   /* 2, 3 (xyz) or 4 (xyzm) */
    std::vector<Geometry> parts;
    bool IsEmpty() const { return pts.empty() && parts.empty(); }
    void AddPoint(double x, double y, double z = 0, double m = 0);
    void Bounds(double &minx, double &miny, double &maxx, double &maxy) const;
    void TransformCoords(const std::function<void(double &, double &)> &f);
    std::string ToWkt() const;
};

struct Feature {
    long long fid = 0;
    std::string geomField;         /* name of the geometry field, "" for default */
    Geometry geom;
    std::vector<Value> values;
};

struct Layer {
    std::string name;
    std::string geomType = "Unknown";
    bool hasGeom = true;
    std::vector<FieldDef> fields;
    std::string srsWkt;
    std::vector<Feature> features;
    std::map<std::string, std::string> metadata;
    std::string geomFieldName;
    int fidCount = 0;
    bool hasFeatureCount = true;
    bool isOrdered = false;
    std::map<std::string, std::string> geomFieldMetadata;
    std::string defaultGeomFieldName;
};

struct VectorDataset {
    std::string driverShort, driverLong;
    std::string name;
    std::vector<std::string> files;
    std::vector<Layer> layers;
    std::map<std::string, std::map<std::string, std::string> > metadata;
    bool updateMode = false;
};

/* ---------------- CRS ---------------- */
struct CRS {
    bool valid = false;
    std::string wkt;          /* WKT2 */
    std::string name;
    std::string authority;    /* EPSG */
    long long code = 0;
    std::string type;         /* Geographic 2D, Projected, ... */
    std::string proj4;        /* proj parameters */
    bool isGeographic = false;
    std::string areaOfUse;
    std::vector<int> axisMapping;

    void SetFromEpsg(long long c);
    static CRS FromUserInput(const std::string &s);
    bool IsSame(const CRS &o) const;
    bool TransformTo(const CRS &dst, double &x, double &y) const;
    std::string ProjJson() const;
    std::string Wkt() const { return wkt; }
};

/* dataset open / create */
GDALDataset *OpenRaster(const std::string &name, bool update, const std::vector<std::string> &openOptions,
                        std::vector<std::string> *filesOut = nullptr);
VectorDataset *OpenVector(const std::string &name, bool update, const std::vector<std::string> &openOptions,
                          std::vector<std::string> *filesOut = nullptr);
std::string IdentifyDriver(const std::string &name, std::vector<std::string> &files);
GDALDataset *CreateRaster(const std::string &name, const std::string &format, int nx, int ny, int nb,
                          GDataType type, const std::vector<std::string> &co);
VectorDataset *CreateVector(const std::string &name, const std::string &format,
                            const std::vector<std::string> &co, const std::vector<std::string> &lco);
void WriteRaster(GDALDataset *ds);
void WriteVector(VectorDataset *ds);

/* helpers */
std::string WktFromGeometry(const Geometry &g);
bool GeometryFromWkt(const std::string &wkt, Geometry &g);
std::string GeometryToJson(const Geometry &g);
bool GeometryFromJson(const std::string &txt, Geometry &g);
void CopyRasterData(GDALDataset *src, GDALDataset *dst, const std::string &resampling);
std::string DblStr(double v);
double StrDbl(const std::string &s, double dflt);
std::string FormatCoord(double v, int prec = 7);

#endif
EOF
echo ok"}

