static double ClampToType(GDataType t, double v)
{
    switch (t) {
        case GDT_Byte: if (v < 0) return 0; if (v > 255) return 255; return floor(v + 0.5);
        case GDT_Int8: if (v < -128) return -128; if (v > 127) return 127; return floor(v + 0.5);
        case GDT_UInt16: if (v < 0) return 0; if (v > 65535) return 65535; return floor(v + 0.5);
        case GDT_Int16: if (v < -32768) return -32768; if (v > 32767) return 32767; return floor(v + 0.5);
        case GDT_UInt32: if (v < 0) return 0; if (v > 4294967295.0) return 4294967295.0; return floor(v + 0.5);
        case GDT_Int32: if (v < -2147483648.0) return -2147483648.0; if (v > 2147483647.0) return 2147483647.0; return floor(v + 0.5);
        default: return v;
    }
}

double RasterBand::GetValue(size_t i) const
{
    size_t sz = (size_t)DataTypeSize(type);
    if (i * sz + sz > data.size()) return 0;
    const unsigned char *p = &data[i * sz];
    switch (type) {
        case GDT_Byte: return (double)p[0];
        case GDT_Int8: return (double)*(int8_t *)p;
        case GDT_UInt16: return (double)*(uint16_t *)p;
        case GDT_Int16: return (double)*(int16_t *)p;
        case GDT_UInt32: return (double)*(uint32_t *)p;
        case GDT_Int32: return (double)*(int32_t *)p;
        case GDT_UInt64: return (double)*(uint64_t *)p;
        case GDT_Int64: return (double)*(int64_t *)p;
        case GDT_Float16: {
            uint16_t h = *(uint16_t *)p;
            int sign = (h >> 15) & 1, exp = (h >> 10) & 0x1f, man = h & 0x3ff;
            double v;
            if (exp == 0) v = ldexp((double)man, -24);
            else if (exp == 31) v = man ? NAN : INFINITY;
            else v = ldexp((double)man + 1024.0, exp - 25);
            return sign ? -v : v;
        }
        case GDT_Float32: { float f; memcpy(&f, p, 4); return (double)f; }
        case GDT_Float64: { double d; memcpy(&d, p, 8); return d; }
        case GDT_CInt16: { int16_t re, im; memcpy(&re, p, 2); memcpy(&im, p + 2, 2); return (double)re; }
        case GDT_CInt32: { int32_t re, im; memcpy(&re, p, 4); memcpy(&im, p + 4, 4); return (double)re; }
        case GDT_CFloat32: { float re, im; memcpy(&re, p, 4); memcpy(&im, p + 4, 4); return (double)re; }
        case GDT_CFloat64: { double re, im; memcpy(&re, p, 8); memcpy(&im, p + 8, 8); return re; }
        default: return 0;
    }
}

void RasterBand::SetValue(size_t i, double v)
{
    size_t sz = (size_t)DataTypeSize(type);
    if (i * sz + sz > data.size()) return;
    unsigned char *p = &data[i * sz];
    v = ClampToType(type, v);
    switch (type) {
        case GDT_Byte: p[0] = (unsigned char)v; break;
        case GDT_Int8: *(int8_t *)p = (int8_t)v; break;
        case GDT_UInt16: *(uint16_t *)p = (uint16_t)v; break;
        case GDT_Int16: *(int16_t *)p = (int16_t)v; break;
        case GDT_UInt32: *(uint32_t *)p = (uint32_t)v; break;
        case GDT_Int32: *(int32_t *)p = (int32_t)v; break;
        case GDT_UInt64: *(uint64_t *)p = (uint64_t)v; break;
        case GDT_Int64: *(int64_t *)p = (int64_t)v; break;
        case GDT_Float16: {
            uint16_t h = 0;
            if (std::isnan(v)) h = 0x7e00;
            else {
                int sign = v < 0 ? 1 : 0;
                double a = std::fabs(v);
                if (std::isinf(a)) h = (uint16_t)((sign << 15) | 0x7c00);
                else {
                    int e;
                    double m = std::frexp(a, &e);
                    e += 14;
                    if (e > 15) h = (uint16_t)((sign << 15) | 0x7c00);
                    else if (e < -14) h = (uint16_t)(sign << 15);
                    else {
                        uint32_t man = (uint32_t)((m - 0.5) * 2048.0);
                        h = (uint16_t)((sign << 15) | ((e + 15) << 10) | man);
                    }
                }
            }
            *(uint16_t *)p = h;
            break;
        }
        case GDT_Float32: { float f = (float)v; memcpy(p, &f, 4); break; }
        case GDT_Float64: { double d = v; memcpy(p, &d, 8); break; }
        case GDT_CInt16: { int16_t re = (int16_t)v, im = 0; memcpy(p, &re, 2); memcpy(p + 2, &im, 2); break; }
        case GDT_CInt32: { int32_t re = (int32_t)v, im = 0; memcpy(p, &re, 4); memcpy(p + 4, &im, 4); break; }
        case GDT_CFloat32: { float re = (float)v, im = 0; memcpy(p, &re, 4); memcpy(p + 4, &im, 4); break; }
        case GDT_CFloat64: { double re = v, im = 0; memcpy(p, &re, 8); memcpy(p + 8, &im, 8); break; }
        default: break;
    }
}

