double RasterBand::GetValue(size_t i) const
{
    size_t sz = (size_t)DataTypeSize(type);
    if (i * sz + sz > data.size()) return 0;
    const unsigned char *p = &data[i * sz];
    switch (type) {
        case GDT_Byte: return (double)p[0];
        case GDT_Int8: return (double)*(int8_t *)p;
        case GDT_UInt16: return (double)*(uint16_t *)p;
        case GDT_Int16: return (double)*(int16_t *)p;
        case GDT_UInt32: return (double)*(uint32_t *)p;
        case GDT_Int32: return (double)*(int32_t *)p;
        case GDT_UInt64: return (double)*(uint64_t *)p;
        case GDT_Int64: return (double)*(int64_t *)p;
        case GDT_Float16: {
            uint16_t h = *(uint16_t *)p;
            int sign = (h >> 15) & 1, exp = (h >> 10) & 0x1f, man = h & 0x3ff;
            double v;
            if (exp == 0) v = ldexp((double)man, -24);
            else if (exp == 31) v = man ? NAN : INFINITY;
            else v = ldexp((double)man + 1024.0, exp - 25);
            return sign ? -v : v;
        }
        case GDT_Float32: { float f; memcpy(&f, p, 4); return (double)f; }
        case GDT_Float64: { double d; memcpy(&d, p, 8); return d; }
        case GDT_CInt16: { int16_t re, im; memcpy(&re, p, 2); memcpy(&im, p + 2, 2); return (double)re; }
