void Geometry::AddPoint(double x, double y, double z, double m)
{
    std::vector<double> p;
    p.push_back(x); p.push_back(y);
    if (dims >= 3) p.push_back(z);
    if (dims >= 4) p.push_back(m);
    pts.push_back(p);
}

void Geometry::Bounds(double &minx, double &miny, double &maxx, double &maxy) const
{
    minx = miny = std::numeric_limits<double>::infinity();
    maxx = maxy = -std::numeric_limits<double>::infinity();
    auto upd = [&](double x, double y) {
        if (x < minx) minx = x;
        if (y < miny) miny = y;
        if (x > maxx) maxx = x;
        if (y > maxy) maxy = y;
    };
    for (auto &p : pts) upd(p[0], p[1]);
    for (auto &q : parts) q.Bounds(minx, miny, maxx, maxy);
    if (minx > maxx) { minx = miny = maxx = maxy = 0; }
}

void Geometry::TransformCoords(const std::function<void(double &, double &)> &f)
{
    for (auto &p : pts) f(p[0], p[1]);
    for (auto &q : parts) q.TransformCoords(f);
}

static std::string DblWkt(double v)
{
    if (std::isnan(v)) return "nan";
    if (std::isinf(v)) return v > 0 ? "inf" : "-inf";
    char buf[64];
    snprintf(buf, sizeof(buf), "%.20g", v);
    return std::string(buf);
}

static void AppendWkt(const Geometry &g, std::string &out)
{
    std::string t = g.type;
    if (t == "UNKNOWN" || t.empty()) { out += "GEOMETRYCOLLECTION EMPTY"; return; }
    ToUpperIn(t);
    if (!g.parts.empty()) {
        out += t + " (";
        for (size_t i = 0; i < g.parts.size(); ++i) {
            if (i) out += ",";
            AppendWkt(g.parts[i], out);
        }
        out += ")";
        return;
    }
    out += t;
    if (g.pts.empty()) { out += " EMPTY"; return; }
    out += " (";
    for (size_t i = 0; i < g.pts.size(); ++i) {
        if (i) out += ", ";
        out += DblWkt(g.pts[i][0]) + " " + DblWkt(g.pts[i][1]);
        for (int k = 2; k < (int)g.pts[i].size(); ++k) out += " " + DblWkt(g.pts[i][k]);
    }
    out += ")";
}

std::string WktFromGeometry(const Geometry &g)
{
    std::string out;
    AppendWkt(g, out);
    return out;
}

/* --- WKT parsing --- */
struct WktLexer {
    const char *p;
    WktLexer(const std::string &s) : p(s.c_str()) {}
    void SkipWs() { while (*p && isspace((unsigned char)*p)) ++p; }
    std::string Word()
    {
        SkipWs();
        const char *st = p;
        while (*p && (isalpha((unsigned char)*p) || isdigit((unsigned char)*p) || *p == '_')) ++p;
        return std::string(st, p);
    }
    bool Accept(char c) { SkipWs(); if (*p == c) { ++p; return true; } return false; }
    bool Done() { SkipWs(); return *p == '\0'; }
    bool Number(double &v)
    {
        SkipWs();
        char *end = nullptr;
        double d = strtod(p, &end);
        if (end == p) return false;
        v = d; p = end;
        return true;
    }
};

static bool ParseWktGeom(WktLexer &lx, Geometry &g);

static bool ParseCoordSeq(WktLexer &lx, Geometry &g)
{
    if (lx.Accept('E') || lx.Accept('e')) {
        /* EMPTY */
        lx.Accept('M'); lx.Accept('P'); lx.Accept('T'); lx.Accept('Y');
        return true;
    }
    lx.SkipWs();
    if (lx.Accept('E')) { /* already handled */ }
    if (!lx.Accept('(')) {
        /* maybe EMPTY */
        return false;
    }
    while (true) {
        double c[4] = {0, 0, 0, 0};
        int n = 0;
        while (n < 4 && lx.Number(c[n])) n++;
        if (n >= 2) {
            g.dims = n > g.dims ? n : g.dims;
            g.pts.push_back(std::vector<double>(c, c + n));
        }
        if (lx.Accept(',')) continue;
        lx.Accept(')');
        break;
    }
    return true;
}

static bool ParseWktGeom(WktLexer &lx, Geometry &g)
{
    std::string w = lx.Word();
    if (w.empty()) return false;
    std::string u = ToUpper(w);
    if (u == "SRID" ) { lx.Accept('='); double d; lx.Number(d); return ParseWktGeom(lx, g); }
    if (u == "EMPTY") { g.type = "UNKNOWN"; return true; }
    g.type = u;
    lx.SkipWs();
    if (lx.Accept('M')) { /* M suffix */ }
    lx.SkipWs();
    if (lx.Accept('(')) {
        /* possibly nested */
        if (u == "GEOMETRYCOLLECTION") {
            if (lx.Accept(')')) return true;
            while (true) {
                Geometry sub;
                if (!ParseWktGeom(lx, sub)) break;
                g.parts.push_back(sub);
                if (lx.Accept(',')) continue;
                lx.Accept(')');
                break;
            }
            return true;
        }
        if (u == "POINT" || u == "LINESTRING" || u == "LINEARRING" || u == "CIRCULARSTRING") {
            if (lx.Accept(')')) return true;
            while (true) {
                double c[4] = {0, 0, 0, 0};
                int n = 0;
                while (n < 4 && lx.Number(c[n])) n++;
                if (n >= 2) {
                    if (n > g.dims) g.dims = n;
                    g.pts.push_back(std::vector<double>(c, c + n));
                }
                if (lx.Accept(',')) continue;
                lx.Accept(')');
                break;
            }
            return true;
        }
        /* MULTIPOINT */
        if (u == "MULTIPOINT") {
            if (lx.Accept(')')) return true;
            while (true) {
                Geometry sub;
                sub.type = "POINT";
                sub.dims = g.dims;
                if (lx.Accept('(')) {
                    double c[4] = {0, 0, 0, 0};
                    int n = 0;
                    while (n < 4 && lx.Number(c[n])) n++;
                    if (n >= 2) { if (n > sub.dims) sub.dims = n; sub.pts.push_back(std::vector<double>(c, c + n)); }
                    lx.Accept(')');
                } else {
                    double c[4] = {0, 0, 0, 0};
                    int n = 0;
                    while (n < 4 && lx.Number(c[n])) n++;
                    if (n >= 2) { if (n > sub.dims) sub.dims = n; sub.pts.push_back(std::vector<double>(c, c + n)); }
                }
                g.parts.push_back(sub);
                if (lx.Accept(',')) continue;
                lx.Accept(')');
                break;
            }
            return true;
        }
        /* POLYGON / MULTILINESTRING / MULTIPOLYGON / others: nested sequences */
        while (true) {
            Geometry sub;
            sub.type = (u == "POLYGON") ? "LINEARRING" : (u == "MULTILINESTRING" ? "LINESTRING" : (u == "MULTIPOLYGON" ? "POLYGON" : u));
            sub.dims = g.dims;
            if (lx.Accept('(')) {
                if (!ParseCoordSeq(lx, sub)) return false;
            } else {
                if (!ParseCoordSeq(lx, sub)) return false;
            }
            g.parts.push_back(sub);
            if (lx.Accept(',')) continue;
            lx.Accept(')');
            break;
        }
        return true;
    }
    lx.SkipWs();
    if (lx.Accept('(')) { lx.SkipWs(); return true; }
    return true;
}

bool GeometryFromWkt(const std::string &wkt, Geometry &g)
{
    if (Trim(wkt).empty()) { g = Geometry(); g.type = "UNKNOWN"; return true; }
    WktLexer lx(Trim(wkt));
    return ParseWktGeom(lx, g);
}

