static const EpsgEntry *FindEpsg(long long code)
{
    if (code >= 32601 && code <= 32660) return nullptr;   /* handled separately */
    for (const EpsgEntry *e = kEpsg; e->name; ++e) if (e->code == code) return e;
    return nullptr;
}

static std::string UtmName(int zone, bool south, const char *base, const char *area)
{
    char buf[256];
    snprintf(buf, sizeof(buf), "%s / UTM zone %d%s", base, zone, south ? "S" : "N");
    return std::string(buf);
}

/* ------------------------------------------------------------------ */
struct Ellipsoid { const char *name; double a; double rf; };
static const Ellipsoid kEll[] = {
    {"WGS 84", 6378137.0, 298.257223563},
    {"GRS80", 6378137.0, 298.257222101},
    {"airy", 6377563.396, 299.3249646},
    {"intl", 6378388.0, 297.0},
    {"clrk66", 6378206.4, 294.9786982},
    {"bessel", 6377397.155, 299.1528128},
    {"sphere", 6370997.0, 0.0},
    {nullptr, 0, 0}
};
static const Ellipsoid *FindEll(const std::string &n)
{
    for (const Ellipsoid *e = kEll; e->name; ++e) if (n == e->name) return e;
    return nullptr;
}

struct ProjParams {
    std::string proj;       /* merc, tmerc, laea, aea, moll, eqc, stere, sinu, cass, robin, cea, utm */
    double lat_0 = 0, lon_0 = 0, lat_1 = 0, lat_2 = 0, lat_ts = 0;
    double x_0 = 0, y_0 = 0, k_0 = 1;
    double a = 6378137.0, rf = 298.257223563;
    bool sphere = false;
    int utmZone = 0;
    bool utmSouth = false;
    std::string datum, ellps, units;
};

static ProjParams ParseProj4(const std::string &s)
{
    ProjParams p;
    if (s.empty()) { p.proj = "longlat"; return p; }
    for (auto &tok : StrSplit(s, ' ')) {
        size_t q = tok.find('=');
        std::string k = (q == std::string::npos) ? tok : tok.substr(0, q);
        std::string v = (q == std::string::npos) ? "" : tok.substr(q + 1);
        if (k[0] == '+') k = k.substr(1);
        if (k == "proj") p.proj = v;
        else if (k == "lat_0") p.lat_0 = StrDbl(v, 0);
        else if (k == "lon_0") p.lon_0 = StrDbl(v, 0);
        else if (k == "lat_1") p.lat_1 = StrDbl(v, 0);
        else if (k == "lat_2") p.lat_2 = StrDbl(v, 0);
        else if (k == "lat_ts") p.lat_ts = StrDbl(v, 0);
        else if (k == "x_0") p.x_0 = StrDbl(v, 0);
        else if (k == "y_0") p.y_0 = StrDbl(v, 0);
        else if (k == "k_0" || k == "k") p.k_0 = StrDbl(v, 1);
        else if (k == "a") p.a = StrDbl(v, 6378137.0);
        else if (k == "rf") p.rf = StrDbl(v, 298.257223563);
        else if (k == "R") { p.a = StrDbl(v, 6378137.0); p.sphere = true; }
        else if (k == "datum") p.datum = v;
        else if (k == "ellps") p.ellps = v;
        else if (k == "units") p.units = v;
        else if (k == "zone") p.utmZone = (int)StrDbl(v, 0);
        else if (k == "south") p.utmSouth = true;
    }
    if (p.proj == "utm") { p.proj = "tmerc"; if (p.utmZone) { p.lon_0 = -183.0 + 6.0 * p.utmZone; p.k_0 = 0.9996; p.x_0 = 500000; p.y_0 = p.utmSouth ? 10000000 : 0; } }
    if (p.proj == "merc") { p.sphere = p.sphere || (p.a == 6378137.0 && p.datum.empty() && p.ellps.empty()); }
    const Ellipsoid *e = FindEll(p.ellps);
    if (e) { p.a = e->a; p.rf = e->rf; }
    if (!p.datum.empty()) {
        if (p.datum == "WGS84") { p.a = 6378137.0; p.rf = 298.257223563; }
        else if (p.datum == "NAD83") { p.a = 6378137.0; p.rf = 298.257222101; }
    }
    return p;
}

static double Deg2Rad(double d) { return d * M_PI / 180.0; }
static double Rad2Deg(double r) { return r * 180.0 / M_PI; }

/* forward/inverse projections between lon/lat (radians) and x/y */
struct PJ {
    ProjParams p;
    double e2 = 0;      /* first eccentricity squared */
    double ep2 = 0;     /* second eccentricity squared */
    double A = 0, B = 0, C = 0, D = 0;
    void Init();
    bool Fwd(double lam, double phi, double &x, double &y) const;
    bool Inv(double x, double y, double &lam, double &phi) const;
};

void PJ::Init()
{
    double f = p.rf > 0 ? 1.0 / p.rf : 0.0;
    e2 = f * (2 - f);
    ep2 = e2 / (1 - e2);
    double phi0 = Deg2Rad(p.lat_0);
    if (p.proj == "laea" || p.proj == "aea" || p.proj == "stere" || p.proj == "ups") {
        double phi1 = Deg2Rad(p.lat_1 ? p.lat_1 : p.lat_0);
        double phi2 = Deg2Rad(p.lat_2 ? p.lat_2 : p.lat_0);
        if (p.proj == "aea") {
            double m1 = cos(phi1) / sqrt(1 - e2 * sin(phi1) * sin(phi1));
            double m2 = cos(phi2) / sqrt(1 - e2 * sin(phi2) * sin(phi2));
            C = (m1 * m1 + p.rf * m2 * m2) / (p.rf + 1);
            if (fabs(m1 - m2) < 1e-9) n = m1;
            else n = (m1 * m1 - m2 * m2) / (m2 * m2 - p.rf * m1 * m1);
            rho0 = p.a * (C - 2 * n * log(tan(M_PI / 4 + asin(sqrt(C)) * 0 /*dummy*/) / 2)) / (2 * n);
        } else {
            double sinphi = sin(phi0);
            n = 1 + e2 * pow(cos(phi0), 4) / (1 - e2);
            C = sqrt((n - 1) / (n - 1 - e2 * sinphi * sinphi)) * cos(phi0);
            double k = sqrt((n - 1) * (1 - e2 * sinphi * sinphi)) / (n * cos(phi0));
            rho0 = k * p.a / n;
        }
        A = 0; B = 0;
    }
}
