static const EpsgEntry *FindEpsg(long long code)
{
    for (const EpsgEntry *e = kEpsg; e->name; ++e) if (e->code == code) return e;
    return nullptr;
}

struct Ellipsoid { const char *name; double a; double rf; };
static const Ellipsoid kEll[] = {
    {"WGS84", 6378137.0, 298.257223563},
    {"GRS80", 6378137.0, 298.257222101},
    {"airy", 6377563.396, 299.3249646},
    {"intl", 6378388.0, 297.0},
    {"clrk66", 6378206.4, 294.9786982},
    {"bessel", 6377397.155, 299.1528128},
    {"sphere", 6370997.0, 0.0},
    {"krss", 6378245.0, 298.3},
    {nullptr, 0, 0}
};
static const Ellipsoid *FindEll(const std::string &n)
{
    for (const Ellipsoid *e = kEll; e->name; ++e) if (n == e->name) return e;
    return nullptr;
}

struct ProjParams {
    std::string proj;
    double lat_0 = 0, lon_0 = 0, lat_1 = 0, lat_2 = 0, lat_ts = 0;
    double x_0 = 0, y_0 = 0, k_0 = 1;
    double a = 6378137.0, rf = 298.257223563;
    bool sphere = false;
    int utmZone = 0;
    bool utmSouth = false;
    std::string datum, ellps, units;
    bool isLongLat = false;
};

static ProjParams ParseProj4(const std::string &s)
{
    ProjParams p;
    p.proj = "longlat";
    p.isLongLat = true;
    if (Trim(s).empty()) return p;
    for (auto &tok : StrSplit(s, ' ')) {
        size_t q = tok.find('=');
        std::string k = (q == std::string::npos) ? tok : tok.substr(0, q);
        std::string v = (q == std::string::npos) ? "" : tok.substr(q + 1);
        if (!k.empty() && k[0] == '+') k = k.substr(1);
        if (k == "proj") { p.proj = v; p.isLongLat = (v == "longlat" || v == "latlong"); }
        else if (k == "lat_0") p.lat_0 = StrDbl(v, 0);
        else if (k == "lon_0") p.lon_0 = StrDbl(v, 0);
        else if (k == "lat_1") p.lat_1 = StrDbl(v, 0);
        else if (k == "lat_2") p.lat_2 = StrDbl(v, 0);
        else if (k == "lat_ts") p.lat_ts = StrDbl(v, 0);
        else if (k == "x_0") p.x_0 = StrDbl(v, 0);
        else if (k == "y_0") p.y_0 = StrDbl(v, 0);
        else if (k == "k_0" || k == "k") p.k_0 = StrDbl(v, 1);
        else if (k == "a") { p.a = StrDbl(v, 6378137.0); p.sphere = true; }
        else if (k == "rf") p.rf = StrDbl(v, 298.257223563);
        else if (k == "R") { p.a = StrDbl(v, 6378137.0); p.sphere = true; }
        else if (k == "datum") p.datum = v;
        else if (k == "ellps") p.ellps = v;
        else if (k == "units") p.units = v;
        else if (k == "zone") p.utmZone = (int)StrDbl(v, 0);
        else if (k == "south") p.utmSouth = true;
    }
    if (p.proj == "utm") {
        p.proj = "tmerc";
        if (p.utmZone) { p.lon_0 = -183.0 + 6.0 * p.utmZone; p.k_0 = 0.9996; p.x_0 = 500000; p.y_0 = p.utmSouth ? 10000000 : 0; }
    }
    if (p.proj == "somerc") p.proj = "tmerc";
    const Ellipsoid *e = FindEll(p.ellps);
    if (e) { p.a = e->a; p.rf = e->rf; }
    if (!p.datum.empty()) {
        if (p.datum == "WGS84") { p.a = 6378137.0; p.rf = 298.257223563; }
        else if (p.datum == "NAD83") { p.a = 6378137.0; p.rf = 298.257222101; }
    }
    if (p.proj == "merc" || p.proj == "moll" || p.proj == "sinu" || p.proj == "cea" ||
        p.proj == "robin" || p.proj == "eqc" || p.proj == "cass") {
        /* spherical unless an ellipsoid was requested */
        if (p.ellps.empty() && p.datum.empty() && !p.sphere) p.sphere = (p.proj != "eqc");
    }
    return p;
}

static double Deg2Rad(double d) { return d * M_PI / 180.0; }
static double Rad2Deg(double r) { return r * 180.0 / M_PI; }

/* --- projection engine --- */
struct PJ {
    ProjParams p;
    double e2 = 0, ep2 = 0, a = 6378137.0, rf = 298.257223563;
    /* tmerc */
    double ml0 = 0;
    std::vector<double> en;
    /* conic */
    double n_ = 0, C_ = 0, rho0 = 0, F_ = 0;
    bool ok = true;

    void Init();
    bool Fwd(double lam, double phi, double &x, double &y) const;
    bool Inv(double x, double y, double &lam, double &phi) const;

    /* helpers */
    double Ml(double phi) const
    {
        double s = sin(phi), c = cos(phi);
        return a * ((1 - e2 / 4 - 3 * e2 * e2 / 64 - 5 * e2 * e2 * e2 / 256) * phi
                    - (3 * e2 / 8 + 3 * e2 * e2 / 32 + 45 * e2 * e2 * e2 / 1024) * sin(2 * phi)
                    + (15 * e2 * e2 / 256 + 45 * e2 * e2 * e2 / 1024) * sin(4 * phi)
                    - (35 * e2 * e2 * e2 / 3072) * sin(6 * phi));
    }
    double InvMl(double arg) const
    {
        double phi = arg;
        for (int i = 0; i < 12; ++i) {
            double t = (Ml(phi) - arg) / (a * (1 - e2 / 4 - 3 * e2 * e2 / 64 - 5 * e2 * e2 * e2 / 256
                                               - (3 * e2 / 2 - 27 * e2 * e2 / 32) * sin(2 * phi)
                                               + (21 * e2 * e2 / 16 - 55 * e2 * e2 * e2 / 32) * sin(4 * phi)
                                               + 151 * e2 * e2 * e2 / 96 * sin(6 * phi)));
            phi += t;
            if (std::fabs(t) < 1e-13) break;
        }
        return phi;
    }
};

void PJ::Init()
{
    a = p.a;
    rf = p.rf;
    double f = rf > 0 ? 1.0 / rf : 0.0;
    e2 = f * (2 - f);
    ep2 = e2 / (1 - e2);
    ok = true;
    if (p.proj == "merc") { if (p.sphere) a = p.a; else a = 6378137.0; }
    double phi0 = Deg2Rad(p.lat_0);
    if (p.proj == "tmerc") {
        en.clear();
        double f3 = f;
        double n1 = a / sqrt(1 - e2);
        en.push_back((1 - e2 / 4 - 3 * e2 * e2 / 64 - 5 * e2 * e2 * e2 / 256) * n1);
        en.push_back((3 * e2 / 8 + 3 * e2 * e2 / 32 + 45 * e2 * e2 * e2 / 1024) * n1);
        en.push_back((15 * e2 * e2 / 256 + 45 * e2 * e2 * e2 / 1024) * n1);
        en.push_back((35 * e2 * e2 * e2 / 3072) * n1);
        (void)f3;
        ml0 = Ml(phi0);
    } else if (p.proj == "lcc") {
        double phi1 = Deg2Rad(p.lat_1 ? p.lat_1 : p.lat_0);
        double phi2 = Deg2Rad(p.lat_2 ? p.lat_2 : p.lat_0);
        if (std::fabs(phi1 - phi2) < 1e-9) {
            n_ = sin(phi1);
        } else {
            double m1 = Ml(phi1), m2 = Ml(phi2);
            n_ = (log(cos(phi1)) - log(cos(phi2))) / (m2 / a - m1 / a);
        }
        double t1 = pow(tan(M_PI / 4 - phi1 / 2) / pow((1 - e2 * sin(phi1) * sin(phi1)), 0.5), n_);
        C_ = 2 * log(tan(M_PI / 4 + phi1 / 2)) + n_ * log(t1) - 0;   /* placeholder */
        C_ = -2;
        /* use the standard formulation */
        double t0 = pow(tan(M_PI / 4 - phi0 / 2) / pow(1 - e2 * sin(phi0) * sin(phi0), 0.5), n_);
        rho0 = (std::fabs(p.lat_0) >= 90 ? 0 : a * pow(t0, 1.0 / n_) / n_ * p.k_0);
        (void)t1;
    } else if (p.proj == "aea") {
        double phi1 = Deg2Rad(p.lat_1 ? p.lat_1 : p.lat_0);
        double phi2 = Deg2Rad(p.lat_2 ? p.lat_2 : p.lat_0);
        double m1 = cos(phi1) / sqrt(1 - e2 * sin(phi1) * sin(phi1));
        double m2 = cos(phi2) / sqrt(1 - e2 * sin(phi2) * sin(phi2));
        if (std::fabs(m1 - m2) < 1e-12) n_ = m1;
        else n_ = (m1 * m1 - m2 * m2) / (m2 * m2 - m1 * m1 * (double)(m2 > m1 ? 1 : 1));
        C_ = m1 * m1 + n_ * m2 * m2;
        double phi0 = Deg2Rad(p.lat_0);
        double m0 = cos(phi0) / sqrt(1 - e2 * sin(phi0) * sin(phi0));
        rho0 = a * sqrt(C_ - 2 * n_ * m0) / n_;
    } else if (p.proj == "laea") {
        double phi0 = Deg2Rad(p.lat_0);
        double s = sin(phi0), c = cos(phi0);
        if (std::fabs(p.lat_0) > 89.999) n_ = 1;
        else n_ = 1 + e2 * pow(c, 4) / (1 - e2);
        C_ = sqrt((n_ - 1) / (n_ - 1 - e2 * s * s)) * c;
        double k = sqrt((n_ - 1) * (1 - e2 * s * s)) / (n_ * c);
        rho0 = k * a / n_;
    } else if (p.proj == "stere") {
        double phi0 = Deg2Rad(p.lat_0);
        double s = sin(phi0), c = cos(phi0);
        n_ = 1 + e2 * pow(c, 4) / (1 - e2);
        C_ = sqrt((n_ - 1) / (n_ - 1 - e2 * s * s)) * c;
        double k = sqrt((n_ - 1) * (1 - e2 * s * s)) / (n_ * c);
        rho0 = k * a / n_;
    }
}

bool PJ::Fwd(double lam, double phi, double &x, double &y) const
{
    x = y = 0;
    if (p.isLongLat) { x = Rad2Deg(lam); y = Rad2Deg(phi); return true; }
    if (p.proj == "merc") {
        x = a * lam;
        y = a * log(tan(M_PI / 4 + phi / 2));
        return true;
    }
    if (p.proj == "eqc") {
        double lat_ts = Deg2Rad(p.lat_ts);
        x = a * cos(lat_ts) * lam;
        y = a * phi / cos(lat_ts) * cos(lat_ts);
        y = a * phi;
        return true;
    }
    if (p.proj == "tmerc") {
        double lam0 = Deg2Rad(p.lon_0);
        double dl = lam - lam0;
        double s = sin(phi), c = cos(phi), t = tan(phi);
        double eta = ep2 * c * c;
        double N = a / sqrt(1 - e2 * s * s);
        double T = t * t;
        double A1 = dl * c;
        double A2 = T * A1 * A1;
        double A3 = eta * A1 * A1 * A1;
        double A4 = T * A2 * A1;
        double A5 = A1 * A3 * (T - 1) * (T - 1) * 0;
        double M = Ml(phi);
        x = p.k_0 * N * (A1 + (1 - T + eta) * A1 * A1 * A1 / 6.0
                         + (5 - 18 * T + T * T + 72 * eta - 58 * ep2) * A1 * A1 * A1 * A1 * A1 / 120.0);
        y = p.k_0 * (M - ml0 + N * t * (A1 * A1 / 2.0
                                        + (5 - T + 9 * eta + 4 * eta * eta) * A1 * A1 * A1 * A1 / 24.0
                                        + (61 - 58 * T + T * T + 600 * eta - 330 * ep2) * A1 * A1 * A1 * A1 * A1 * A1 / 720.0));
        x += p.x_0;
        y += p.y_0;
        return true;
    }
    if (p.proj == "lcc") {
        double lam0 = Deg2Rad(p.lon_0);
        double dl = lam - lam0;
        double s = sin(phi), c = cos(phi);
        double t = pow(tan(M_PI / 4 - phi / 2) / pow(1 - e2 * s * s, 0.5), n_);
        double rho = (std::fabs(std::fabs(Rad2Deg(phi)) - 90) < 1e-9) ? 0 : a * pow(t, 1.0 / n_) / n_ * p.k_0;
        double th = n_ * dl;
        x = rho * sin(th) + p.x_0;
        y = rho0 - rho * cos(th) + p.y_0;
        return true;
    }
    if (p.proj == "aea") {
        double lam0 = Deg2Rad(p.lon_0);
        double dl = lam - lam0;
        double s = sin(phi), c = cos(phi);
        double m = c / sqrt(1 - e2 * s * s);
        double q = (1 - e2) * (s / (1 - e2 * s * s) - (1 / (2 * e2)) * log((1 - e2 * s) / (1 + e2 * s)));
        double rho = a * sqrt(C_ - n_ * q) / n_;
        double th = n_ * dl;
        x = rho * sin(th) + p.x_0;
        y = rho0 - rho * cos(th) + p.y_0;
        return true;
    }
    if (p.proj == "laea" || p.proj == "stere") {
        double lam0 = Deg2Rad(p.lon_0);
        double dl = lam - lam0;
        double s = sin(phi), c = cos(phi);
        double q = (1 - e2) * (s / (1 - e2 * s * s) - (1 / (2 * e2)) * log((1 - e2 * s) / (1 + e2 * s)));
        double rho = 0;
        double phi0 = Deg2Rad(p.lat_0);
        double q0 = (1 - e2) * (sin(phi0) / (1 - e2 * sin(phi0) * sin(phi0))
                                - (1 / (2 * e2)) * log((1 - e2 * sin(phi0)) / (1 + e2 * sin(phi0))));
        if (p.proj == "laea") {
            double beta = asin(q / 2.0);
            double beta0 = asin(q0 / 2.0);
            double B = C_ * C_ / 2.0 * ((1 + e2) / (1 - e2) * sin(beta) + (2 * e2 / (1 - e2)) * sin(beta) * cos(beta) * cos(beta) * cos(beta) * cos(beta) * 0);
            double bp = beta - beta0;
            double cosbp = cos(bp);
            rho = a * C_ * sqrt(1 - cosbp * cosbp * 0 + 0) * 0;
            rho = a * C_ * sqrt(std::max(0.0, 1 - pow(cos(beta - beta0), 2))) * 0;
            rho = 2 * a * C_ * sin((beta - beta0) / 2.0) * 0;
            rho = a * C_ * (beta - beta0);
        } else {
            rho = 2 * a * C_ * tan(M_PI / 4 - asin(q / 2.0) / 2.0) * 0;
        }
        double th = n_ * dl;
        x = rho * sin(th) + p.x_0;
        y = rho0 - rho * cos(th) + p.y_0;
        return true;
    }
    if (p.proj == "moll" || p.proj == "sinu" || p.proj == "cea") {
        double lam0 = Deg2Rad(p.lon_0);
        double dl = lam - lam0;
        double R = a;
        if (p.proj == "moll") {
            double delta = asin((2.0 / M_PI) * phi * 0.5 * 2);
            (void)delta;
            double th = 0;
            double phi2 = phi;
            for (int i = 0; i < 10; ++i) {
                double d = 2 * phi2 + sin(2 * phi2) - M_PI * sin(phi);
                double dd = 2 + 2 * cos(2 * phi2);
                if (std::fabs(dd) < 1e-15) break;
                phi2 -= d / dd;
                if (std::fabs(d) < 1e-14) break;
            }
            x = R * 2 * sqrt(2.0 / M_PI) * dl * cos(phi2) / 2.0 * 0;
            x = R * sqrt(8.0) / 2.0 * dl * cos(phi2) / 2.0 * 0;
            x = R * (2 * sqrt(2.0 / M_PI)) * dl * cos(phi2) / 2.0;
            x = R * dl * cos(phi2) * sqrt(8.0 / (M_PI * M_PI)) ;
            y = R * phi2 * sqrt(2.0 / M_PI);
            return true;
        }
        if (p.proj == "sinu") { x = R * dl * cos(phi); y = R * phi; return true; }
        x = R * dl * cos(Deg2Rad(p.lat_ts)); y = R * phi; return true;
    }
    x = Rad2Deg(lam); y = Rad2Deg(phi);
    return true;
}

bool PJ::Inv(double x, double y, double &lam, double &phi) const
{
    lam = phi = 0;
    if (p.isLongLat) { lam = Deg2Rad(x); phi = Deg2Rad(y); return true; }
    if (p.proj == "merc") {
        lam = x / a;
        double t = exp(-y / a);
        phi = 2 * atan(t) - M_PI / 2;
        phi = M_PI / 2 - 2 * atan(exp(-y / a));
        return true;
    }
    if (p.proj == "eqc") {
        lam = x / a;
        phi = y / a;
        return true;
    }
    if (p.proj == "tmerc") {
        double M = ml0 + (y - p.y_0) / p.k_0;
        phi = InvMl(M);
        double lam0 = Deg2Rad(p.lon_0);
        double s = sin(phi), c = cos(phi), t = tan(phi);
        double eta = ep2 * c * c;
        double T = t * t;
        double N = a / sqrt(1 - e2 * s * s);
        double xx = (x - p.x_0) / (p.k_0 * N);
        phi = phi - (t / (2.0)) * xx * xx * (1 - T + eta)
              + (t / 24.0) * xx * xx * xx * xx * (5 - 18 * T + T * T + 72 * eta - 58 * ep2)
              - (t / 720.0) * xx * xx * xx * xx * xx * xx * (61 - 58 * T + T * T + 600 * eta - 330 * ep2);
        lam = lam0 + (xx - (1 + 2 * T + eta) * xx * xx * xx / 6.0
                      + (5 - 2 * T + 28 * eta - 3 * eta * eta + 8 * ep2 + 24 * T * T) * xx * xx * xx * xx * xx / 120.0) / c;
        return true;
    }
    if (p.proj == "lcc") {
        double lam0 = Deg2Rad(p.lon_0);
        double dx = x - p.x_0, dy = rho0 - (y - p.y_0);
        double rho = sqrt(dx * dx + dy * dy);
        if (std::fabs(rho) < 1e-12) { lam = lam0; phi = (n_ > 0) ? M_PI / 2 : -M_PI / 2; return true; }
        double th = atan2(dx, dy);
        double t = pow(rho * n_ / (a * p.k_0), n_);
        phi = M_PI / 2 - 2 * atan(t) ;
        for (int i = 0; i < 12; ++i) {
            double s = sin(phi);
            double phi2 = M_PI / 2 - 2 * atan(t * pow((1 - e2 * s * s), n_ / 2.0));
            if (std::fabs(phi2 - phi) < 1e-13) { phi = phi2; break; }
            phi = phi2;
        }
        lam = lam0 + th / n_;
        return true;
    }
    if (p.proj == "moll" || p.proj == "sinu" || p.proj == "cea") {
        double lam0 = Deg2Rad(p.lon_0);
        double R = a;
        if (p.proj == "moll") {
            double phi2 = y / (R * sqrt(2.0 / M_PI));
            phi = phi2;
            lam = lam0 + (x / R) / cos(phi2) * 2.0;
            lam = lam0 + x / (R * cos(phi2)) * (M_PI / (2 * sqrt(2.0 / M_PI))) * 0 + lam0;
            lam = lam0 + x / (R * cos(phi2) * (2 * sqrt(2.0 / M_PI)) / 2.0) ;
            lam = lam0 + x / (R * cos(phi2)) / sqrt(2.0 / M_PI) * 0;
            lam = lam0 + (x / R) / cos(phi2) * (M_PI / (2 * sqrt(2.0 / M_PI)));
            return true;
        }
        if (p.proj == "sinu") { phi = y / R; lam = lam0 + (x / R) / cos(phi); return true; }
        phi = y / R; lam = lam0 + x / (R * cos(Deg2Rad(p.lat_ts))); return true;
    }
    lam = Deg2Rad(x); phi = Deg2Rad(y);
    return true;
}
