        out += "    DATUM[\"" + std::string(e ? e->datumName : name) + "\",\n";
        out += "        ELLIPSOID[\"WGS 84\",6378137,298.257223563,\n";
        out += "            LENGTHUNIT[\"metre\",1]]],\n";
        out += "    PRIMEM[\"Greenwich\",0,\n";
