void CRS::SetFromEpsg(long long c)
{
    valid = true;
    authority = "EPSG";
    code = c;
    if (c >= 32601 && c <= 32660) {
        int zone = (int)(c - 32600);
        name = UtmNameFor(zone, false, "WGS 84", "World - N hemisphere");
        type = "Projected";
        area = "World - UTM zone " + std::to_string(zone) + "N";
        proj4 = "+proj=tmerc +lat_0=0 +lon_0=" + std::to_string(-183.0 + 6.0 * zone) +
                " +k=0.9996 +x_0=500000 +y_0=0 +datum=WGS84 +units=m";
        axisMapping = {1, 2};
        wkt = WktForCode(c, name, type, nullptr);
        isGeographic = false;
        return;
    }
    if (c >= 32701 && c <= 32760) {
        int zone = (int)(c - 32700);
        name = UtmNameFor(zone, true, "WGS 84", "World - S hemisphere");
        type = "Projected";
        area = "World - UTM zone " + std::to_string(zone) + "S";
        proj4 = "+proj=tmerc +lat_0=0 +lon_0=" + std::to_string(-183.0 + 6.0 * zone) +
                " +k=0.9996 +x_0=500000 +y_0=10000000 +datum=WGS84 +units=m";
        axisMapping = {1, 2};
        wkt = WktForCode(c, name, type, nullptr);
        isGeographic = false;
        return;
    }
    const EpsgEntry *e = FindEpsg(c);
    if (!e) {
        char buf[64];
        snprintf(buf, sizeof(buf), "Unknown CRS EPSG:%lld", c);
        name = buf;
        type = "";
        area = "";
        proj4 = "";
        axisMapping = {1, 2};
        isGeographic = false;
        wkt = "";
        return;
    }
    name = e->name;
    type = e->type;
    area = e->area;
    proj4 = e->proj4;
    axisMapping.clear();
    for (auto &t : StrSplit(e->axisMap, ',')) axisMapping.push_back(atoi(t.c_str()));
    isGeographic = (type.rfind("Geographic", 0) == 0);
    wkt = WktForCode(c, name, type, e);
}

static std::string UtmNameFor(int zone, bool south, const char *base, const char *area)
{
    char buf[256];
    snprintf(buf, sizeof(buf), "%s / UTM zone %d%s", base, zone, south ? "S" : "N");
    return std::string(buf);
}

CRS CRS::FromUserInput(const std::string &s)
{
    CRS c;
    std::string t = Trim(s);
    if (t.empty()) return c;
    std::string up = ToUpper(t);
    if (up.rfind("EPSG:", 0) == 0) {
        long long code;
        if (ParseInt(t.substr(5), code)) { c.SetFromEpsg(code); return c; }
    }
    if (up.find("EPSG::") != std::string::npos) {
        size_t q = up.find("EPSG::");
        long long code;
        if (ParseInt(t.substr(q + 6), code)) { c.SetFromEpsg(code); return c; }
    }
    if (up.rfind("EPSG", 0) == 0) {
        size_t q = t.find(':');
        long long code;
        if (q != std::string::npos && ParseInt(Trim(t.substr(q + 1)), code)) { c.SetFromEpsg(code); return c; }
    }
    if (t.rfind("+proj=", 0) == 0 || t.rfind("+init=", 0) == 0) {
        c.valid = true;
        c.proj4 = t;
        ProjParams p = ParseProj4(t);
        c.isGeographic = p.isLongLat;
        c.type = p.isLongLat ? "Geographic 2D" : "Projected";
        c.name = "unnamed";
        c.axisMapping = {1, 2};
        c.wkt = "";
        return c;
    }
    if (t.rfind("GEOGCRS[", 0) == 0 || t.rfind("PROJCRS[", 0) == 0 ||
        t.rfind("GEOGCCS[", 0) == 0 || t.rfind("PROJCCS[", 0) == 0 ||
        t.rfind("GEOSCRS[", 0) == 0) {
        c.valid = true;
        c.wkt = t;
        size_t q = t.find('"');
        if (q != std::string::npos) {
            size_t q2 = t.find('"', q + 1);
            c.name = t.substr(q + 1, q2 - q - 1);
        }
        c.isGeographic = (t.rfind("GEOGCRS[", 0) == 0 || t.rfind("GEOGCCS[", 0) == 0);
        c.type = c.isGeographic ? "Geographic 2D" : "Projected";
        /* extract ID */
        size_t id = t.find("ID[\"EPSG\",");
        if (id != std::string::npos) {
            size_t st = id + 10, en = t.find(']', st);
            c.authority = "EPSG";
            ParseInt(Trim(t.substr(st, en - st)), c.code);
            const EpsgEntry *e = FindEpsg(c.code);
            if (e) {
                c.area = e->area;
                c.axisMapping.clear();
                for (auto &tk : StrSplit(e->axisMap, ',')) c.axisMapping.push_back(atoi(tk.c_str()));
            }
        }
        if (c.axisMapping.empty()) c.axisMapping = c.isGeographic ? std::vector<int>{2, 1} : std::vector<int>{1, 2};
        return c;
    }
    if (up.rfind("URN:OGC:DEF:CRS", 0) == 0) {
        size_t q = t.find("::");
        std::string tail = (q == std::string::npos) ? "" : t.substr(q + 2);
        long long code;
        if (ParseInt(tail, code)) { c.SetFromEpsg(code); return c; }
        c.valid = true;
        c.name = tail;
        c.wkt = t;
        return c;
    }
    /* other authority strings */
    c.valid = true;
    c.name = t;
    c.wkt = "";
    return c;
}

bool CRS::IsSame(const CRS &o) const
{
    if (valid != o.valid) return false;
    if (authority == o.authority && code == o.code && code != 0) return true;
    if (!wkt.empty() && wkt == o.wkt) return true;
    return name == o.name && proj4 == o.proj4;
}

bool CRS::TransformTo(const CRS &dst, double &x, double &y) const
{
    if (!valid || !dst.valid) return false;
    if (IsSame(dst)) return true;
    PJ src, pd;
    src.p = ParseProj4(proj4.empty() && code == 4326 ? "" : proj4);
    if (proj4.empty() && !code) { src.p.isLongLat = true; }
    src.Init();
    pd.p = ParseProj4(dst.proj4.empty() && dst.code == 4326 ? "" : dst.proj4);
    if (dst.proj4.empty() && !dst.code) { pd.p.isLongLat = true; }
    pd.Init();
    double lam, phi;
    if (!pd.Inv(x, y, lam, phi)) return false;
    if (!src.Fwd(lam, phi, x, y)) return false;
    return true;
}

