{"command": "cat > /workspace/src/formats.cpp <<'CEOF'
/* Format drivers: GeoJSON family, ESRI Shapefile, GeoTIFF, VRT and MEM. */
#include "gdal.h"
#include "port.h"
#include "crs.h"

#include <string.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>

/* ------------------------------------------------------------------ */
/* simple JSON value reader                                            */
/* ------------------------------------------------------------------ */
struct JVal {
    int kind = 0;             /* 0 null, 1 bool, 2 num, 3 str, 4 arr, 5 obj */
    bool b = false;
    double num = 0;
    std::string str;
    std::vector<JVal> arr;
    std::vector<std::pair<std::string, JVal> > obj;
    const JVal *Get(const char *k) const
    {
        for (auto &p : obj) if (p.first == k) return &p.second;
        return nullptr;
    }
    std::string Str(const char *k, const std::string &d = "") const
    {
        const JVal *v = Get(k);
        return (v && v->kind == 3) ? v->str : d;
    }
    double Num(const char *k, double d = 0) const
    {
        const JVal *v = Get(k);
        return (v && (v->kind == 2)) ? v->num : d;
    }
};

struct JParser {
    const char *p;
    explicit JParser(const std::string &s) : p(s.c_str()) {}
    void Ws() { while (*p && (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r')) ++p; }
    bool Parse(JVal &v);
    bool Str(std::string &s);
};

bool JParser::Str(std::string &s)
{
    if (*p != '"') return false;
    ++p;
    while (*p && *p != '"') {
        if (*p == '\\' && p[1]) {
            ++p;
            switch (*p) {
                case 'n': s += '\n'; break;
                case 't': s += '\t'; break;
                case 'r': s += '\r'; break;
                case 'b': s += '\b'; break;
                case 'f': s += '\f'; break;
                case 'u': {
                    char buf[8];
                    int v = 0;
                    for (int i = 0; i < 4 && isxdigit((unsigned char)p[1]); ++i) {
                        ++p;
                        char c = *p;
                        v = v * 16 + (c <= '9' ? c - '0' : (tolower(c) - 'a' + 10));
                    }
                    if (v < 0x80) s += (char)v;
                    else if (v < 0x800) { s += (char)(0xc0 | (v >> 6)); s += (char)(0x80 | (v & 0x3f)); }
                    else { s += (char)(0xe0 | (v >> 12)); s += (char)(0x80 | ((v >> 6) & 0x3f)); s += (char)(0x80 | (v & 0x3f)); }
                    break;
                }
                default: s += *p; break;
            }
            ++p;
        } else s += *p++;
    }
    if (*p == '"') ++p;
    return true;
}

bool JParser::Parse(JVal &v)
{
    Ws();
    if (*p == '{') {
        v.kind = 5;
        ++p;
        Ws();
        if (*p == '}') { ++p; return true; }
        while (true) {
            Ws();
            std::string k;
            if (!Str(k)) return false;
            Ws();
            if (*p != ':') return false;
            ++p;
            JVal c;
            if (!Parse(c)) return false;
            v.obj.push_back({k, c});
            Ws();
            if (*p == ',') { ++p; continue; }
            if (*p == '}') { ++p; return true; }
            return false;
        }
    }
    if (*p == '[') {
        v.kind = 4;
        ++p;
        Ws();
        if (*p == ']') { ++p; return true; }
        while (true) {
            JVal c;
            if (!Parse(c)) return false;
            v.arr.push_back(c);
            Ws();
            if (*p == ',') { ++p; continue; }
            if (*p == ']') { ++p; return true; }
            return false;
        }
    }
    if (*p == '"') { v.kind = 3; return Str(v.str); }
    if (*p == 't') { if (!strncmp(p, "true", 4)) { p += 4; v.kind = 1; v.b = true; return true; } return false; }
    if (*p == 'f') { if (!strncmp(p, "false", 5)) { p += 5; v.kind = 1; return true; } return false; }
    if (*p == 'n') { if (!strncmp(p, "null", 4)) { p += 4; return true; } return false; }
    char *end = nullptr;
    double d = strtod(p, &end);
    if (end == p) return false;
    v.kind = 2;
    v.num = d;
    p = end;
    return true;
}

/* ------------------------------------------------------------------ */
/* GeoJSON helpers                                                     */
/* ------------------------------------------------------------------ */
static void JValToGeom(const JVal &v, Geometry &g);

static void CoordToPt(const JVal &v, Geometry &g)
{
    if (v.kind != 4 || v.arr.empty()) return;
    std::vector<double> pt;
    for (auto &c : v.arr) pt.push_back(c.num);
    if (pt.size() > (size_t)g.dims) g.dims = (int)pt.size();
    g.pts.push_back(pt);
}

static void JValToGeom(const JVal &v, Geometry &g)
{
    std::string ty = ToLower(v.Str("type"));
    const JVal *coords = v.Get("coordinates");
    if (ty == "point") {
        g.type = "Point";
        if (coords) CoordToPt(*coords, g);
    } else if (ty == "multipoint") {
        g.type = "MultiPoint";
        if (coords)
            for (auto &c : coords->arr) {
                Geometry sub;
                sub.type = "Point";
                sub.dims = g.dims;
                CoordToPt(c, sub);
                g.parts.push_back(sub);
            }
    } else if (ty == "linestring") {
        g.type = "LineString";
        if (coords)
            for (auto &c : coords->arr) CoordToPt(c, g);
    } else if (ty == "multilinestring") {
        g.type = "MultiLineString";
        if (coords)
            for (auto &c : coords->arr) {
                Geometry sub;
                sub.type = "LineString";
                sub.dims = g.dims;
                for (auto &c2 : c.arr) CoordToPt(c2, sub);
                g.parts.push_back(sub);
            }
    } else if (ty == "polygon") {
        g.type = "Polygon";
        if (coords)
            for (auto &c : coords->arr) {
                Geometry sub;
                sub.type = "LineString";
                sub.dims = g.dims;
                for (auto &c2 : c.arr) CoordToPt(c2, sub);
                g.parts.push_back(sub);
            }
    } else if (ty == "multipolygon") {
        g.type = "MultiPolygon";
        if (coords)
            for (auto &c : coords->arr) {
                Geometry poly;
                poly.type = "Polygon";
                poly.dims = g.dims;
                for (auto &c2 : c.arr) {
                    Geometry ring;
                    ring.type = "LineString";
                    ring.dims = g.dims;
                    for (auto &c3 : c2.arr) CoordToPt(c3, ring);
                    poly.parts.push_back(ring);
                }
                g.parts.push_back(poly);
            }
    } else if (ty == "geometrycollection") {
        g.type = "GeometryCollection";
        const JVal *gs = v.Get("geometries");
        if (gs)
            for (auto &c : gs->arr) {
                Geometry sub;
                JValToGeom(c, sub);
                g.parts.push_back(sub);
            }
    }
}

static void GeomToJson(const Geometry &g, std::string &out, bool compact);

static std::string CoordStr(const std::vector<double> &p)
{
    std::string s = "[";
    for (size_t i = 0; i < p.size(); ++i) {
        if (i) s += ",";
        s += FormatReal(p[i]);
    }
    s += "]";
    return s;
}

static void GeomToJson(const Geometry &g, std::string &out, bool compact)
{
    std::string t = g.type.empty() ? "Unknown" : g.type;
    if (t == "LineString" && g.parts.empty() && g.pts.size() == 2) t = "LineString";
    std::string ty = t;
    if (ty == "LineString") ty = "LineString";
    out += "{\"type\":\"" + ty + "\",";
    if (g.parts.empty()) {
        out += "\"coordinates\":[";
        for (size_t i = 0; i < g.pts.size(); ++i) {
            if (i) out += ",";
            out += CoordStr(g.pts[i]);
        }
        out += "]}";
    } else {
        if (g.type == "GeometryCollection") {
            out += "\"geometries\":[";
            for (size_t i = 0; i < g.parts.size(); ++i) {
                if (i) out += ",";
                GeomToJson(g.parts[i], out, compact);
            }
            out += "]}";
            return;
        }
        out += "\"coordinates\":[";
        for (size_t i = 0; i < g.parts.size(); ++i) {
            if (i) out += ",";
            const Geometry &sub = g.parts[i];
            if (g.type == "MultiPolygon") {
                out += "[";
                for (size_t j = 0; j < sub.parts.size(); ++j) {
                    if (j) out += ",";
                    out += "[";
                    for (size_t k = 0; k < sub.parts[j].pts.size(); ++k) {
                        if (k) out += ",";
                        out += CoordStr(sub.parts[j].pts[k]);
                    }
                    out += "]";
                }
                out += "]";
            } else if (g.type == "Polygon" || g.type == "MultiLineString") {
                out += "[";
                for (size_t k = 0; k < sub.pts.size(); ++k) {
                    if (k) out += ",";
                    out += CoordStr(sub.pts[k]);
                }
                out += "]";
            } else {
                out += "[";
                for (size_t k = 0; k < sub.pts.size(); ++k) {
                    if (k) out += ",";
                    out += CoordStr(sub.pts[k]);
                }
                out += "]";
            }
        }
        out += "]}";
    }
}

std::string GeometryToJson(const Geometry &g) { std::string s; GeomToJson(g, s, false); return s; }

/* ------------------------------------------------------------------ */
/* GeoJSON writer                                                      */
/* ------------------------------------------------------------------ */
static std::string JsonQ(const std::string &s)
{
    std::string r = "\"";
    for (unsigned char c : s) {
        switch (c) {
            case '"': r += "\\\""; break;
            case '\\': r += "\\\\"; break;
            case '\n': r += "\\n"; break;
            case '\r': r += "\\r"; break;
            case '\t': r += "\\t"; break;
            default:
                if (c < 0x20) { char b[8]; snprintf(b, sizeof(b), "\\u%04x", c); r += b; }
                else r += (char)c;
        }
    }
    r += "\"";
    return r;
}

static std::string FieldTypeNameOf(const FieldDef &f)
{
    switch (f.type) {
        case OFT_Integer: return "Integer";
        case OFT_Integer64: return "Integer64";
        case OFT_Real: return "Real";
        case OFT_String: return "String";
        case OFT_Date: return "Date";
        case OFT_Time: return "Time";
        case OFT_DateTime: return "DateTime";
        case OFT_IntegerList: return "IntegerList";
        case OFT_Integer64List: return "Integer64List";
        case OFT_RealList: return "RealList";
        case OFT_StringList: return "StringList";
        case OFT_Binary: return "Binary";
        default: return "String";
    }
}

static std::string ValueToJson(const Value &v, OFIELDTYPE t)
{
    if (v.isNull) return "null";
    switch (t) {
        case OFT_Integer: case OFT_Integer64: return std::to_string(v.i);
        case OFT_Real: return FormatReal(v.d);
        default: return JsonQ(v.s);
    }
}

static std::string FieldJsonType(const FieldDef &f)
{
    switch (f.type) {
        case OFT_Integer: return "\"type\":\"Integer\"";
        case OFT_Integer64: return "\"type\":\"Integer64\"";
        case OFT_Real: return "\"type\":\"Real\"";
        case OFT_Date: return "\"type\":\"String\",\"subtype\":\"Date\"";
        case OFT_Time: return "\"type\":\"String\",\"subtype\":\"Time\"";
        case OFT_DateTime: return "\"type\":\"String\",\"subtype\":\"DateTime\"";
        case OFT_IntegerList: return "\"type\":\"IntegerList\"";
        case OFT_Integer64List: return "\"type\":\"Integer64List\"";
        case OFT_RealList: return "\"type\":\"RealList\"";
        case OFT_StringList: return "\"type\":\"StringList\"";
        case OFT_Binary: return "\"type\":\"Binary\"";
        default: return "\"type\":\"String\"";
    }
}

static void WriteGeoJson(const VectorDataset &ds, const std::string &path, bool seq)
{
    FILE *f = fopen(path.c_str(), "wb");
    if (!f) return;
    std::string out;
    if (ds.layers.empty()) {
        if (!seq) out = "{\n\"type\": \"FeatureCollection\",\n\"features\": [\n]\n}\n";
    } else {
        const Layer &ly = ds.layers[0];
        if (!seq) {
            out = "{\n\"type\": \"FeatureCollection\",\n";
            if (!ly.name.empty()) out += "\"name\": " + JsonQ(ly.name) + ",\n";
            CRS crs = CRS::FromWkt(ly.srsWkt);
            if (crs.valid && crs.code && !ly.srsWkt.empty() && crs.code != 4326)
                out += "\"crs\": { \"type\": \"name\", \"properties\": { \"name\": \"urn:ogc:def:crs:EPSG::" +
                       std::to_string(crs.code) + "\" } },\n";
            out += "\"features\": [\n";
        }
        for (size_t i = 0; i < ly.features.size(); ++i) {
            const Feature &ft = ly.features[i];
            out += "{\"type\":\"Feature\",\"properties\":{";
            bool first = true;
            for (size_t j = 0; j < ly.fields.size() && j < ft.values.size(); ++j) {
                const FieldDef &fd = ly.fields[j];
                if (!first) out += ",";
                first = false;
                out += JsonQ(fd.name) + ":" + ValueToJson(ft.values[j], fd.type);
            }
            out += "},";
            if (ft.geom.IsEmpty() && ft.geom.type == "UNKNOWN") {
                out += "\"geometry\":null";
            } else {
                std::string gj;
                GeomToJson(ft.geom, gj, false);
                out += "\"geometry\":" + gj;
            }
            out += "}";
            if (!seq && i + 1 < ly.features.size()) out += ",\n";
            else out += "\n";
        }
        if (!seq) out += "]\n}\n";
    }
    fwrite(out.data(), 1, out.size(), f);
    fclose(f);
}

/* ------------------------------------------------------------------ */
/* GeoJSON reader                                                      */
/* ------------------------------------------------------------------ */
static void CollectFields(const JVal &props, std::vector<FieldDef> &fields)
{
    for (auto &p : props.obj) {
        bool found = false;
        for (auto &f : fields) if (f.name == p.first) { found = true; break; }
        if (found) continue;
        FieldDef f;
        f.name = p.first;
        if (p.second.kind == 2) {
            bool integral = (p.second.num == floor(p.second.num)) && std::fabs(p.second.num) < 2e9;
            f.type = integral ? OFT_Integer : OFT_Real;
        } else if (p.second.kind == 3) f.type = OFT_String;
        else if (p.second.kind == 1) f.type = OFT_Integer;
        else f.type = OFT_String;
        fields.push_back(f);
    }
}

static void ValueFromJVal(const JVal &v, Value &out)
{
    out = Value();
    if (v.kind == 0) { out.isNull = true; return; }
    if (v.kind == 1) { out.isNull = false; out.i = v.b ? 1 : 0; out.d = out.i; out.s = v.b ? "true" : "false"; return; }
    if (v.kind == 2) {
        out.isNull = false;
        out.d = v.num;
        out.i = (long long)v.num;
        char buf[64];
        snprintf(buf, sizeof(buf), "%.17g", v.num);
        out.s = buf;
        return;
    }
    out.isNull = false;
    out.s = v.str;
    return;
}

static bool ReadGeoJson(const std::string &path, VectorDataset &ds)
{
    bool ok = false;
    std::string data = ReadWholeFile(path, ok);
    if (!ok) return false;
    JParser jp(data);
    JVal v;
    if (!jp.Parse(v)) return false;
    ds.driverShort = ds.driverLong = "GeoJSON";
    ds.name = path;
    ds.files.push_back(path);
    Layer ly;
    ly.name = BaseName(path);
    size_t q = ly.name.rfind('.');
    if (q != std::string::npos) ly.name = ly.name.substr(0, q);
    std::string crsName;
    const JVal *crs = v.Get("crs");
    if (crs) {
        const JVal *props = crs->Get("properties");
        if (props) crsName = props->Str("name");
    }
    const JVal *feats = v.Get("features");
    if (!feats) {
        const JVal *geom = v.Get("geometry");
        if (geom) { /* single geometry file */ }
        feats = v.Get("features");
    }
    std::string layerName;
    const JVal *nm = v.Get("name");
    if (nm && nm->kind == 3) layerName = nm->str;
    if (!layerName.empty()) ly.name = layerName;
    if (feats) {
        for (auto &fv : feats->arr) {
            Feature ft;
            ft.fid = (long long)ly.features.size() + 1;
            const JVal *props = fv.Get("properties");
            if (props) {
                CollectFields(*props, ly.fields);
                ft.values.resize(props->obj.size());
                size_t i = 0;
                for (auto &p : props->obj) {
                    Value vv;
                    ValueFromJVal(p.second, vv);
                    ft.values.push_back(vv);
                    (void)i;
                }
                /* align values with fields order */
                ft.values.clear();
                for (auto &fd : ly.fields) {
                    const JVal *pv = props->Get(fd.name.c_str());
                    Value vv;
                    if (pv) ValueFromJVal(*pv, vv);
                    ft.values.push_back(vv);
                }
            }
            const JVal *gj = fv.Get("geometry");
            if (gj && gj->kind == 5) JValToGeom(*gj, ft.geom);
            ly.features.push_back(ft);
        }
    }
    if (ly.features.size()) {
        double minx, miny, maxx, maxy;
        ly.features[0].geom.Bounds(minx, miny, maxx, maxy);
        for (auto &f : ly.features) {
            double a, b, c, dd;
            f.geom.Bounds(a, b, c, dd);
            if (a < minx) minx = a;
            if (b < miny) miny = b;
            if (c > maxx) maxx = c;
            if (dd > maxy) maxy = dd;
        }
        ly.geomType = ly.features[0].geom.type.empty() ? "Unknown" : ly.features[0].geom.type;
        for (auto &f : ly.features) {
            if (!f.geom.IsEmpty() && f.geom.type != ly.geomType) {
                if ((ly.geomType == "Point" && f.geom.type == "MultiPoint") ||
                    (ly.geomType == "LineString" && f.geom.type == "MultiLineString") ||
                    (ly.geomType == "Polygon" && f.geom.type == "MultiPolygon"))
                    ly.geomType = f.geom.type;
                else if (ly.geomType != "Unknown") { ly.geomType = "Unknown"; break; }
            }
        }
    }
    if (!crsName.empty()) {
        CRS c = CRS::FromUserInput(crsName);
        if (c.valid) ly.srsWkt = c.wkt;
    }
    ds.layers.push_back(ly);
    return true;
}

