/* Format drivers: GeoJSON family, ESRI Shapefile, GeoTIFF, VRT and MEM. */
#include "gdal.h"
#include "port.h"
#include "crs.h"

#include <string.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>

/* ------------------------------------------------------------------ */
/* simple JSON value reader                                            */
/* ------------------------------------------------------------------ */
struct JVal {
    int kind = 0;             /* 0 null, 1 bool, 2 num, 3 str, 4 arr, 5 obj */
    bool b = false;
    double num = 0;
    std::string str;
    std::vector<JVal> arr;
    std::vector<std::pair<std::string, JVal> > obj;
    const JVal *Get(const char *k) const
    {
        for (auto &p : obj) if (p.first == k) return &p.second;
        return nullptr;
    }
    std::string Str(const char *k, const std::string &d = "") const
    {
        const JVal *v = Get(k);
        return (v && v->kind == 3) ? v->str : d;
    }
    double Num(const char *k, double d = 0) const
    {
        const JVal *v = Get(k);
        return (v && (v->kind == 2)) ? v->num : d;
    }
};

struct JParser {
    const char *p;
    explicit JParser(const std::string &s) : p(s.c_str()) {}
    void Ws() { while (*p && (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r')) ++p; }
    bool Parse(JVal &v);
    bool Str(std::string &s);
};

bool JParser::Str(std::string &s)
{
    if (*p != '"') return false;
    ++p;
    while (*p && *p != '"') {
        if (*p == '\\' && p[1]) {
            ++p;
            switch (*p) {
                case 'n': s += '\n'; break;
                case 't': s += '\t'; break;
                case 'r': s += '\r'; break;
                case 'b': s += '\b'; break;
                case 'f': s += '\f'; break;
                case 'u': {
                    char buf[8];
                    int v = 0;
                    for (int i = 0; i < 4 && isxdigit((unsigned char)p[1]); ++i) {
                        ++p;
                        char c = *p;
                        v = v * 16 + (c <= '9' ? c - '0' : (tolower(c) - 'a' + 10));
                    }
                    if (v < 0x80) s += (char)v;
                    else if (v < 0x800) { s += (char)(0xc0 | (v >> 6)); s += (char)(0x80 | (v & 0x3f)); }
                    else { s += (char)(0xe0 | (v >> 12)); s += (char)(0x80 | ((v >> 6) & 0x3f)); s += (char)(0x80 | (v & 0x3f)); }
                    break;
                }
                default: s += *p; break;
            }
            ++p;
        } else s += *p++;
    }
    if (*p == '"') ++p;
    return true;
}

bool JParser::Parse(JVal &v)
{
    Ws();
    if (*p == '{') {
        v.kind = 5;
        ++p;
        Ws();
        if (*p == '}') { ++p; return true; }
        while (true) {
            Ws();
            std::string k;
            if (!Str(k)) return false;
            Ws();
            if (*p != ':') return false;
            ++p;
            JVal c;
            if (!Parse(c)) return false;
            v.obj.push_back({k, c});
            Ws();
            if (*p == ',') { ++p; continue; }
            if (*p == '}') { ++p; return true; }
            return false;
        }
    }
    if (*p == '[') {
        v.kind = 4;
        ++p;
        Ws();
        if (*p == ']') { ++p; return true; }
        while (true) {
            JVal c;
            if (!Parse(c)) return false;
            v.arr.push_back(c);
            Ws();
            if (*p == ',') { ++p; continue; }
            if (*p == ']') { ++p; return true; }
            return false;
        }
    }
    if (*p == '"') { v.kind = 3; return Str(v.str); }
    if (*p == 't') { if (!strncmp(p, "true", 4)) { p += 4; v.kind = 1; v.b = true; return true; } return false; }
    if (*p == 'f') { if (!strncmp(p, "false", 5)) { p += 5; v.kind = 1; return true; } return false; }
    if (*p == 'n') { if (!strncmp(p, "null", 4)) { p += 4; return true; } return false; }
    char *end = nullptr;
    double d = strtod(p, &end);
    if (end == p) return false;
    v.kind = 2;
    v.num = d;
    p = end;
    return true;
}

/* ------------------------------------------------------------------ */
/* GeoJSON helpers                                                     */
/* ------------------------------------------------------------------ */
static void JValToGeom(const JVal &v, Geometry &g);

static void CoordToPt(const JVal &v, Geometry &g)
{
    if (v.kind != 4 || v.arr.empty()) return;
    std::vector<double> pt;
    for (auto &c : v.arr) pt.push_back(c.num);
    if (pt.size() > (size_t)g.dims) g.dims = (int)pt.size();
    g.pts.push_back(pt);
}

static void JValToGeom(const JVal &v, Geometry &g)
{
    std::string ty = ToLower(v.Str("type"));
    const JVal *coords = v.Get("coordinates");
    if (ty == "point") {
        g.type = "Point";
        if (coords) CoordToPt(*coords, g);
    } else if (ty == "multipoint") {
        g.type = "MultiPoint";
        if (coords)
            for (auto &c : coords->arr) {
                Geometry sub;
                sub.type = "Point";
                sub.dims = g.dims;
                CoordToPt(c, sub);
                g.parts.push_back(sub);
            }
    } else if (ty == "linestring") {
        g.type = "LineString";
        if (coords)
            for (auto &c : coords->arr) CoordToPt(c, g);
    } else if (ty == "multilinestring") {
        g.type = "MultiLineString";
        if (coords)
            for (auto &c : coords->arr) {
                Geometry sub;
                sub.type = "LineString";
                sub.dims = g.dims;
                for (auto &c2 : c.arr) CoordToPt(c2, sub);
                g.parts.push_back(sub);
            }
    } else if (ty == "polygon") {
        g.type = "Polygon";
        if (coords)
            for (auto &c : coords->arr) {
                Geometry sub;
                sub.type = "LineString";
                sub.dims = g.dims;
                for (auto &c2 : c.arr) CoordToPt(c2, sub);
                g.parts.push_back(sub);
            }
    } else if (ty == "multipolygon") {
        g.type = "MultiPolygon";
        if (coords)
            for (auto &c : coords->arr) {
                Geometry poly;
                poly.type = "Polygon";
                poly.dims = g.dims;
                for (auto &c2 : c.arr) {
                    Geometry ring;
                    ring.type = "LineString";
                    ring.dims = g.dims;
                    for (auto &c3 : c2.arr) CoordToPt(c3, ring);
                    poly.parts.push_back(ring);
                }
                g.parts.push_back(poly);
            }
    } else if (ty == "geometrycollection") {
        g.type = "GeometryCollection";
        const JVal *gs = v.Get("geometries");
        if (gs)
            for (auto &c : gs->arr) {
                Geometry sub;
                JValToGeom(c, sub);
                g.parts.push_back(sub);
            }
    }
}

static void GeomToJson(const Geometry &g, std::string &out, bool compact);

static std::string CoordStr(const std::vector<double> &p)
{
    std::string s = "[";
    for (size_t i = 0; i < p.size(); ++i) {
        if (i) s += ",";
        s += FormatReal(p[i]);
    }
    s += "]";
    return s;
}

static void GeomToJson(const Geometry &g, std::string &out, bool compact)
{
    std::string t = g.type.empty() ? "Unknown" : g.type;
    if (t == "LineString" && g.parts.empty() && g.pts.size() == 2) t = "LineString";
    std::string ty = t;
    if (ty == "LineString") ty = "LineString";
    out += "{\"type\":\"" + ty + "\",";
    if (g.parts.empty()) {
        out += "\"coordinates\":[";
        for (size_t i = 0; i < g.pts.size(); ++i) {
            if (i) out += ",";
            out += CoordStr(g.pts[i]);
        }
        out += "]}";
    } else {
        if (g.type == "GeometryCollection") {
            out += "\"geometries\":[";
            for (size_t i = 0; i < g.parts.size(); ++i) {
                if (i) out += ",";
                GeomToJson(g.parts[i], out, compact);
            }
            out += "]}";
            return;
        }
        out += "\"coordinates\":[";
        for (size_t i = 0; i < g.parts.size(); ++i) {
            if (i) out += ",";
            const Geometry &sub = g.parts[i];
            if (g.type == "MultiPolygon") {
                out += "[";
                for (size_t j = 0; j < sub.parts.size(); ++j) {
                    if (j) out += ",";
                    out += "[";
                    for (size_t k = 0; k < sub.parts[j].pts.size(); ++k) {
                        if (k) out += ",";
                        out += CoordStr(sub.parts[j].pts[k]);
                    }
                    out += "]";
                }
                out += "]";
            } else if (g.type == "Polygon" || g.type == "MultiLineString") {
                out += "[";
                for (size_t k = 0; k < sub.pts.size(); ++k) {
                    if (k) out += ",";
                    out += CoordStr(sub.pts[k]);
                }
                out += "]";
            } else {
                out += "[";
                for (size_t k = 0; k < sub.pts.size(); ++k) {
                    if (k) out += ",";
                    out += CoordStr(sub.pts[k]);
                }
                out += "]";
            }
        }
        out += "]}";
    }
}

std::string GeometryToJson(const Geometry &g) { std::string s; GeomToJson(g, s, false); return s; }

