        if (props) crsName = props->Str("name");
    }
    const JVal *feats = v.Get("features");
    if (!feats) {
        const JVal *geom = v.Get("geometry");
        if (geom) { /* single geometry file */ }
        feats = v.Get("features");
    }
    std::string layerName;
    const JVal *nm = v.Get("name");
    if (nm && nm->kind == 3) layerName = nm->str;
    if (!layerName.empty()) ly.name = layerName;
    if (feats) {
        for (auto &fv : feats->arr) {
            Feature ft;
            ft.fid = (long long)ly.features.size() + 1;
            const JVal *props = fv.Get("properties");
            if (props) {
                CollectFields(*props, ly.fields);
                ft.values.resize(props->obj.size());
                size_t i = 0;
                for (auto &p : props->obj) {
                    Value vv;
                    ValueFromJVal(p.second, vv);
                    ft.values.push_back(vv);
                    (void)i;
                }
                /* align values with fields order */
                ft.values.clear();
                for (auto &fd : ly.fields) {
                    const JVal *pv = props->Get(fd.name.c_str());
                    Value vv;
                    if (pv) ValueFromJVal(*pv, vv);
                    ft.values.push_back(vv);
                }
            }
            const JVal *gj = fv.Get("geometry");
            if (gj && gj->kind == 5) JValToGeom(*gj, ft.geom);
            ly.features.push_back(ft);
        }
    }
    if (ly.features.size()) {
        double minx, miny, maxx, maxy;
        ly.features[0].geom.Bounds(minx, miny, maxx, maxy);
