            f.geom.Bounds(a, b, c, dd);
            if (a < minx) minx = a;
            if (b < miny) miny = b;
            if (c > maxx) maxx = c;
            if (dd > maxy) maxy = dd;
        }
        ly.geomType = ly.features[0].geom.type.empty() ? "Unknown" : ly.features[0].geom.type;
        for (auto &f : ly.features) {
            if (!f.geom.IsEmpty() && f.geom.type != ly.geomType) {
                if ((ly.geomType == "Point" && f.geom.type == "MultiPoint") ||
                    (ly.geomType == "LineString" && f.geom.type == "MultiLineString") ||
                    (ly.geomType == "Polygon" && f.geom.type == "MultiPolygon"))
                    ly.geomType = f.geom.type;
                else if (ly.geomType != "Unknown") { ly.geomType = "Unknown"; break; }
            }
        }
    }
    if (!crsName.empty()) {
        CRS c = CRS::FromUserInput(crsName);
        if (c.valid) ly.srsWkt = c.wkt;
    }
    ds.layers.push_back(ly);
    return true;
}

