/* ------------------------------------------------------------------ */
/* ESRI Shapefile                                                      */
/* ------------------------------------------------------------------ */
static int ShpShapeOf(const std::string &geomType)
{
    std::string t = ToLower(geomType);
    if (t == "point") return 1;
    if (t == "multipoint") return 8;
    if (t == "linestring") return 3;
    if (t == "polygon") return 5;
    return 1;
}

static void WriteShapefile(const VectorDataset &ds, const std::string &path)
{
    std::string base = path;
    size_t q = base.rfind('.');
    std::string ext = (q == std::string::npos) ? "" : ToLower(base.substr(q + 1));
    if (ext == "shp" || ext == "dbf" || ext == "shx") base = base.substr(0, q);
    Layer *ly = ds.layers.empty() ? nullptr : &ds.layers[0];
    int shapeType = ly ? ShpShapeOf(ly->geomType) : 1;
    int nrec = ly ? (int)ly->features.size() : 0;

