    std::string dbfpath = base + ".dbf";
    std::vector<std::vector<std::string> > rows;
    std::vector<FieldDef> flds;
    if (ly) {
        for (auto &f : ly->fields) {
            FieldDef fd = f;
            if (fd.type == OFT_Real) { fd.width = 24; fd.precision = 15; }
            else if (fd.type == OFT_Integer) { fd.width = 11; fd.precision = 0; }
            else if (fd.type == OFT_Integer64) { fd.width = 18; fd.precision = 0; }
            else if (fd.type == OFT_Date || fd.type == OFT_Time || fd.type == OFT_DateTime) { fd.type = OFT_String; fd.width = 32; }
            else if (fd.type == OFT_String) { fd.width = 80; }
            else { fd.type = OFT_String; fd.width = 80; }
            flds.push_back(fd);
        }
        for (auto &ft : ly->features) {
            std::vector<std::string> row;
            for (size_t i = 0; i < flds.size(); ++i) {
                const Value &v = (i < ft.values.size()) ? ft.values[i] : Value();
                if (v.isNull) { row.push_back(""); continue; }
                char buf[256];
                switch (flds[i].type) {
                    case OFT_Integer: snprintf(buf, sizeof(buf), "%lld", v.i); break;
                    case OFT_Integer64: snprintf(buf, sizeof(buf), "%lld", v.i); break;
                    case OFT_Real: snprintf(buf, sizeof(buf), "%.*f", flds[i].precision, v.d); break;
                    default: strncpy(buf, v.s.c_str(), sizeof(buf) - 1); buf[sizeof(buf) - 1] = 0; break;
                }
                row.push_back(buf);
            }
            rows.push_back(row);
        }
    }
    {
        FILE *f = fopen(dbfpath.c_str(), "wb");
        if (!f) return;
        int hdrSize = 32 + 32 * (int)flds.size() + 1;
        int recSize = 1;
        for (auto &fd : flds) recSize += fd.width;
        fputc(0x03, f);
        unsigned char yy = (unsigned char)(2025 - 1900), mm = 1, dd = 1;
        fwrite(&yy, 1, 1, f); fwrite(&mm, 1, 1, f); fwrite(&dd, 1, 1, f);
        uint32_t nrec32 = (uint32_t)nrec;
        uint16_t h16 = (uint16_t)hdrSize, r16 = (uint16_t)recSize;
        fwrite(&nrec32, 4, 1, f);
        fwrite(&h16, 2, 1, f);
        fwrite(&r16, 2, 1, f);
        for (int i = 0; i < 20; ++i) fputc(0, f);
        for (auto &fd : flds) {
            char nm[11];
            memset(nm, 0, sizeof(nm));
            strncpy(nm, fd.name.c_str(), 10);
            fwrite(nm, 1, 11, f);
            char type = 'C';
            if (fd.type == OFT_Integer) type = 'N';
            else if (fd.type == OFT_Integer64) type = 'N';
            else if (fd.type == OFT_Real) type = 'N';
            else if (fd.type == OFT_Date) type = 'D';
            fputc(type, f);
            uint32_t addr = 0;
            fwrite(&addr, 4, 1, f);
            uint8_t len = (uint8_t)fd.width, dec = (uint8_t)fd.precision;
            fwrite(&len, 1, 1, f);
            fwrite(&dec, 1, 1, f);
            for (int i = 0; i < 14; ++i) fputc(0, f);
        }
        fputc(0x0d, f);
        for (auto &row : rows) {
            fputc(' ', f);
            for (size_t i = 0; i < flds.size(); ++i) {
                std::string v = (i < row.size()) ? row[i] : "";
                if ((int)v.size() > flds[i].width) v = v.substr(0, flds[i].width);
                if (flds[i].type == OFT_Real || flds[i].type == OFT_Integer || flds[i].type == OFT_Integer64) {
                    for (int k = (int)v.size(); k < flds[i].width; ++k) fputc(' ', f);
                    fwrite(v.data(), 1, v.size(), f);
                } else {
                    fwrite(v.data(), 1, v.size(), f);
                    for (int k = (int)v.size(); k < flds[i].width; ++k) fputc(' ', f);
                }
            }
        }
        fputc(0x1a, f);
        fclose(f);
    }
    if (!ly) return;
    /* --- .shp / .shx --- */
    std::string shppath = base + ".shp", shxpath = base + ".shx";
    std::vector<uint32_t> offsets;
    std::vector<uint32_t> lengths;
    std::string body;
    double minx = 0, miny = 0, maxx = 0, maxy = 0, minz = 0, maxz = 0, minm = 0, maxm = 0;
    bool any = false;
    std::string content;
    int idx = 0;
    for (auto &ft : ly->features) {
        offsets.push_back((uint32_t)(50 + body.size() / 2));
        std::string rec;
        uint32_t recLenWords = 0;
        std::string geom;
        double bx0 = 0, by0 = 0, bx1 = 0, by1 = 0;
        bool hasBox = false;
        int nParts = 0, nPts = 0;
        std::vector<int> parts;
        std::string ptsData;
        if (ft.geom.IsEmpty()) {
            /* null shape */
            int t = 0;
            geom.append((const char *)&t, 4);
        } else {
            double b[4];
            ft.geom.Bounds(b[0], b[1], b[2], b[3]);
            hasBox = true;
            bx0 = b[0]; by0 = b[1]; bx1 = b[2]; by1 = b[3];
            int t = shapeType;
            geom.append((const char *)&t, 4);
            geom.append((const char *)b, 32);
            if (shapeType == 1) {
                double x = ft.geom.pts[0][0], y = ft.geom.pts[0][1];
                geom.append((const char *)&x, 8);
                geom.append((const char *)&y, 8);
            } else if (shapeType == 8) {
                int32_t n = (int32_t)ft.geom.parts.size();
                geom.append((const char *)&n, 4);
                geom.append((const char *)b, 32);
                for (auto &p : ft.geom.parts) {
                    double x = p.pts[0][0], y = p.pts[0][1];
                    geom.append((const char *)&x, 8);
                    geom.append((const char *)&y, 8);
                }
            } else {
                /* linestring / polygon with parts */
                std::vector<std::vector<double> > all;
                for (auto &p : ft.geom.parts) {
                    parts.push_back((int)all.size());
                    for (auto &pt : p.pts) all.push_back(pt);
                }
                if (all.empty()) for (auto &pt : ft.geom.pts) all.push_back(pt);
                int32_t np = (int32_t)parts.size();
                int32_t npt = (int32_t)all.size();
                geom.append((const char *)&np, 4);
                geom.append((const char *)&npt, 4);
                geom.append((const char *)b, 32);
                geom.append((const char *)parts.data(), 4 * parts.size());
                for (auto &p : all) {
                    geom.append((const char *)&p[0], 8);
                    geom.append((const char *)&p[1], 8);
                }
            }
        }
        recLenWords = (uint32_t)(geom.size() + 8) / 2;
        body += geom;
        lengths.push_back(recLenWords);
        if (hasBox) {
            if (!any) { minx = bx0; miny = by0; maxx = bx1; maxy = by1; any = true; }
            else {
                if (bx0 < minx) minx = bx0;
                if (by0 < miny) miny = by0;
                if (bx1 > maxx) maxx = bx1;
                if (by1 > maxy) maxy = by1;
            }
        }
        idx++;
    }
    {
        FILE *f = fopen(shppath.c_str(), "wb");
        if (!f) return;
        uint32_t fileCode = 9994;
        uint32_t unused[5] = {0, 0, 0, 0, 0};
        uint32_t fileLenWords = (uint32_t)((50 + body.size()) / 2);
        uint32_t version = 1000, shpType = (uint32_t)shapeType;
        fwrite(&fileCode, 4, 1, f);
        fwrite(unused, 4, 5, f);
        uint32_t fl = ((fileLenWords & 0xff) << 24) | (((fileLenWords >> 8) & 0xff) << 16) |
                      (((fileLenWords >> 16) & 0xff) << 8) | ((fileLenWords >> 24) & 0xff);
        fwrite(&fl, 4, 1, f);
        fwrite(&version, 4, 1, f);
        fwrite(&shpType, 4, 1, f);
        double b[8] = {minx, miny, maxx, maxy, minz, minm, maxz, maxm};
        if (!any) memset(b, 0, sizeof(b));
        fwrite(b, 8, 8, f);
        fwrite(body.data(), 1, body.size(), f);
        fclose(f);
    }
    {
        FILE *f = fopen(shxpath.c_str(), "wb");
        if (!f) return;
        uint32_t fileCode = 9994;
        uint32_t unused[5] = {0, 0, 0, 0, 0};
        uint32_t fileLenWords = (uint32_t)((50 + 8 * offsets.size()) / 2);
        fwrite(&fileCode, 4, 1, f);
        fwrite(unused, 4, 5, f);
        uint32_t fl = ((fileLenWords & 0xff) << 24) | (((fileLenWords >> 8) & 0xff) << 16) |
                      (((fileLenWords >> 16) & 0xff) << 8) | ((fileLenWords >> 24) & 0xff);
        fwrite(&fl, 4, 1, f);
        uint32_t version = 1000, shpType = (uint32_t)shapeType;
        fwrite(&version, 4, 1, f);
        fwrite(&shpType, 4, 1, f);
        double b[8] = {minx, miny, maxx, maxy, minz, minm, maxz, maxm};
        if (!any) memset(b, 0, sizeof(b));
        fwrite(b, 8, 8, f);
        for (size_t i = 0; i < offsets.size(); ++i) {
            uint32_t off = offsets[i];
            uint32_t len = lengths[i];
            uint32_t o = ((off & 0xff) << 24) | (((off >> 8) & 0xff) << 16) | (((off >> 16) & 0xff) << 8) | ((off >> 24) & 0xff);
            uint32_t l = ((len & 0xff) << 24) | (((len >> 8) & 0xff) << 16) | (((len >> 16) & 0xff) << 8) | ((len >> 24) & 0xff);
            fwrite(&o, 4, 1, f);
            fwrite(&l, 4, 1, f);
        }
        fclose(f);
    }
}

/* ------------------------------------------------------------------ */
/* Shapefile reader                                                    */
/* ------------------------------------------------------------------ */
static bool ReadShapefile(const std::string &path, VectorDataset &ds)
{
    std::string base = path;
    size_t q = base.rfind('.');
    std::string ext = (q == std::string::npos) ? "" : ToLower(base.substr(q + 1));
    std::string shppath = base;
    if (ext == "dbf" || ext == "shx") { base = base.substr(0, q); shppath = base + ".shp"; }
    else if (ext != "shp") shppath = base + ".shp";
    if (!FileExists(shppath)) shppath = base + ".dbf";
    if (!FileExists(shppath)) return false;
    ds.driverShort = "ESRI Shapefile";
    ds.driverLong = "ESRI Shapefile";
    ds.name = base;
    ds.files.push_back(base + ".shp");
    if (FileExists(base + ".dbf")) ds.files.push_back(base + ".dbf");
    if (FileExists(base + ".shx")) ds.files.push_back(base + ".shx");
    if (FileExists(base + ".prj")) ds.files.push_back(base + ".prj");

    Layer ly;
    ly.name = BaseName(base);
    /* .prj */
    if (FileExists(base + ".prj")) {
        bool ok = false;
        std::string prj = ReadWholeFile(base + ".prj", ok);
        if (ok && !Trim(prj).empty()) {
            CRS c = CRS::FromUserInput(Trim(prj));
            if (c.valid) ly.srsWkt = c.wkt;
        }
    }
    /* .dbf */
    bool ok = false;
    std::string dbf = ReadWholeFile(base + ".dbf", ok);
    std::vector<std::vector<std::string> > rows;
    if (ok && dbf.size() > 33) {
        uint32_t nrec = *(const uint32_t *)&dbf[4];
        uint16_t hdr = *(const uint16_t *)&dbf[8];
        uint16_t recsz = *(const uint16_t *)&dbf[10];
        size_t pos = 32;
        while (pos + 32 <= (size_t)hdr && dbf[pos] != 0x0d) {
            FieldDef fd;
            fd.name = std::string(dbf.data() + pos, 11);
            size_t z = fd.name.find('\0');
            if (z != std::string::npos) fd.name = fd.name.substr(0, z);
            while (!fd.name.empty() && fd.name[fd.name.size() - 1] == ' ') fd.name.pop_back();
            char t = dbf[pos + 11];
            fd.width = (unsigned char)dbf[pos + 16];
            fd.precision = (unsigned char)dbf[pos + 17];
            if (t == 'N') fd.type = (fd.precision > 0) ? OFT_Real : OFT_Integer;
            else if (t == 'D') fd.type = OFT_Date;
            else fd.type = OFT_String;
            ly.fields.push_back(fd);
            pos += 32;
        }
        for (uint32_t r = 0; r < nrec; ++r) {
            size_t p = (size_t)hdr + (size_t)r * recsz;
            if (p + recsz > dbf.size()) break;
            std::vector<std::string> row;
            size_t pp = p + 1;
            for (auto &fd : ly.fields) {
                std::string v = dbf.substr(pp, fd.width);
                while (!v.empty() && (v[v.size() - 1] == ' ')) v.pop_back();
                while (!v.empty() && v[0] == ' ') v.erase(0, 1);
                pp += fd.width;
                row.push_back(v);
            }
            rows.push_back(row);
        }
    }
    /* .shp */
    bool ok2 = false;
    std::string shp = ReadWholeFile(shppath, ok2);
    int shapeType = 0;
    std::vector<std::pair<uint32_t, uint32_t> > index;
    if (ok2 && shp.size() > 100) {
        uint32_t flWords = *(const uint32_t *)&shp[24];
        /* big endian */
        flWords = ((flWords & 0xff) << 24) | (((flWords >> 8) & 0xff) << 16) | (((flWords >> 16) & 0xff) << 8) | ((flWords >> 24) & 0xff);
        shapeType = *(const int32_t *)&shp[32];
        uint32_t nrec = (flWords * 2 - 100) / 8;
        for (uint32_t i = 0; i < nrec; ++i) {
            size_t p = 100 + (size_t)i * 8;
            if (p + 8 > shp.size()) break;
            uint32_t off = *(const uint32_t *)&shp[p];
            uint32_t len = *(const uint32_t *)&shp[p + 4];
            off = ((off & 0xff) << 24) | (((off >> 8) & 0xff) << 16) | (((off >> 16) & 0xff) << 8) | ((off >> 24) & 0xff);
            len = ((len & 0xff) << 24) | (((len >> 8) & 0xff) << 16) | (((len >> 16) & 0xff) << 8) | ((len >> 24) & 0xff);
            index.push_back({off, len});
        }
    }
    if (shapeType == 1) ly.geomType = "Point";
    else if (shapeType == 8) ly.geomType = "MultiPoint";
    else if (shapeType == 3) ly.geomType = "LineString";
    else if (shapeType == 5) ly.geomType = "Polygon";
    else ly.geomType = "Unknown";
    size_t n = rows.size() > index.size() ? rows.size() : index.size();
    for (size_t i = 0; i < n; ++i) {
        Feature ft;
        ft.fid = (long long)i + 1;
        if (i < rows.size()) {
            ft.values.resize(rows[i].size());
            for (size_t j = 0; j < rows[i].size(); ++j) {
                Value v;
                v.isNull = rows[i][j].empty();
                if (!v.isNull) {
                    if (ly.fields[j].type == OFT_Real) v.d = StrDbl(rows[i][j], 0);
                    else if (ly.fields[j].type == OFT_Integer) v.i = strtoll(rows[i][j].c_str(), nullptr, 10);
                    v.s = rows[i][j];
                    v.d = (ly.fields[j].type == OFT_Real) ? StrDbl(rows[i][j], 0) : (double)strtod(rows[i][j].c_str(), nullptr);
                    v.i = (long long)strtoll(rows[i][j].c_str(), nullptr, 10);
                }
                ft.values[j] = v;
            }
        }
        if (i < index.size()) {
            size_t off = (size_t)index[i].first * 2;
            uint32_t len = index[i].second;
            if (off + 8 + (size_t)len * 2 <= shp.size()) {
                const char *rec = shp.data() + off + 8;
                int t = *(const int32_t *)rec;
                Geometry g;
                if (t == 1) {
                    g.type = "Point";
                    g.dims = 2;
                    double x = *(const double *)(rec + 4), y = *(const double *)(rec + 12);
                    g.AddPoint(x, y);
                } else if (t == 8) {
                    g.type = "MultiPoint";
                    g.dims = 2;
                    int32_t np = *(const int32_t *)(rec + 40);
                    for (int32_t k = 0; k < np; ++k) {
                        size_t q2 = 44 + 16 * (size_t)k;
                        if (q2 + 16 > (size_t)len * 2) break;
                        g.parts.push_back(Geometry());
                        g.parts.back().type = "Point";
                        g.parts.back().dims = 2;
                        g.parts.back().AddPoint(*(const double *)(rec + q2), *(const double *)(rec + q2 + 8));
                    }
                } else if (t == 3 || t == 5) {
                    g.type = (t == 3) ? "LineString" : "Polygon";
                    g.dims = 2;
                    int32_t np = *(const int32_t *)(rec + 44);
                    int32_t npt = *(const int32_t *)(rec + 48);
                    const int32_t *parts = (const int32_t *)(rec + 52);
                    for (int32_t p2 = 0; p2 < np; ++p2) {
                        int start = parts[p2];
                        int end = (p2 + 1 < np) ? parts[p2 + 1] : npt;
                        Geometry ring;
                        ring.type = (t == 5) ? "LineString" : "LineString";
                        ring.dims = 2;
                        for (int k2 = start; k2 < end; ++k2) {
                            size_t q2 = 52 + 4 * (size_t)np + 16 * (size_t)k2;
                            if (q2 + 16 > (size_t)len * 2) break;
                            ring.AddPoint(*(const double *)(rec + q2), *(const double *)(rec + q2 + 8));
                        }
                        g.parts.push_back(ring);
                    }
                } else {
                    g.type = "Unknown";
                }
                ft.geom = g;
            }
        }
        ly.features.push_back(ft);
    }
    if (ly.features.size()) {
        std::string t = ly.features[0].geom.type;
        for (auto &f : ly.features) if (!f.geom.IsEmpty() && f.geom.type != t) { t = "Unknown"; break; }
        if (t.empty() || t == "UNKNOWN") t = ly.geomType;
        ly.geomType = t.empty() ? "Unknown" : t;
    }
    ds.layers.push_back(ly);
    return true;
}
