                if (v.isNull) { row.push_back(""); continue; }
                char buf[256];
                switch (flds[i].type) {
                    case OFT_Integer: snprintf(buf, sizeof(buf), "%lld", v.i); break;
                    case OFT_Integer64: snprintf(buf, sizeof(buf), "%lld", v.i); break;
                    case OFT_Real: snprintf(buf, sizeof(buf), "%.*f", flds[i].precision, v.d); break;
                    default: strncpy(buf, v.s.c_str(), sizeof(buf) - 1); buf[sizeof(buf) - 1] = 0; break;
                }
                row.push_back(buf);
            }
            rows.push_back(row);
        }
    }
    {
        FILE *f = fopen(dbfpath.c_str(), "wb");
        if (!f) return;
        int hdrSize = 32 + 32 * (int)flds.size() + 1;
        int recSize = 1;
        for (auto &fd : flds) recSize += fd.width;
        fputc(0x03, f);
        unsigned char yy = (unsigned char)(2025 - 1900), mm = 1, dd = 1;
        fwrite(&yy, 1, 1, f); fwrite(&mm, 1, 1, f); fwrite(&dd, 1, 1, f);
        uint32_t nrec32 = (uint32_t)nrec;
        uint16_t h16 = (uint16_t)hdrSize, r16 = (uint16_t)recSize;
        fwrite(&nrec32, 4, 1, f);
        fwrite(&h16, 2, 1, f);
        fwrite(&r16, 2, 1, f);
        for (int i = 0; i < 20; ++i) fputc(0, f);
        for (auto &fd : flds) {
            char nm[11];
            memset(nm, 0, sizeof(nm));
            strncpy(nm, fd.name.c_str(), 10);
            fwrite(nm, 1, 11, f);
            char type = 'C';
            if (fd.type == OFT_Integer) type = 'N';
            else if (fd.type == OFT_Integer64) type = 'N';
            else if (fd.type == OFT_Real) type = 'N';
            else if (fd.type == OFT_Date) type = 'D';
            fputc(type, f);
            uint32_t addr = 0;
            fwrite(&addr, 4, 1, f);
            uint8_t len = (uint8_t)fd.width, dec = (uint8_t)fd.precision;
            fwrite(&len, 1, 1, f);
            fwrite(&dec, 1, 1, f);
            for (int i = 0; i < 14; ++i) fputc(0, f);
        }
        fputc(0x0d, f);
        for (auto &row : rows) {
            fputc(' ', f);
            for (size_t i = 0; i < flds.size(); ++i) {
                std::string v = (i < row.size()) ? row[i] : "";
