        fwrite(&version, 4, 1, f);
        fwrite(&shpType, 4, 1, f);
        double b[8] = {minx, miny, maxx, maxy, minz, minm, maxz, maxm};
        if (!any) memset(b, 0, sizeof(b));
        fwrite(b, 8, 8, f);
        fwrite(body.data(), 1, body.size(), f);
        fclose(f);
    }
    {
        FILE *f = fopen(shxpath.c_str(), "wb");
        if (!f) return;
        uint32_t fileCode = 9994;
        uint32_t unused[5] = {0, 0, 0, 0, 0};
        uint32_t fileLenWords = (uint32_t)((50 + 8 * offsets.size()) / 2);
        fwrite(&fileCode, 4, 1, f);
        fwrite(unused, 4, 5, f);
        uint32_t fl = ((fileLenWords & 0xff) << 24) | (((fileLenWords >> 8) & 0xff) << 16) |
                      (((fileLenWords >> 16) & 0xff) << 8) | ((fileLenWords >> 24) & 0xff);
        fwrite(&fl, 4, 1, f);
        uint32_t version = 1000, shpType = (uint32_t)shapeType;
        fwrite(&version, 4, 1, f);
        fwrite(&shpType, 4, 1, f);
        double b[8] = {minx, miny, maxx, maxy, minz, minm, maxz, maxm};
        if (!any) memset(b, 0, sizeof(b));
        fwrite(b, 8, 8, f);
        for (size_t i = 0; i < offsets.size(); ++i) {
            uint32_t off = offsets[i];
            uint32_t len = lengths[i];
            uint32_t o = ((off & 0xff) << 24) | (((off >> 8) & 0xff) << 16) | (((off >> 16) & 0xff) << 8) | ((off >> 24) & 0xff);
            uint32_t l = ((len & 0xff) << 24) | (((len >> 8) & 0xff) << 16) | (((len >> 16) & 0xff) << 8) | ((len >> 24) & 0xff);
            fwrite(&o, 4, 1, f);
            fwrite(&l, 4, 1, f);
        }
        fclose(f);
    }
}

