/* Shapefile reader                                                    */
/* ------------------------------------------------------------------ */
static bool ReadShapefile(const std::string &path, VectorDataset &ds)
{
    std::string base = path;
    size_t q = base.rfind('.');
    std::string ext = (q == std::string::npos) ? "" : ToLower(base.substr(q + 1));
    std::string shppath = base;
    if (ext == "dbf" || ext == "shx") { base = base.substr(0, q); shppath = base + ".shp"; }
    else if (ext != "shp") shppath = base + ".shp";
    if (!FileExists(shppath)) shppath = base + ".dbf";
    if (!FileExists(shppath)) return false;
    ds.driverShort = "ESRI Shapefile";
    ds.driverLong = "ESRI Shapefile";
    ds.name = base;
    ds.files.push_back(base + ".shp");
    if (FileExists(base + ".dbf")) ds.files.push_back(base + ".dbf");
    if (FileExists(base + ".shx")) ds.files.push_back(base + ".shx");
    if (FileExists(base + ".prj")) ds.files.push_back(base + ".prj");

    Layer ly;
    ly.name = BaseName(base);
    /* .prj */
    if (FileExists(base + ".prj")) {
        bool ok = false;
        std::string prj = ReadWholeFile(base + ".prj", ok);
        if (ok && !Trim(prj).empty()) {
            CRS c = CRS::FromUserInput(Trim(prj));
            if (c.valid) ly.srsWkt = c.wkt;
        }
    }
    /* .dbf */
    bool ok = false;
    std::string dbf = ReadWholeFile(base + ".dbf", ok);
    std::vector<std::vector<std::string> > rows;
    if (ok && dbf.size() > 33) {
        uint32_t nrec = *(const uint32_t *)&dbf[4];
        uint16_t hdr = *(const uint16_t *)&dbf[8];
        uint16_t recsz = *(const uint16_t *)&dbf[10];
        size_t pos = 32;
        while (pos + 32 <= (size_t)hdr && dbf[pos] != 0x0d) {
            FieldDef fd;
            fd.name = std::string(dbf.data() + pos, 11);
            size_t z = fd.name.find('\0');
            if (z != std::string::npos) fd.name = fd.name.substr(0, z);
            while (!fd.name.empty() && fd.name[fd.name.size() - 1] == ' ') fd.name.pop_back();
            char t = dbf[pos + 11];
            fd.width = (unsigned char)dbf[pos + 16];
            fd.precision = (unsigned char)dbf[pos + 17];
            if (t == 'N') fd.type = (fd.precision > 0) ? OFT_Real : OFT_Integer;
            else if (t == 'D') fd.type = OFT_Date;
            else fd.type = OFT_String;
            ly.fields.push_back(fd);
            pos += 32;
        }
        for (uint32_t r = 0; r < nrec; ++r) {
            size_t p = (size_t)hdr + (size_t)r * recsz;
            if (p + recsz > dbf.size()) break;
            std::vector<std::string> row;
            size_t pp = p + 1;
            for (auto &fd : ly.fields) {
                std::string v = dbf.substr(pp, fd.width);
                while (!v.empty() && (v[v.size() - 1] == ' ')) v.pop_back();
                while (!v.empty() && v[0] == ' ') v.erase(0, 1);
                pp += fd.width;
                row.push_back(v);
            }
            rows.push_back(row);
        }
    }
    /* .shp */
    bool ok2 = false;
    std::string shp = ReadWholeFile(shppath, ok2);
    int shapeType = 0;
    std::vector<std::pair<uint32_t, uint32_t> > index;
    if (ok2 && shp.size() > 100) {
        uint32_t flWords = *(const uint32_t *)&shp[24];
        /* big endian */
        flWords = ((flWords & 0xff) << 24) | (((flWords >> 8) & 0xff) << 16) | (((flWords >> 16) & 0xff) << 8) | ((flWords >> 24) & 0xff);
        shapeType = *(const int32_t *)&shp[32];
        uint32_t nrec = (flWords * 2 - 100) / 8;
        for (uint32_t i = 0; i < nrec; ++i) {
            size_t p = 100 + (size_t)i * 8;
            if (p + 8 > shp.size()) break;
            uint32_t off = *(const uint32_t *)&shp[p];
            uint32_t len = *(const uint32_t *)&shp[p + 4];
            off = ((off & 0xff) << 24) | (((off >> 8) & 0xff) << 16) | (((off >> 16) & 0xff) << 8) | ((off >> 24) & 0xff);
            len = ((len & 0xff) << 24) | (((len >> 8) & 0xff) << 16) | (((len >> 16) & 0xff) << 8) | ((len >> 24) & 0xff);
            index.push_back({off, len});
        }
    }
    if (shapeType == 1) ly.geomType = "Point";
    else if (shapeType == 8) ly.geomType = "MultiPoint";
    else if (shapeType == 3) ly.geomType = "LineString";
    else if (shapeType == 5) ly.geomType = "Polygon";
    else ly.geomType = "Unknown";
    size_t n = rows.size() > index.size() ? rows.size() : index.size();
    for (size_t i = 0; i < n; ++i) {
        Feature ft;
        ft.fid = (long long)i + 1;
        if (i < rows.size()) {
            ft.values.resize(rows[i].size());
            for (size_t j = 0; j < rows[i].size(); ++j) {
                Value v;
                v.isNull = rows[i][j].empty();
                if (!v.isNull) {
                    if (ly.fields[j].type == OFT_Real) v.d = StrDbl(rows[i][j], 0);
                    else if (ly.fields[j].type == OFT_Integer) v.i = strtoll(rows[i][j].c_str(), nullptr, 10);
                    v.s = rows[i][j];
                    v.d = (ly.fields[j].type == OFT_Real) ? StrDbl(rows[i][j], 0) : (double)strtod(rows[i][j].c_str(), nullptr);
                    v.i = (long long)strtoll(rows[i][j].c_str(), nullptr, 10);
                }
                ft.values[j] = v;
            }
        }
        if (i < index.size()) {
            size_t off = (size_t)index[i].first * 2;
            uint32_t len = index[i].second;
            if (off + 8 + (size_t)len * 2 <= shp.size()) {
                const char *rec = shp.data() + off + 8;
                int t = *(const int32_t *)rec;
                Geometry g;
                if (t == 1) {
                    g.type = "Point";
                    g.dims = 2;
                    double x = *(const double *)(rec + 4), y = *(const double *)(rec + 12);
                    g.AddPoint(x, y);
                } else if (t == 8) {
                    g.type = "MultiPoint";
                    g.dims = 2;
                    int32_t np = *(const int32_t *)(rec + 40);
                    for (int32_t k = 0; k < np; ++k) {
                        size_t q2 = 44 + 16 * (size_t)k;
                        if (q2 + 16 > (size_t)len * 2) break;
                        g.parts.push_back(Geometry());
                        g.parts.back().type = "Point";
                        g.parts.back().dims = 2;
                        g.parts.back().AddPoint(*(const double *)(rec + q2), *(const double *)(rec + q2 + 8));
                    }
                } else if (t == 3 || t == 5) {
                    g.type = (t == 3) ? "LineString" : "Polygon";
                    g.dims = 2;
                    int32_t np = *(const int32_t *)(rec + 44);
                    int32_t npt = *(const int32_t *)(rec + 48);
                    const int32_t *parts = (const int32_t *)(rec + 52);
                    for (int32_t p2 = 0; p2 < np; ++p2) {
                        int start = parts[p2];
                        int end = (p2 + 1 < np) ? parts[p2 + 1] : npt;
                        Geometry ring;
                        ring.type = (t == 5) ? "LineString" : "LineString";
                        ring.dims = 2;
                        for (int k2 = start; k2 < end; ++k2) {
                            size_t q2 = 52 + 4 * (size_t)np + 16 * (size_t)k2;
                            if (q2 + 16 > (size_t)len * 2) break;
                            ring.AddPoint(*(const double *)(rec + q2), *(const double *)(rec + q2 + 8));
                        }
                        g.parts.push_back(ring);
                    }
                } else {
                    g.type = "Unknown";
                }
                ft.geom = g;
            }
        }
        ly.features.push_back(ft);
    }
    if (ly.features.size()) {
        std::string t = ly.features[0].geom.type;
        for (auto &f : ly.features) if (!f.geom.IsEmpty() && f.geom.type != t) { t = "Unknown"; break; }
        if (t.empty() || t == "UNKNOWN") t = ly.geomType;
        ly.geomType = t.empty() ? "Unknown" : t;
    }
    ds.layers.push_back(ly);
    return true;
}
