cat > /workspace/src/tiff.cpp <<'CEOF'
/* GeoTIFF reader/writer (classic TIFF, little endian) */
#include "gdal.h"
#include "port.h"
#include "spec.h"

#include <string.h>
#include <math.h>
#include <stdlib.h>

struct TiffTag {
    uint16_t tag;
    uint16_t type;     /* 2 ascii, 3 short, 4 long, 12 double */
    uint32_t count;
    uint32_t value;    /* inline or offset */
};

static const int kTypeSize[] = {0, 1, 1, 2, 4, 8, 1, 1, 2, 4, 8, 4, 8};

static void put16(std::string &s, uint16_t v)
{
    s += (char)(v & 0xff);
    s += (char)((v >> 8) & 0xff);
}
static void put32(std::string &s, uint32_t v)
{
    s += (char)(v & 0xff);
    s += (char)((v >> 8) & 0xff);
    s += (char)((v >> 16) & 0xff);
    s += (char)((v >> 24) & 0xff);
}
static void put64(std::string &s, uint64_t v)
{
    for (int i = 0; i < 8; ++i) s += (char)((v >> (8 * i)) & 0xff);
}
static void putd(std::string &s, double v)
{
    uint64_t u;
    memcpy(&u, &v, 8);
    put64(s, u);
}
static uint16_t get16(const unsigned char *p) { return (uint16_t)(p[0] | (p[1] << 8)); }
static uint32_t get32(const unsigned char *p)
{
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}
static double getd(const unsigned char *p)
{
    uint64_t u = 0;
    for (int i = 7; i >= 0; --i) u = (u << 8) | p[i];
    double d;
    memcpy(&d, &u, 8);
    return d;
}

struct GeoKeys {
    std::vector<uint16_t> keys;
    std::vector<double> doubles;
    std::string ascii;
};

/* Build the GeoTIFF keys for a CRS (only WGS 84 based systems are encoded). */
static void BuildGeoKeys(const CRS &crs, GeoKeys &gk)
{
    gk.keys.push_back(1); gk.keys.push_back(1); gk.keys.push_back(0);
    std::vector<std::array<uint16_t, 4> > k;
    auto add = [&](uint16_t id, uint16_t loc, uint16_t cnt, uint16_t val) {
        k.push_back({id, loc, cnt, val});
    };
    if (crs.isGeographic) {
        add(1024, 0, 1, 2);                       /* ModelTypeGeographic */
        add(1025, 0, 1, 1);                       /* RasterPixelIsArea */
        if (crs.code) add(2048, 0, 1, (uint16_t)crs.code);
        if (crs.code == 4326) {
            std::string cit = "WGS 84|";
            gk.ascii = cit;
            add(2049, 34737, (uint16_t)cit.size(), 0);
            add(2054, 0, 1, 9102);
            add(2057, 34736, 1, 0);               /* semi major */
            gk.doubles.push_back(6378137.0);
            add(2059, 34736, 1, 1);               /* inverse flattening */
            gk.doubles.push_back(298.257223563);
        }
    } else {
        add(1024, 0, 1, 1);                       /* ModelTypeProjected */
        add(1025, 0, 1, 1);
        if (crs.code) add(3072, 0, 1, (uint16_t)crs.code);
        if (crs.code) add(3074, 0, 1, 9001);      /* linear units metre */
    }
    gk.keys.push_back((uint16_t)k.size());
    for (auto &e : k) for (auto v : e) gk.keys.push_back(v);
}

std::string WriteTiff(const GDALDataset &ds)
{
    int nb = ds.nbands;
    size_t sampleSize = (size_t)DataTypeSize(ds.bands.empty() ? GDT_Byte : ds.bands[0].type);
    /* interleaved pixel storage */
    std::string pixels;
    pixels.reserve((size_t)ds.nx * ds.ny * nb * sampleSize);
    for (int y = 0; y < ds.ny; ++y) {
        for (int x = 0; x < ds.nx; ++x) {
            for (int b = 0; b < nb; ++b) {
                const RasterBand &band = ds.bands[b];
                size_t i = (size_t)y * ds.nx + x;
                size_t sz = (size_t)DataTypeSize(band.type);
                size_t off = i * sz;
                for (size_t k = 0; k < sz; ++k)
                    pixels += (char)(off + k < band.data.size() ? band.data[off + k] : 0);
            }
        }
    }
    CRS crs;
    if (!ds.srsWkt.empty()) crs = CRS::FromUserInput(ds.srsWkt);
    GeoKeys gk;
    if (crs.valid) BuildGeoKeys(crs, gk);
    /* metadata (GDAL_METADATA XML) */
    std::string metaXml;
    {
        std::string items;
        for (auto &dom : ds.metadata) {
            if (dom.first == "IMAGE_STRUCTURE") continue;
            for (auto &kv : dom.second) {
                if (kv.first == "AREA_OR_POINT") continue;
                items += "        <MDI key=\"" + kv.first + "\">" + kv.second + "</MDI>\n";
            }
        }
        if (!items.empty())
            metaXml = "<Metadata>\n" + items + "</Metadata>\n";
    }
    /* header layout */
    size_t ntags = 10;
    if (nb > 1) ntags += 2;                      /* BitsPerSample, SampleFormat */
    if (crs.valid) ntags += 2;                   /* pixel scale, tiepoint */
    if (crs.valid && (crs.code || crs.isGeographic)) ntags += 3;
    if (!metaXml.empty()) ntags += 1;
    if (nb > 1) ntags += 1;                      /* ExtraSamples */
    if (!metaXml.empty()) ntags += 1;
    std::string out = "II";
    out += (char)42;
    out += (char)0;
    put32(out, 8);

    /* compute offsets */
    size_t ifdOff = 8;
    size_t ifdSize = 2 + 12 * ntags + 4;
    size_t extraOff = ifdOff + ifdSize;
    std::string extra;
    std::vector<std::pair<uint16_t, size_t> > extraRef;   /* tag -> offset in extra */
    /* BitsPerSample / SampleFormat arrays */
    std::vector<uint16_t> bits, sf;
    for (int b = 0; b < nb; ++b) {
        GDataType t = ds.bands.empty() ? GDT_Byte : ds.bands[b].type;
        bits.push_back((uint16_t)(DataTypeSize(t) * 8));
        bool isFloat = (t == GDT_Float32 || t == GDT_Float64 || t == GDT_CFloat32 || t == GDT_CFloat64 || t == GDT_Float16);
        sf.push_back(isFloat ? 3 : 1);
    }
    /* Build the tag list in ascending order, then lay out the extra data. */
    struct TagInfo { uint16_t tag; uint16_t type; uint32_t count; std::string data; bool inlineOk; };
    std::vector<TagInfo> tags;
    auto addT = [&](uint16_t tag, uint16_t type, uint32_t count, const std::string &data) {
        TagInfo ti;
        ti.tag = tag; ti.type = type; ti.count = count;
        size_t sz = (size_t)kTypeSize[type] * count;
        ti.data = data;
        ti.inlineOk = sz <= 4;
        tags.push_back(ti);
    };
    addT(256, 3, 1, std::string((const char *)&(uint16_t){(uint16_t)ds.nx}, 2));
    addT(257, 3, 1, std::string((const char *)&(uint16_t){(uint16_t)ds.ny}, 2));
    if (nb > 1) {
        std::string b; for (auto v : bits) put16(b, v);
        addT(258, 3, (uint32_t)nb, b);
    }
    uint16_t comp = 1;
    addT(259, 3, 1, std::string((const char *)&comp, 2));
    uint16_t photo = (nb >= 3) ? 2 : 1;
    addT(262, 3, 1, std::string((const char *)&photo, 2));
    addT(273, 4, 1, std::string());               /* strip offsets - placeholder */
    uint16_t spp = (uint16_t)nb;
    addT(277, 3, 1, std::string((const char *)&spp, 2));
    uint16_t rps = (uint16_t)ds.ny;
    addT(278, 3, 1, std::string((const char *)&rps, 2));
    uint32_t sbc = (uint32_t)pixels.size();
    addT(279, 4, 1, std::string((const char *)&sbc, 4));
    uint16_t pc = 1;
    addT(284, 3, 1, std::string((const char *)&pc, 2));
    if (nb > 1) {
        uint16_t es = 0;
        addT(338, 3, 1, std::string((const char *)&es, 2));
        std::string f; for (auto v : sf) put16(f, v);
        addT(339, 3, (uint32_t)nb, f);
    } else {
        uint16_t f = sf.empty() ? 1 : sf[0];
        addT(339, 3, 1, std::string((const char *)&f, 2));
    }
    if (crs.valid) {
        std::string sc;
        putd(sc, ds.hasGeoTransform ? std::fabs(ds.geoTransform[1]) : 1.0);
        putd(sc, ds.hasGeoTransform ? std::fabs(ds.geoTransform[5]) : 1.0);
        putd(sc, 0.0);
        addT(33550, 12, 3, sc);
        std::string tp;
        putd(tp, 0.0); putd(tp, 0.0); putd(tp, 0.0);
        putd(tp, ds.hasGeoTransform ? ds.geoTransform[0] : 0.0);
        putd(tp, ds.hasGeoTransform ? ds.geoTransform[3] : 0.0);
        putd(tp, 0.0);
        addT(33922, 12, 6, tp);
    }
    if (!metaXml.empty()) {
        std::string m = metaXml;
        m += '\0';
        addT(42112, 2, (uint32_t)m.size(), m);
    }
    if (!gk.keys.empty()) {
        std::string kd;
        for (auto v : gk.keys) put16(kd, v);
        addT(34735, 3, (uint32_t)gk.keys.size(), kd);
        if (!gk.doubles.empty()) {
            std::string dd;
            for (auto v : gk.doubles) putd(dd, v);
            addT(34736, 12, (uint32_t)gk.doubles.size(), dd);
        }
        if (!gk.ascii.empty()) addT(34737, 2, (uint32_t)gk.ascii.size(), gk.ascii);
    }
    /* layout */
    size_t cursor = extraOff;
    for (auto &t : tags) {
        size_t sz = (size_t)kTypeSize[t.type] * t.count;
        if (sz > 4) { t.value = 0; cursor += sz + (sz & 1); }
    }
    size_t dataOff = cursor;
    /* assign extra offsets */
    size_t cur2 = extraOff;
    std::vector<uint32_t> offsets;
    for (auto &t : tags) {
        size_t sz = (size_t)kTypeSize[t.type] * t.count;
        if (sz > 4) { offsets.push_back((uint32_t)cur2); cur2 += sz + (sz & 1); }
        else offsets.push_back(0);
    }
    /* strip offsets tag position */
    size_t stripIdx = 0;
    for (size_t i = 0; i < tags.size(); ++i) if (tags[i].tag == 273) stripIdx = i;
    uint32_t stripOff = (uint32_t)dataOff;
    /* write the IFD */
    put16(out, (uint16_t)tags.size());
    for (size_t i = 0; i < tags.size(); ++i) {
        put16(out, tags[i].tag);
        put16(out, tags[i].type);
        put32(out, tags[i].count);
        if (tags[i].tag == 273) put32(out, stripOff);
        else if (offsets[i]) put32(out, offsets[i]);
        else {
            const std::string &d = tags[i].data;
            size_t sz = (size_t)kTypeSize[tags[i].type] * tags[i].count;
            std::string v = d;
            while (v.size() < 4) v += '\0';
            out += v.substr(0, 4);
        }
    }
    put32(out, 0);   /* next IFD */
    /* extra data */
    for (size_t i = 0; i < tags.size(); ++i) {
        size_t sz = (size_t)kTypeSize[tags[i].type] * tags[i].count;
        if (sz > 4) {
            out += tags[i].data;
            if (sz & 1) out += '\0';
        }
    }
    out += pixels;
    return out;
}

bool ReadTiff(const std::string &path, GDALDataset &ds)
{
    bool ok = false;
    std::string data = ReadWholeFile(path, ok);
    if (!ok || data.size() < 16) return false;
    bool le = (data[0] == 'I');
    (void)le;
    if (data[0] != 'I' || data[1] != 'I') return false;
    uint32_t ifd = get32((const unsigned char *)data.data() + 4);
    if (ifd + 2 > data.size()) return false;
    uint16_t ntags = get16((const unsigned char *)data.data() + ifd);
    std::map<uint16_t, TiffTag> tags;
    for (int i = 0; i < ntags; ++i) {
        size_t p = ifd + 2 + 12 * i;
        if (p + 12 > data.size()) break;
        TiffTag t;
        t.tag = get16((const unsigned char *)data.data() + p);
        t.type = get16((const unsigned char *)data.data() + p + 2);
        t.count = get32((const unsigned char *)data.data() + p + 4);
        memcpy(&t.value, data.data() + p + 8, 4);
        tags[t.tag] = t;
    }
    auto tagData = [&](uint16_t tag) -> std::string {
        auto it = tags.find(tag);
        if (it == tags.end()) return std::string();
        const TiffTag &t = it->second;
        size_t sz = (size_t)kTypeSize[t.type] * t.count;
        if (sz <= 4) return data.substr(ifd + 2 + 12 * (std::distance(tags.begin(), it)) + 8, sz);
        size_t off = t.value;
        if (off + sz > data.size()) return std::string();
        return data.substr(off, sz);
    };
    (void)tagData;
    if (!tags.count(256) || !tags.count(257)) return false;
    int nx = 0, ny = 0, nb = 1;
    {
        auto it = tags.find(256);
        std::string d = tagData(256);
        nx = (d.size() >= 2) ? get16((const unsigned char *)d.data()) : 0;
        d = tagData(257);
        ny = (d.size() >= 2) ? get16((const unsigned char *)d.data()) : 0;
        if (tags.count(277)) {
            std::string s = tagData(277);
            nb = (s.size() >= 2) ? get16((const unsigned char *)s.data()) : 1;
        }
    }
    ds.driverShort = "GTiff";
    ds.driverLong = "GeoTIFF";
    ds.name = path;
    ds.files.push_back(path);
    ds.nx = nx;
    ds.ny = ny;
    ds.nbands = nb;
    /* bits per sample / sample format */
    std::vector<int> bits(nb, 8), fmt(nb, 1);
    {
        std::string d = tagData(258);
        if (d.size() >= (size_t)2 * nb) for (int i = 0; i < nb; ++i) bits[i] = get16((const unsigned char *)d.data() + 2 * i);
        d = tagData(339);
        if (d.size() >= (size_t)2 * nb) for (int i = 0; i < nb; ++i) fmt[i] = get16((const unsigned char *)d.data() + 2 * i);
    }
    GDataType t = GDT_Byte;
    int b = bits.empty() ? 8 : bits[0];
    int f = fmt.empty() ? 1 : fmt[0];
    if (f == 3) t = (b == 32) ? GDT_Float32 : (b == 64 ? GDT_Float64 : GDT_Float16);
    else if (f == 2) t = (b == 16) ? GDT_CInt16 : (b == 32 ? GDT_CInt32 : GDT_CFloat32);
    else t = (b == 8) ? GDT_Byte : (b == 16 ? GDT_Int16 : GDT_Int32);
    std::string offsets = tagData(273);
    std::string counts = tagData(279);
    std::string pixels;
    if (!offsets.empty() && !counts.empty()) {
        uint32_t off = get32((const unsigned char *)offsets.data());
        uint32_t cnt = get32((const unsigned char *)counts.data());
        if (off + cnt <= data.size()) pixels = data.substr(off, cnt);
    }
    /* geotransform */
    std::string ps = tagData(33550), tp2 = tagData(33922);
    if (ps.size() >= 16 && tp2.size() >= 32) {
        double sx = getd((const unsigned char *)ps.data());
        double sy = getd((const unsigned char *)ps.data() + 8);
        double ox = getd((const unsigned char *)tp2.data() + 24);
        double oy = getd((const unsigned char *)tp2.data() + 32);
        ds.hasGeoTransform = true;
        ds.geoTransform[0] = ox;
        ds.geoTransform[1] = sx;
        ds.geoTransform[2] = 0;
        ds.geoTransform[3] = oy;
        ds.geoTransform[4] = 0;
        ds.geoTransform[5] = -std::fabs(sy);
    }
    /* geokeys */
    std::string kd = tagData(34735);
    std::string dd = tagData(34736);
    std::string ad = tagData(34737);
    if (kd.size() >= 8) {
        uint16_t nkeys = get16((const unsigned char *)kd.data() + 6);
        int gtype = 0;
        long long code = 0;
        for (int i = 0; i < nkeys; ++i) {
            size_t p = 8 + 8 * i;
            if (p + 8 > kd.size()) break;
            uint16_t id = get16((const unsigned char *)kd.data() + p);
