/* GeoTIFF reader/writer (classic TIFF, little endian) */
#include "gdal.h"
#include "port.h"
#include "spec.h"

#include <string.h>
#include <math.h>
#include <stdlib.h>

struct TiffTag {
    uint16_t tag;
    uint16_t type;     /* 2 ascii, 3 short, 4 long, 12 double */
    uint32_t count;
    uint32_t value;    /* inline or offset */
};

static const int kTypeSize[] = {0, 1, 1, 2, 4, 8, 1, 1, 2, 4, 8, 4, 8};

static void put16(std::string &s, uint16_t v)
{
    s += (char)(v & 0xff);
    s += (char)((v >> 8) & 0xff);
}
static void put32(std::string &s, uint32_t v)
{
    s += (char)(v & 0xff);
    s += (char)((v >> 8) & 0xff);
    s += (char)((v >> 16) & 0xff);
    s += (char)((v >> 24) & 0xff);
}
static void put64(std::string &s, uint64_t v)
{
    for (int i = 0; i < 8; ++i) s += (char)((v >> (8 * i)) & 0xff);
}
static void putd(std::string &s, double v)
{
    uint64_t u;
    memcpy(&u, &v, 8);
    put64(s, u);
}
static uint16_t get16(const unsigned char *p) { return (uint16_t)(p[0] | (p[1] << 8)); }
static uint32_t get32(const unsigned char *p)
{
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}
static double getd(const unsigned char *p)
{
    uint64_t u = 0;
    for (int i = 7; i >= 0; --i) u = (u << 8) | p[i];
    double d;
