    }
    out += "  <VRTRasterBand>\n";
    (void)srcName;
    out += "  </VRTRasterBand>\n";
    out += "</OGRVRTDataset>\n";
    return out;
}

/* ------------------------------------------------------------------ */
/* open / identify                                                     */
/* ------------------------------------------------------------------ */
static bool HasExt(const std::string &p, const char *e)
{
    std::string l = ToLower(p);
    size_t q = l.rfind('.');
    if (q == std::string::npos) return false;
    return l.substr(q + 1) == e;
}

std::string IdentifyDriver(const std::string &name, std::vector<std::string> &files)
{
    files.clear();
    std::string l = ToLower(name);
    if (HasExt(name, "tif") || HasExt(name, "tiff")) { files.push_back(name); return "GTiff"; }
    if (HasExt(name, "vrt")) { files.push_back(name); return "VRT"; }
    if (HasExt(name, "geojsonl") || HasExt(name, "geojsons")) { files.push_back(name); return "GeoJSONSeq"; }
    if (HasExt(name, "json") || HasExt(name, "geojson")) {
        bool ok = false;
        std::string d = ReadWholeFile(name, ok);
        if (ok) {
            std::string t = Trim(d);
            if (!t.empty() && t[0] == '{' && t.find("\"type\"") != std::string::npos) {
                JParser jp(d);
                JVal v;
                if (jp.Parse(v)) {
                    std::string ty = v.Str("type");
                    if (ty == "FeatureCollection" || ty == "Feature") { files.push_back(name); return "GeoJSON"; }
                    if (ty == "Topology") { files.push_back(name); return "TopoJSON"; }
                    if (ty == "esriFeatureCollection" || ty == "esriFeature") { files.push_back(name); return "ESRIJSON"; }
                }
            }
        }
        files.push_back(name);
        return "GeoJSON";
    }
    if (HasExt(name, "shp") || HasExt(name, "dbf") || HasExt(name, "shx")) {
        std::string base = name;
        size_t q2 = base.rfind('.');
        base = base.substr(0, q2);
        if (FileExists(base + ".shp")) files.push_back(base + ".shp");
        if (FileExists(base + ".dbf")) files.push_back(base + ".dbf");
        if (FileExists(base + ".shx")) files.push_back(base + ".shx");
        return "ESRI Shapefile";
    }
    if (HasExt(name, "topojson")) { files.push_back(name); return "TopoJSON"; }
    if (IsDirectory(name)) {
        for (auto &f : ListDir(name)) {
            std::string full = name + "/" + f;
            if (HasExt(full, "shp")) files.push_back(full);
        }
        if (!files.empty()) return "ESRI Shapefile";
    }
    return std::string();
}

GDALDataset *OpenRaster(const std::string &name, bool update, const std::vector<std::string> &openOptions,
                        std::vector<std::string> *filesOut)
{
    (void)openOptions;
    std::string drv = IdentifyDriver(name, *(filesOut ? *filesOut : *(new std::vector<std::string>())));
    if (drv.empty()) return nullptr;
    GDALDataset *ds = new GDALDataset();
    if (drv == "GTiff") {
        if (!ReadTiff(name, *ds)) { delete ds; return nullptr; }
    } else if (drv == "VRT") {
        /* VRT datasets are parsed by the vector module */
        delete ds;
        return nullptr;
    } else if (drv == "MEM") {
        delete ds;
        return nullptr;
    } else {
        delete ds;
        return nullptr;
    }
    ds->updateMode = update;
    return ds;
}

VectorDataset *OpenVector(const std::string &name, bool update, const std::vector<std::string> &openOptions,
