                            const std::vector<std::string> &co, const std::vector<std::string> &lco)
{
    (void)co;
    (void)lco;
    VectorDataset *ds = new VectorDataset();
    std::string fmt = format.empty() ? std::string() : format;
    if (fmt.empty()) {
        if (HasExt(name, "geojsonl") || HasExt(name, "geojsons")) fmt = "GeoJSONSeq";
        else if (HasExt(name, "shp")) fmt = "ESRI Shapefile";
        else fmt = "GeoJSON";
    }
    ds->driverShort = fmt;
    ds->driverLong = fmt;
    ds->name = name;
    ds->files.push_back(name);
    return ds;
}

void WriteVector(VectorDataset *ds)
{
    if (ds->driverShort == "ESRI Shapefile") WriteShapefile(*ds, ds->name);
    else WriteGeoJson(*ds, ds->name, ds->driverShort == "GeoJSONSeq");
}
