bool ReadGeoJsonSeq(const std::string &path, VectorDataset &ds)
{
    bool ok = false;
    std::string data = ReadWholeFile(path, ok);
    if (!ok) return false;
    ds.driverShort = "GeoJSONSeq";
    ds.driverLong = "GeoJSON Sequence";
    ds.name = path;
    ds.files.push_back(path);
    Layer ly;
    ly.name = BaseName(path);
    size_t q = ly.name.rfind('.');
    if (q != std::string::npos) ly.name = ly.name.substr(0, q);
    ly.hasFeatureCount = false;
    size_t pos = 0;
    while (pos < data.size()) {
        while (pos < data.size() && isspace((unsigned char)data[pos])) ++pos;
        if (pos >= data.size()) break;
        if (data[pos] != '{') break;
        JParser jp(data.substr(pos));
        JVal v;
        if (!jp.Parse(v)) break;
        pos += (jp.p - (data.c_str() + pos));
        std::string ty = ToLower(v.Str("type"));
        if (ty != "feature" && ty != "featurecollection") break;
        const JVal *feats = v.Get("features");
        if (ty == "featurecollection" && !feats) break;
        std::vector<const JVal *> list;
        if (ty == "feature") list.push_back(&v);
        else for (auto &f : feats->arr) list.push_back(&f);
        for (auto fv : list) {
            Feature ft;
            ft.fid = (long long)ly.features.size() + 1;
            const JVal *props = fv->Get("properties");
            if (props) {
                CollectFields(*props, ly.fields);
                ft.values.clear();
                for (auto &fd : ly.fields) {
                    const JVal *pv = props->Get(fd.name.c_str());
                    Value vv;
                    if (pv) ValueFromJVal(*pv, vv);
                    ft.values.push_back(vv);
                }
            }
            const JVal *gj = fv->Get("geometry");
            if (gj && gj->kind == 5) JValToGeom(*gj, ft.geom);
            ly.features.push_back(ft);
        }
    }
    if (ly.features.size()) ly.geomType = ly.features[0].geom.type.empty() ? "Unknown" : ly.features[0].geom.type;
    ds.layers.push_back(ly);
    return true;
}
