static int DoRasterInfo(Alg &alg)
{
    std::string name = alg.str("input");
    std::vector<std::string> files;
    GDALDataset *ds = OpenRaster(name, false, alg.lst("open-option"), &files);
    if (!ds) {
        CPLLError(4, "`" + name + "' not recognized as being in a supported file format.");
        return 1;
    }
    ds->files = files;
    bool json = (alg.str("output-format") == "json");
    (void)json;
    if (!alg.flag("no-fl") && false) {}
    if (json) {
        printf("{\n");
        printf("  \"description\":\"%s\",\n", JsonEscape(ds->name).c_str());
        printf("  \"driverShortName\":\"%s\",\n", JsonEscape(ds->driverShort).c_str());
        printf("  \"driverLongName\":\"%s\",\n", JsonEscape(ds->driverLong).c_str());
        printf("  \"files\":[\n");
        for (size_t i = 0; i < ds->files.size(); ++i)
            printf("    \"%s\"%s\n", JsonEscape(ds->files[i]).c_str(), (i + 1 < ds->files.size()) ? "," : "");
        printf("  ],\n");
        printf("  \"size\":[\n    %d,\n    %d\n  ],\n", ds->nx, ds->ny);
        printf("  \"metadata\":{\n");
        bool firstDom = true;
        for (auto &dom : ds->metadata) {
            if (dom.second.empty()) continue;
            printf("%s    \"%s\":{\n", firstDom ? "" : ",\n", JsonEscape(dom.first).c_str());
            firstDom = false;
            bool firstKv = true;
            for (auto &kv : dom.second) {
                printf("%s      \"%s\":\"%s\"", firstKv ? "" : ",\n", JsonEscape(kv.first).c_str(), JsonEscape(kv.second).c_str());
                firstKv = false;
            }
            printf("\n    }");
        }
        printf("\n  },\n");
        printf("  \"cornerCoordinates\":{\n");
        double ulx, uly, lrx, lry, llx, lly, urx, ury, cx, cy;
        if (ds->hasGeoTransform) {
            ulx = ds->geoTransform[0]; uly = ds->geoTransform[3];
            llx = ds->geoTransform[0]; lly = ds->geoTransform[3] + ds->ny * ds->geoTransform[5];
            urx = ds->geoTransform[0] + ds->nx * ds->geoTransform[1]; ury = ds->geoTransform[3];
            lrx = ds->geoTransform[0] + ds->nx * ds->geoTransform[1];
            lry = ds->geoTransform[3] + ds->ny * ds->geoTransform[5];
        } else {
            ulx = 0; uly = ds->ny; llx = 0; lly = 0; urx = ds->nx; ury = ds->ny; lrx = ds->nx; lry = 0;
        }
        cx = (ulx + lrx) / 2; cy = (uly + lry) / 2;
        auto emit = [&](const char *k, double a, double b, bool last) {
            printf("    \"%s\":[\n      %s,\n      %s\n    ]%s\n", k, FormatReal(a).c_str(), FormatReal(b).c_str(), last ? "" : ",");
        };
        printf("    \"upperLeft\":[\n      %s,\n      %s\n    ],\n", FormatReal(ulx).c_str(), FormatReal(uly).c_str());
        printf("    \"lowerLeft\":[\n      %s,\n      %s\n    ],\n", FormatReal(llx).c_str(), FormatReal(lly).c_str());
        printf("    \"lowerRight\":[\n      %s,\n      %s\n    ],\n", FormatReal(lrx).c_str(), FormatReal(lry).c_str());
        printf("    \"upperRight\":[\n      %s,\n      %s\n    ],\n", FormatReal(urx).c_str(), FormatReal(ury).c_str());
        printf("    \"center\":[\n      %s,\n      %s\n    ]\n", FormatReal(cx).c_str(), FormatReal(cy).c_str());
        printf("  },\n");
        printf("  \"bands\":[\n");
        for (size_t i = 0; i < ds->bands.size(); ++i) {
            RasterBand &b = ds->bands[i];
            printf("    {\n");
            printf("      \"band\":%d,\n", (int)i + 1);
            printf("      \"block\":[\n        %d,\n        %d\n      ],\n", b.blockX, b.blockY);
            printf("      \"type\":\"%s\",\n", DataTypeName(b.type).c_str());
            printf("      \"colorInterpretation\":\"%s\",\n", ColorInterpName(b.interp).c_str());
            if (b.noDataSet) printf("      \"noDataValue\":%s,\n", FormatReal(b.nodata).c_str());
            printf("      \"metadata\":{\n      }\n");
            printf("    }%s\n", (i + 1 < ds->bands.size()) ? "," : "");
        }
        printf("  ]\n");
        printf("}");
    } else {
        RasterInfoText(*ds);
    }
    delete ds;
    return 0;
}

