static void VectorInfoText(VectorDataset &ds)
{
    printf("INFO: Open of `%s'\n", ds.name.c_str());
    printf("      using driver `%s' successful.\n\n", ds.driverShort.c_str());
    for (auto &ly : ds.layers) {
        printf("Layer name: %s\n", ly.name.c_str());
        std::string gt = ly.geomType;
        printf("Geometry: %s\n", gt.c_str());
        printf("Feature Count: %d\n", (int)ly.features.size());
        double minx, miny, maxx, maxy;
        bool any = false;
        for (auto &f : ly.features) {
            double a, b, c, d;
            f.geom.Bounds(a, b, c, d);
            if (f.geom.IsEmpty()) continue;
            if (!any) { minx = a; miny = b; maxx = c; maxy = d; any = true; }
