                if (c > maxx) maxx = c;
                if (d > maxy) maxy = d;
            }
        }
        if (any) printf("Extent: (%f, %f) - (%f, %f)\n", minx, miny, maxx, maxy);
        if (!ly.srsWkt.empty()) {
            CRS c = CRS::FromUserInput(ly.srsWkt);
            printf("Layer Coordinate Reference System:\n");
            printf("  - name: %s\n", c.name.c_str());
            if (c.code) printf("  - ID: %s:%lld\n", c.authority.c_str(), c.code);
