    ds->files = files;
    if (alg.str("output-format") == "json") {
        printf("{\n");
        printf("  \"description\":\"%s\",\n", JsonEscape(ds->name).c_str());
        printf("  \"driverShortName\":\"%s\",\n", ds->driverShort.c_str());
        printf("  \"driverLongName\":\"%s\",\n", ds->driverLong.c_str());
        printf("  \"layers\":[\n");
        for (size_t i = 0; i < ds->layers.size(); ++i) {
            Layer &ly = ds->layers[i];
            printf("    {\n");
            printf("      \"name\":\"%s\",\n", JsonEscape(ly.name).c_str());
            printf("      \"metadata\":{\n      },\n");
            printf("      \"geometryFields\":[\n");
