            printf("          \"name\":\"\",\n");
            printf("          \"type\":\"%s\",\n", ly.geomType.c_str());
            printf("          \"nullable\":true,\n");
            printf("          \"extent\":[\n");
            double minx, miny, maxx, maxy;
            bool any = false;
            for (auto &f : ly.features) {
                double a, b, c, d;
                f.geom.Bounds(a, b, c, d);
                if (f.geom.IsEmpty()) continue;
                if (!any) { minx = a; miny = b; maxx = c; maxy = d; any = true; }
                else {
                    if (a < minx) minx = a;
                    if (b < miny) miny = b;
                    if (c > maxx) maxx = c;
                    if (d > maxy) maxy = d;
                }
            }
            if (any) printf("            %s,\n            %s,\n            %s,\n            %s\n",
                            FormatReal(minx).c_str(), FormatReal(miny).c_str(),
                            FormatReal(maxx).c_str(), FormatReal(maxy).c_str());
            printf("          ],\n");
            if (!ly.srsWkt.empty()) {
                CRS c = CRS::FromUserInput(ly.srsWkt);
                printf("          \"coordinateSystem\":{\n");
                printf("            \"wkt\":\"%s\",\n", JsonEscape(c.wkt).c_str());
                printf("            \"projjson\":%s,\n", c.ProjJson().c_str());
                printf("            \"dataAxisToSRSAxisMapping\":[\n");
                for (size_t k = 0; k < c.axisMapping.size(); ++k)
                    printf("            %d%s\n", c.axisMapping[k], (k + 1 < c.axisMapping.size()) ? "," : "");
                printf("            ]\n");
                printf("          },\n");
            }
            printf("          \"fields\":[\n");
            for (size_t j = 0; j < ly.fields.size(); ++j) {
                FieldDef &f = ly.fields[j];
                printf("            {\n");
                printf("              \"name\":\"%s\",\n", JsonEscape(f.name).c_str());
                printf("              \"type\":\"%s\",\n", FieldTypeName(f.type).c_str());
                printf("              \"subtype\":\"None\",\n");
                printf("              \"nullable\":true,\n");
                printf("              \"default\":null\n");
                printf("            }%s\n", (j + 1 < ly.fields.size()) ? "," : "");
            }
            printf("          ]\n");
            printf("        }\n");
            printf("      ]\n");
            printf("    }%s\n", (i + 1 < ds->layers.size()) ? "," : "");
        }
        printf("  ]\n}");
    } else {
        VectorInfoText(*ds);
    }
    delete ds;
    return 0;
}

/* ------------------------------------------------------------------ */
int CommandRun(Alg &alg)
{
    std::string p = alg.cmd->path;
    if (p == "raster/info") return DoRasterInfo(alg);
    if (p == "vector/info") return DoVectorInfo(alg);
    return 0;
}

int CommandRunAlias(const std::string &name, Alg &alg)
{
    (void)name;
    if (name == "info") {
        /* determine raster or vector from the file */
        std::string f = alg.str("input");
        std::vector<std::string> files;
        std::string drv = IdentifyDriver(f, files);
        if (drv == "GeoJSON" || drv == "ESRI Shapefile" || drv == "GeoJSONSeq") {
            CmdDef *vi = SpecFind("vector/info");
            Alg a2;
            a2.cmd = vi;
            ParseArgs(a2, std::vector<std::string>{f, "--output-format", alg.str("output-format")});
            return DoVectorInfo(a2);
        }
        CmdDef *ri = SpecFind("raster/info");
        Alg a2;
        a2.cmd = ri;
        ParseArgs(a2, std::vector<std::string>{f});
        return DoRasterInfo(a2);
    }
    return 0;
}

