static void DMS(double v, char *out, size_t n)
{
    char hemi = v >= 0 ? 'E' : 'W';
    double a = std::fabs(v);
    int d = (int)a;
    double rem = (a - d) * 60;
    int m = (int)rem;
    double s = (rem - m) * 60;
    /* round to 2 decimals and propagate */
    double sr = floor(s * 100 + 0.5) / 100.0;
    if (sr >= 60) { sr -= 60; m += 1; }
    if (m >= 60) { m -= 60; d += 1; }
    snprintf(out, n, "%dd%d'%.2f\"%c", d, m, sr, hemi);
}

