static void RasterInfoText(GDALDataset &ds)
{
    printf("Driver: %s/%s\n", ds.driverShort.c_str(), ds.driverLong.c_str());
    for (auto &f : ds.files) printf("Files: %s\n", f.c_str());
    printf("Size is %d, %d\n", ds.nx, ds.ny);
    if (!ds.srsWkt.empty()) {
        CRS c = CRS::FromUserInput(ds.srsWkt);
        printf("Coordinate Reference System:\n");
        printf("  - name: %s\n", c.name.c_str());
        if (c.code) printf("  - ID: %s:%lld\n", c.authority.c_str(), c.code);
        if (!c.type.empty()) printf("  - type: %s\n", c.type.c_str());
        if (!c.areaOfUse.empty()) printf("  - area of use: %s\n", c.areaOfUse.c_str());
        printf("Data axis to CRS axis mapping: ");
        for (size_t i = 0; i < c.axisMapping.size(); ++i) printf("%s%d", i ? "," : "", c.axisMapping[i]);
        printf("\n");
    }
    if (ds.hasGeoTransform)
        printf("Origin = (%.15f,%.15f)\nPixel Size = (%.15f,%.15f)\n",
               ds.geoTransform[0], ds.geoTransform[3], ds.geoTransform[1], ds.geoTransform[5]);
    /* metadata */
    for (auto &dom : ds.metadata) {
        if (dom.second.empty()) continue;
        if (dom.first == "IMAGE_STRUCTURE") continue;
        if (dom.first.empty()) printf("Metadata:\n");
        else printf("Metadata (%s):\n", dom.first.c_str());
        for (auto &kv : dom.second) printf("  %s=%s\n", kv.first.c_str(), kv.second.c_str());
    }
    for (auto &kv : ds.metadata["IMAGE_STRUCTURE"]) {
        printf("Image Structure Metadata:\n");
        printf("  %s=%s\n", kv.first.c_str(), kv.second.c_str());
        break;
    }
    double ulx, uly, llx, lly, urx, ury, lrx, lry, cx, cy;
    if (ds.hasGeoTransform) {
        ulx = ds.geoTransform[0]; uly = ds.geoTransform[3];
        llx = ds.geoTransform[0]; lly = ds.geoTransform[3] + ds.ny * ds.geoTransform[5];
        urx = ds.geoTransform[0] + ds.nx * ds.geoTransform[1]; ury = ds.geoTransform[3];
        lrx = ds.geoTransform[0] + ds.nx * ds.geoTransform[1];
        lry = ds.geoTransform[3] + ds.ny * ds.geoTransform[5];
        cx = (ulx + lrx) / 2; cy = (uly + lry) / 2;
    } else {
        ulx = 0; uly = ds.ny;
        llx = 0; lly = 0;
        urx = ds.nx; ury = ds.ny;
        lrx = ds.nx; lry = 0;
        cx = ds.nx / 2.0; cy = ds.ny / 2.0;
    }
    bool dms = ds.hasGeoTransform;
    printf("Corner Coordinates:\n");
    if (dms) {
        char b1[64], b2[64], b3[64], b4[64];
        CRS c = CRS::FromUserInput(ds.srsWkt);
        bool geographic = c.valid && c.isGeographic;
        (void)geographic;
        printf("%-11s (%12.7f,%12.7f) (%s, %s)\n", "Upper Left", ulx, uly, "", "");
    } else {
        PrintCorner("Upper Left", ulx, uly, false);
        PrintCorner("Lower Left", llx, lly, false);
        PrintCorner("Upper Right", urx, ury, false);
        PrintCorner("Lower Right", lrx, lry, false);
        PrintCorner("Center", cx, cy, false);
    }
    for (size_t i = 0; i < ds.bands.size(); ++i) {
        RasterBand &b = ds.bands[i];
        printf("Band %d Block=%dx%d Type=%s, ColorInterp=%s\n", (int)i + 1, b.blockX, b.blockY,
               DataTypeName(b.type), ColorInterpName(b.interp));
        if (b.noDataSet) printf("  NoData Value=%s\n", FormatReal(b.nodata).c_str());
        if (b.hasScale) printf("  Offset: %.15g,   Scale: %.15g\n", b.offset, b.scale);
        if (!b.unitType.empty()) printf("  Unit Type: %s\n", b.unitType.c_str());
        for (auto &kv : b.metadata)
            if (!kv.second.empty()) printf("  Metadata:\n    %s=%s\n", kv.first.c_str(), kv.second.c_str());
    }
}

