static void VectorInfoText(VectorDataset &ds)
{
    printf("INFO: Open of `%s'\n", ds.name.c_str());
    printf("      using driver `%s' successful.\n\n", ds.driverShort.c_str());
    for (auto &ly : ds.layers) {
        printf("Layer name: %s\n", ly.name.c_str());
        std::string gt = ly.geomType;
        printf("Geometry: %s\n", gt.c_str());
        printf("Feature Count: %d\n", (int)ly.features.size());
        double minx, miny, maxx, maxy;
        bool any = false;
        for (auto &f : ly.features) {
            double a, b, c, d;
            f.geom.Bounds(a, b, c, d);
            if (f.geom.IsEmpty()) continue;
            if (!any) { minx = a; miny = b; maxx = c; maxy = d; any = true; }
            else {
                if (a < minx) minx = a;
                if (b < miny) miny = b;
                if (c > maxx) maxx = c;
                if (d > maxy) maxy = d;
            }
        }
        if (any) printf("Extent: (%f, %f) - (%f, %f)\n", minx, miny, maxx, maxy);
        if (!ly.srsWkt.empty()) {
            CRS c = CRS::FromUserInput(ly.srsWkt);
            printf("Layer Coordinate Reference System:\n");
            printf("  - name: %s\n", c.name.c_str());
            if (c.code) printf("  - ID: %s:%lld\n", c.authority.c_str(), c.code);
            if (!c.type.empty()) printf("  - type: %s\n", c.type.c_str());
            printf("Data axis to CRS axis mapping: ");
            for (size_t i = 0; i < c.axisMapping.size(); ++i) printf("%s%d", i ? "," : "", c.axisMapping[i]);
            printf("\n");
        }
        for (auto &f : ly.fields) {
            std::string t = FieldTypeName(f.type);
            printf("%s: %s (%d.%d)\n", f.name.c_str(), t.c_str(), f.width, f.precision);
        }
    }
}

