                if (f.geom.IsEmpty()) continue;
                if (!any) { minx = a; miny = b; maxx = c; maxy = d; any = true; }
                else {
                    if (a < minx) minx = a;
                    if (b < miny) miny = b;
                    if (c > maxx) maxx = c;
                    if (d > maxy) maxy = d;
                }
            }
            if (any) printf("            %s,\n            %s,\n            %s,\n            %s\n",
                            FormatReal(minx).c_str(), FormatReal(miny).c_str(),
                            FormatReal(maxx).c_str(), FormatReal(maxy).c_str());
            printf("          ],\n");
