                for (size_t k = 0; k < c.axisMapping.size(); ++k)
                    printf("            %d%s\n", c.axisMapping[k], (k + 1 < c.axisMapping.size()) ? "," : "");
                printf("            ]\n");
                printf("          },\n");
            }
            printf("          \"fields\":[\n");
            for (size_t j = 0; j < ly.fields.size(); ++j) {
                FieldDef &f = ly.fields[j];
                printf("            {\n");
                printf("              \"name\":\"%s\",\n", JsonEscape(f.name).c_str());
                printf("              \"type\":\"%s\",\n", FieldTypeName(f.type).c_str());
                printf("              \"subtype\":\"None\",\n");
