        std::string drv = IdentifyDriver(f, files);
        if (drv == "GeoJSON" || drv == "ESRI Shapefile" || drv == "GeoJSONSeq") {
            CmdDef *vi = SpecFind("vector/info");
            Alg a2;
            a2.cmd = vi;
            ParseArgs(a2, std::vector<std::string>{f, "--output-format", alg.str("output-format")});
