                    }
                }
            }
        }
    }
    /* mutual exclusion */
    {
        std::map<std::string, std::vector<const ArgDef *> > groups;
        for (auto &a : alg.cmd->args) if (!a.excl.empty()) groups[a.excl].push_back(&a);
        for (auto &kv : groups) {
            std::vector<std::string> set;
            for (auto *a : kv.second) {
                AlgValue *v = alg.val(a->name);
                if (v && v->isSet) set.push_back(a->name);
            }
            if (set.size() > 1) {
                errs.push_back("Argument '" + set[0] + "' is mutually exclusive with '" + set[1] + "'.");
            }
        }
    }
    if (!errs.empty()) {
        for (auto &e : errs) CPLLError(5, e);
        fputs(RenderUsageForError(alg.cmd).c_str(), stderr);
        fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
        return -1;
    }
    return 0;
}
