/* ------------------------------------------------------------------ */
/* helper: write an error for a missing input dataset                  */
/* ------------------------------------------------------------------ */
static int NotRecognized(const std::string &name)
{
    CPLLError(4, "`" + name + "' not recognized as being in a supported file format.");
    return 1;
}

static bool OpenAnyRasterOrVector(const std::string &name, GDALDataset *&rds, VectorDataset *&vds,
                                  const std::vector<std::string> &oo)
{
    rds = nullptr;
    vds = nullptr;
    std::vector<std::string> files;
    std::string drv = IdentifyDriver(name, files);
    if (drv.empty()) return false;
    if (drv == "GTiff") {
        rds = new GDALDataset();
        if (!ReadTiff(name, *rds)) { delete rds; rds = nullptr; return false; }
        rds->files = files;
        return true;
    }
    vds = OpenVector(name, false, oo, &files);
    if (!vds) return false;
    vds->files = files;
    return true;
}

/* ------------------------------------------------------------------ */
/* raster create                                                       */
/* ------------------------------------------------------------------ */
static void ApplyGt(GDALDataset *ds, const std::vector<std::string> &oo)
{
    (void)ds;
    (void)oo;
}

static int DoRasterCreate(Alg &alg)
{
    std::string out = alg.str("output");
    std::string fmt = alg.str("output-format");
    int nx = 0, ny = 0, nb = 1;
    if (alg.val("size") && !alg.lst("size").empty()) {
        auto v = alg.lst("size");
        long long a = 0, b = 0;
        if (v.size() >= 1) ParseInt(v[0], a);
        if (v.size() >= 2) ParseInt(v[1], b);
        nx = (int)a; ny = (int)b;
    }
    nb = (int)alg.integer("band-count", 1);
    GDataType dt = GDT_Byte;
    std::string otn = alg.str("output-data-type");
    if (!otn.empty()) {
        GDataType t2 = DataTypeFromName(otn);
        if (t2 != GDT_Unknown) dt = t2;
    }
    if (nx <= 0 || ny <= 0) {
        CPLLError(5, "Invalid value for 'size' argument");
        return 1;
    }
    bool overwrite = alg.flag("overwrite");
    bool append = alg.flag("append");
    if (FileExists(out) && !overwrite && !append) {
        CPLLError(1, "Dataset '" + out + "' already exists. You may specify the --overwrite/--append option.");
        fputs(RenderUsageForError(alg.cmd).c_str(), stderr);
        fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
        return 1;
    }
    GDALDataset *ds = CreateRaster(out, fmt == "GDALG" ? "GTiff" : fmt, nx, ny, nb, dt, alg.lst("creation-option"));
    /* georeferencing */
    std::string crsName = alg.str("crs");
    std::vector<double> bbox;
    for (auto &s : alg.lst("bbox")) {
        double d;
        if (ParseDouble(s, d)) bbox.push_back(d);
    }
    /* --like */
    std::string like = alg.str("like");
    if (!like.empty()) {
        GDALDataset *ld = nullptr;
        VectorDataset *lv = nullptr;
        if (OpenAnyRasterOrVector(like, ld, lv, alg.lst("open-option")) && ld) {
            nx = ld->nx; ny = ld->ny;
            ds->nx = nx; ds->ny = ny;
            if (ld->hasGeoTransform) {
                ds->hasGeoTransform = true;
                memcpy(ds->geoTransform, ld->geoTransform, sizeof(ds->geoTransform));
            }
            if (!ld->srsWkt.empty()) ds->srsWkt = ld->srsWkt;
            ds->metadata[""]["AREA_OR_POINT"] = "Area";
            if (!ld->metadata[""]["AREA_OR_POINT"].empty())
                ds->metadata[""]["AREA_OR_POINT"] = ld->metadata[""]["AREA_OR_POINT"];
            delete ld;
        } else if (lv) {
            delete lv;
        }
    }
    if (!bbox.empty() && bbox.size() >= 4) {
        if (!crsName.empty()) {
            CRS c = CRS::FromUserInput(crsName);
            ds->srsWkt = c.wkt;
        } else if (ds->srsWkt.empty()) {
            CRS c;
            c.SetFromEpsg(4326);
            ds->srsWkt = c.wkt;
        }
        ds->hasGeoTransform = true;
        ds->geoTransform[0] = bbox[0];
        ds->geoTransform[1] = (bbox[2] - bbox[0]) / nx;
        ds->geoTransform[2] = 0;
        ds->geoTransform[3] = bbox[3];
        ds->geoTransform[4] = 0;
        ds->geoTransform[5] = -(bbox[3] - bbox[1]) / ny;
    } else if (!crsName.empty()) {
        CRS c = CRS::FromUserInput(crsName);
        ds->srsWkt = c.wkt;
    }
    /* nodata */
    std::string nd = alg.str("nodata");
    if (!nd.empty() && nd != "none") {
        double d = 0;
        if (ParseDouble(nd, d)) {
            for (auto &b : ds->bands) { b.noDataSet = true; b.nodata = d; }
        } else if (nd == "nan") {
            for (auto &b : ds->bands) { b.noDataSet = true; b.nodata = std::nan(""); }
        }
    }
    /* burn values */
    auto burn = alg.lst("burn");
    if (!burn.empty()) {
        for (size_t b = 0; b < ds->bands.size(); ++b) {
            std::string s = (b < burn.size()) ? burn[b] : burn.back();
            double d = 0;
            if (!ParseDouble(s, d)) continue;
            RasterBand &band = ds->bands[b];
            size_t n = (size_t)ds->nx * ds->ny;
            for (size_t i = 0; i < n; ++i) band.SetValue(i, d);
        }
    }
    for (auto &kv : alg.lst("metadata")) {
        size_t q = kv.find('=');
        if (q == std::string::npos) continue;
        ds->metadata[""][kv.substr(0, q)] = kv.substr(q + 1);
    }
    if (alg.flag("copy-metadata")) { /* copied from input when present */ }
    if (ds->srsWkt.empty() && !alg.str("crs").empty()) {}
    if (!ds->srsWkt.empty()) ds->metadata[""]["AREA_OR_POINT"] = "Area";
    WriteRaster(ds);
    delete ds;
    return 0;
}

/* ------------------------------------------------------------------ */
/* raster/vector convert & create                                      */
/* ------------------------------------------------------------------ */
static int CopyDataset(Alg &alg, const std::string &in, const std::string &out, bool quiet)
{
    (void)quiet;
    GDALDataset *rds = nullptr;
    VectorDataset *vds = nullptr;
    if (!OpenAnyRasterOrVector(in, rds, vds, alg.lst("open-option"))) return NotRecognized(in);
    if (rds) {
        std::string fmt = alg.str("output-format");
        GDALDataset *ods = CreateRaster(out, (fmt == "GDALG" ? "GTiff" : fmt), rds->nx, rds->ny, rds->nbands,
                                        rds->bands.empty() ? GDT_Byte : rds->bands[0].type, alg.lst("creation-option"));
        ods->hasGeoTransform = rds->hasGeoTransform;
        memcpy(ods->geoTransform, rds->geoTransform, sizeof(ods->geoTransform));
        ods->srsWkt = rds->srsWkt;
        ods->metadata = rds->metadata;
        for (size_t b = 0; b < rds->bands.size() && b < ods->bands.size(); ++b) {
            ods->bands[b] = rds->bands[b];
            ods->bands[b].blockX = rds->nx;
            ods->bands[b].blockY = rds->ny;
        }
        WriteRaster(ods);
        delete ods;
        delete rds;
    } else {
        std::string fmt = alg.str("output-format");
        VectorDataset *ods = CreateVector(out, (fmt == "GDALG" ? "GeoJSON" : fmt), alg.lst("creation-option"),
                                          alg.lst("layer-creation-option"));
        ods->layers = vds->layers;
        ods->metadata = vds->metadata;
