    bool append = alg.flag("append");
    if (FileExists(out) && !overwrite && !append) {
        CPLLError(1, "Dataset '" + out + "' already exists. You may specify the --overwrite/--append option.");
        fputs(RenderUsageForError(alg.cmd).c_str(), stderr);
        fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
        return 1;
    }
    GDALDataset *ds = CreateRaster(out, fmt == "GDALG" ? "GTiff" : fmt, nx, ny, nb, dt, alg.lst("creation-option"));
    /* georeferencing */
    std::string crsName = alg.str("crs");
    std::vector<double> bbox;
    for (auto &s : alg.lst("bbox")) {
        double d;
        if (ParseDouble(s, d)) bbox.push_back(d);
    }
