            nx = ld->nx; ny = ld->ny;
            ds->nx = nx; ds->ny = ny;
            if (ld->hasGeoTransform) {
                ds->hasGeoTransform = true;
                memcpy(ds->geoTransform, ld->geoTransform, sizeof(ds->geoTransform));
            }
            if (!ld->srsWkt.empty()) ds->srsWkt = ld->srsWkt;
            ds->metadata[""]["AREA_OR_POINT"] = "Area";
            if (!ld->metadata[""]["AREA_OR_POINT"].empty())
                ds->metadata[""]["AREA_OR_POINT"] = ld->metadata[""]["AREA_OR_POINT"];
            delete ld;
        } else if (lv) {
            delete lv;
        }
    }
    if (!bbox.empty() && bbox.size() >= 4) {
        if (!crsName.empty()) {
            CRS c = CRS::FromUserInput(crsName);
            ds->srsWkt = c.wkt;
        } else if (ds->srsWkt.empty()) {
            CRS c;
            c.SetFromEpsg(4326);
            ds->srsWkt = c.wkt;
        }
        ds->hasGeoTransform = true;
        ds->geoTransform[0] = bbox[0];
        ds->geoTransform[1] = (bbox[2] - bbox[0]) / nx;
        ds->geoTransform[2] = 0;
        ds->geoTransform[3] = bbox[3];
        ds->geoTransform[4] = 0;
        ds->geoTransform[5] = -(bbox[3] - bbox[1]) / ny;
