/* ------------------------------------------------------------------ */
/* vector create                                                       */
/* ------------------------------------------------------------------ */
static int FindOrCreateLayer(VectorDataset *ds, const std::string &layerName)
{
    if (!layerName.empty()) {
        for (auto &ly : ds->layers) if (ly.name == layerName) return (int)(&ly - &ds->layers[0]);
    }
    Layer ly;
    ly.name = layerName.empty() ? BaseName(ds->name) : layerName;
    ds->layers.push_back(ly);
    return (int)ds->layers.size() - 1;
}

int DoVectorCreate(Alg &alg)
{
    std::string out = alg.str("output");
    std::string fmt = alg.str("output-format");
    bool overwrite = alg.flag("overwrite");
    bool update = alg.flag("update");
    if (FileExists(out) && !overwrite && !update) {
        CPLLError(1, "Dataset '" + out + "' already exists. You may specify the --overwrite/--update option.");
        fputs(RenderUsageForError(alg.cmd).c_str(), stderr);
        fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
        return 1;
    }
    VectorDataset *ds;
    if (update && FileExists(out)) {
        std::vector<std::string> files;
        ds = OpenVector(out, true, alg.lst("open-option"), &files);
        if (!ds) return NotRecognized(out);
        ds->files = files;
    } else {
        ds = CreateVector(out, fmt, alg.lst("creation-option"), alg.lst("layer-creation-option"));
    }
    std::string layerName = alg.str("output-layer");
    if (layerName.empty()) layerName = alg.str("input-layer");
    FindOrCreateLayer(ds, layerName);
    /* geometry from --geom or --make-point */
    Layer &ly = ds->layers[ds->layers.size() - 1];
    std::string gt = alg.str("geom");
    if (!gt.empty()) {
        ly.geomType = gt;
        ly.hasGeom = (gt != "none");
    }
    /* fields */
    for (auto &kv : alg.lst("field")) {
        size_t q = kv.find('=');
        std::string nm = (q == std::string::npos) ? kv : kv.substr(0, q);
        std::string def = (q == std::string::npos) ? "" : kv.substr(q + 1);
        FieldDef fd;
        fd.name = nm;
        fd.type = FieldTypeFromName(def.empty() ? "String" : def);
        ly.fields.push_back(fd);
    }
    WriteVector(ds);
    delete ds;
    return 0;
}
