        bool isFloat = (t == GDT_Float32 || t == GDT_Float64 || t == GDT_CFloat32 || t == GDT_CFloat64 || t == GDT_Float16);
        sf.push_back(isFloat ? 3 : 1);
    }
    struct TagInfo { uint16_t tag; uint16_t type; uint32_t count; std::string data; };
    std::vector<TagInfo> tags;
    auto addT = [&](uint16_t tag, uint16_t type, uint32_t count, const std::string &data) {
        tags.push_back({tag, type, count, data});
    };
    uint16_t w16 = (uint16_t)ds.nx, h16v = (uint16_t)ds.ny;
    addT(256, 3, 1, std::string((const char *)&w16, 2));
    addT(257, 3, 1, std::string((const char *)&h16v, 2));
    if (nb > 1) {
        std::string b;
        for (auto v : bits) put16(b, v);
        addT(258, 3, (uint32_t)nb, b);
    }
    uint16_t comp = 1;
    addT(259, 3, 1, std::string((const char *)&comp, 2));
    uint16_t photo = (nb >= 3) ? 2 : 1;
    addT(262, 3, 1, std::string((const char *)&photo, 2));
    addT(273, 4, 1, std::string());                    /* StripOffsets placeholder */
    uint16_t spp = (uint16_t)nb;
    addT(277, 3, 1, std::string((const char *)&spp, 2));
    uint16_t rps = (uint16_t)ds.ny;
    addT(278, 3, 1, std::string((const char *)&rps, 2));
    uint32_t sbc = (uint32_t)pixels.size();
    addT(279, 4, 1, std::string((const char *)&sbc, 4));
    uint16_t pc = 1;
    addT(284, 3, 1, std::string((const char *)&pc, 2));
    if (nb > 1) {
        uint16_t es = 0;
        addT(338, 3, 1, std::string((const char *)&es, 2));
        std::string f;
        for (auto v : sf) put16(f, v);
        addT(339, 3, (uint32_t)nb, f);
    } else {
        uint16_t f = sf.empty() ? 1 : sf[0];
        addT(339, 3, 1, std::string((const char *)&f, 2));
    }
    if (crs.valid) {
        std::string sc;
        putd(sc, ds.hasGeoTransform ? std::fabs(ds.geoTransform[1]) : 1.0);
        putd(sc, ds.hasGeoTransform ? std::fabs(ds.geoTransform[5]) : 1.0);
        putd(sc, 0.0);
        addT(33550, 12, 3, sc);
        std::string tp;
        putd(tp, 0.0); putd(tp, 0.0); putd(tp, 0.0);
        putd(tp, ds.hasGeoTransform ? ds.geoTransform[0] : 0.0);
        putd(tp, ds.hasGeoTransform ? ds.geoTransform[3] : 0.0);
        putd(tp, 0.0);
        addT(33922, 12, 6, tp);
    }
    if (!metaXml.empty()) {
        std::string m = metaXml + std::string("\\0");
        addT(42112, 2, (uint32_t)m.size(), m);
    }
    if (!gk.keys.empty()) {
        std::string kd;
        for (auto v : gk.keys) put16(kd, v);
        addT(34735, 3, (uint32_t)gk.keys.size(), kd);
        if (!gk.doubles.empty()) {
            std::string dd;
            for (auto v : gk.doubles) putd(dd, v);
            addT(34736, 12, (uint32_t)gk.doubles.size(), dd);
        }
        if (!gk.ascii.empty()) addT(34737, 2, (uint32_t)gk.ascii.size(), gk.ascii);
    }
    /* TIFF requires tags in ascending order */
    std::sort(tags.begin(), tags.end(), [](const TagInfo &a, const TagInfo &b2) { return a.tag < b2.tag; });
    size_t ntags = tags.size();
    size_t ifdSize = 2 + 12 * ntags + 4;
    size_t cursor = 8 + ifdSize;
    std::vector<uint32_t> offsets(ntags, 0);
    for (size_t i = 0; i < ntags; ++i) {
        size_t sz = (size_t)kTypeSize[tags[i].type] * tags[i].count;
        if (sz > 4) { offsets[i] = (uint32_t)cursor; cursor += sz + (sz & 1); }
    }
    size_t dataOff = cursor;
    std::string out = "II";
    out += (char)42;
    out += (char)0;
    put32(out, 8);
    put16(out, (uint16_t)ntags);
    for (size_t i = 0; i < ntags; ++i) {
        put16(out, tags[i].tag);
        put16(out, tags[i].type);
        put32(out, tags[i].count);
        if (tags[i].tag == 273) put32(out, (uint32_t)dataOff);
        else if (offsets[i]) put32(out, offsets[i]);
        else {
            std::string v = tags[i].data;
            while (v.size() < 4) v += '\\0';
            out += v.substr(0, 4);
        }
    }
    put32(out, 0);
    for (size_t i = 0; i < ntags; ++i) {
        size_t sz = (size_t)kTypeSize[tags[i].type] * tags[i].count;
        if (sz > 4) {
            out += tags[i].data;
            if (sz & 1) out += '\\0';
        }
    }
    out += pixels;
    return out;
}

