        fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
        return 1;
    }
    GDALDataset *ods = CreateRaster(alg.str("output"), alg.str("output-format") == "GDALG" ? "GTiff" : alg.str("output-format"),
                                    ds->nx, ds->ny, ds->nbands, ds->bands.empty() ? GDT_Byte : ds->bands[0].type,
                                    alg.lst("creation-option"));
    CopyRasterAll(ds, ods);
    ods->srsWkt = dst.wkt;
    /* if the source is geographic and the destination is geographic with the
     * same datum, the geotransform is preserved */
    WriteRaster(ods);
    delete ods;
    delete ds;
    return 0;
}

