static void CopyRasterAll(GDALDataset *src, GDALDataset *dst)
{
    dst->nx = src->nx; dst->ny = src->ny; dst->nbands = src->nbands;
    dst->hasGeoTransform = src->hasGeoTransform;
    memcpy(dst->geoTransform, src->geoTransform, sizeof(dst->geoTransform));
    dst->srsWkt = src->srsWkt;
    dst->metadata = src->metadata;
}

static int DoRasterResize(Alg &alg)
{
    std::string in = alg.str("input");
    GDALDataset *ds = nullptr;
    VectorDataset *v = nullptr;
    if (!OpenAnyRasterOrVector(in, ds, v, alg.lst("open-option"))) return NotRecognized(in);
    if (v) { delete v; return NotRecognized(in); }
    auto sz = alg.lst("size");
    auto res = alg.lst("resolution");
    int nx = ds->nx, ny = ds->ny;
    if (!sz.empty()) {
        long long a = 0, b = 0;
        if (sz.size() >= 1) ParseInt(sz[0], a);
        if (sz.size() >= 2) ParseInt(sz[1], b);
        nx = (int)a; ny = (int)b;
        if (sz.size() == 1) ny = ds->ny;
    } else if (!res.empty()) {
        double rx = 0, ry = 0;
        if (res.size() >= 1) ParseDouble(res[0], rx);
        if (res.size() >= 2) ParseDouble(res[1], ry);
        if (rx > 0 && ds->hasGeoTransform) nx = (int)(std::fabs((ds->geoTransform[1] * ds->nx) / rx) + 0.5);
        if (ry > 0 && ds->hasGeoTransform) ny = (int)(std::fabs((ds->geoTransform[5] * ds->ny) / ry) + 0.5);
    } else {
        CPLLError(1, "Neither size nor resolution was specified.");
        fputs(RenderUsageForError(alg.cmd).c_str(), stderr);
        fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
        return 1;
    }
    GDALDataset *ods = CreateRaster(alg.str("output"), alg.str("output-format") == "GDALG" ? "GTiff" : alg.str("output-format"),
                                    nx, ny, ds->nbands, ds->bands.empty() ? GDT_Byte : ds->bands[0].type,
                                    alg.lst("creation-option"));
    CopyRasterAll(ds, ods);
    if (ods->hasGeoTransform) {
        ods->geoTransform[1] = (ds->geoTransform[1] * ds->nx) / nx;
        ods->geoTransform[5] = (ds->geoTransform[5] * ds->ny) / ny;
    }
    for (size_t b = 0; b < ods->bands.size(); ++b) {
        ods->bands[b].noDataSet = ds->bands[b].noDataSet;
        ods->bands[b].nodata = ds->bands[b].nodata;
        ods->bands[b].interp = ds->bands[b].interp;
        for (int y = 0; y < ny; ++y) {
            for (int x = 0; x < nx; ++x) {
                int sx = (int)((double)x * ds->nx / nx);
                int sy = (int)((double)y * ds->ny / ny);
                if (sx >= ds->nx) sx = ds->nx - 1;
                if (sy >= ds->ny) sy = ds->ny - 1;
                ods->bands[b].SetValue((size_t)y * nx + x, ds->bands[b].GetValue((size_t)sy * ds->nx + sx));
            }
        }
    }
    WriteRaster(ods);
    delete ods;
    delete ds;
    return 0;
}

static int DoRasterSelect(Alg &alg)
{
