    VectorDataset *v = nullptr;
    if (!OpenAnyRasterOrVector(in, ds, v, alg.lst("open-option"))) return NotRecognized(in);
    if (v) { delete v; return NotRecognized(in); }
    std::vector<int> bands;
    for (auto &s : alg.lst("band")) {
        long long b = 0;
        if (ParseInt(s, b)) bands.push_back((int)b);
    }
    if (bands.empty()) {
        for (size_t i = 0; i < ds->bands.size(); ++i) bands.push_back((int)i + 1);
    }
    GDALDataset *ods = CreateRaster(alg.str("output"), alg.str("output-format") == "GDALG" ? "GTiff" : alg.str("output-format"),
                                    ds->nx, ds->ny, (int)bands.size(), GDT_Byte, alg.lst("creation-option"));
    CopyRasterAll(ds, ods);
    for (size_t i = 0; i < bands.size(); ++i) {
        int b = bands[i];
        if (b < 1 || b > (int)ds->bands.size()) continue;
        RasterBand &src = ds->bands[b - 1];
        RasterBand &dst = ods->bands[i];
        dst = src;
        dst.blockX = ds->nx;
        dst.blockY = ds->ny;
    }
    WriteRaster(ods);
    delete ods;
    delete ds;
    return 0;
}

/* generic "compute per-pixel function" helper */
static int RasterUnaryOp(Alg &alg, double (*f)(double, double, double, double, double, double),
                         GDataType outType)
{
    std::string in = alg.str("input");
    GDALDataset *ds = nullptr;
    VectorDataset *v = nullptr;
    if (!OpenAnyRasterOrVector(in, ds, v, alg.lst("open-option"))) return NotRecognized(in);
    if (v) { delete v; return NotRecognized(in); }
    int band = (int)alg.integer("band", 1);
    if (band < 1 || band > (int)ds->bands.size()) band = 1;
    GDALDataset *ods = CreateRaster(alg.str("output"), alg.str("output-format") == "GDALG" ? "GTiff" : alg.str("output-format"),
                                    ds->nx, ds->ny, 1, outType, alg.lst("creation-option"));
    CopyRasterAll(ds, ods);
    RasterBand &src = ds->bands[band - 1];
    RasterBand &dst = ods->bands[0];
    dst.noDataSet = src.noDataSet;
    dst.nodata = src.nodata;
    size_t n = (size_t)ds->nx * ds->ny;
    for (size_t i = 0; i < n; ++i) {
        double v0 = src.GetValue(i);
        double left = (i % ds->nx) ? src.GetValue(i - 1) : v0;
        double right = ((i % ds->nx) < (size_t)ds->nx - 1) ? src.GetValue(i + 1) : v0;
        double up = (i >= (size_t)ds->nx) ? src.GetValue(i - ds->nx) : v0;
        double down = (i + ds->nx < n) ? src.GetValue(i + ds->nx) : v0;
        double res = f(v0, left, right, up, down, 0);
        dst.SetValue(i, res);
    }
    WriteRaster(ods);
    delete ods;
    delete ds;
    return 0;
}

static double OpSlope(double c, double l, double r, double u, double d, double /*cell*/)
{
    double dzdx = ((r - l) / 2.0);
    double dzdy = ((u - d) / 2.0);
    double slope = sqrt(dzdx * dzdx + dzdy * dzdy);
    double deg = atan(slope) * 180.0 / M_PI;
    return deg;
}

static double OpAspect(double c, double l, double r, double u, double d, double /*cell*/)
{
    (void)c;
    double dzdx = (r - l) / 2.0;
    double dzdy = (u - d) / 2.0;
    if (dzdx == 0 && dzdy == 0) return -1;
    double az = atan2(dzdy, -dzdx) * 180.0 / M_PI;
    if (az < 0) az += 360;
    return az;
}

static double OpTpi(double c, double l, double r, double u, double d, double /*cell*/)
{
    return ((l + r + u + d) / 4.0) - c;
}

static double OpTri(double c, double l, double r, double u, double d, double /*cell*/)
{
    double s = 0;
    s += std::fabs(l - c); s += std::fabs(r - c);
    s += std::fabs(u - c); s += std::fabs(d - c);
    return s / 4.0;
}

static double OpRoughness(double c, double l, double r, double u, double d, double /*cell*/)
{
    double mx = c, mn = c;
    double vals[5] = {c, l, r, u, d};
    for (int i = 0; i < 5; ++i) { if (vals[i] > mx) mx = vals[i]; if (vals[i] < mn) mn = vals[i]; }
    return mx - mn;
}

