static int DoRasterScale(Alg &alg)
{
    std::string in = alg.str("input");
    GDALDataset *ds = nullptr;
    VectorDataset *v = nullptr;
    if (!OpenAnyRasterOrVector(in, ds, v, alg.lst("open-option"))) return NotRecognized(in);
    if (v) { delete v; return NotRecognized(in); }
    GDALDataset *ods = CreateRaster(alg.str("output"), alg.str("output-format") == "GDALG" ? "GTiff" : alg.str("output-format"),
                                    ds->nx, ds->ny, ds->nbands, GDT_Byte, alg.lst("creation-option"));
    CopyRasterAll(ds, ods);
    auto src = alg.lst("src-min");
    auto dstv = alg.lst("dst-min");
    for (size_t b = 0; b < ods->bands.size(); ++b) {
        RasterBand &sb = ds->bands[b];
        RasterBand &db = ods->bands[b];
        db.type = GDT_Byte;
        db.data.assign((size_t)ds->nx * ds->ny, 0);
        double smin = (b < src.size()) ? StrDbl(src[b], 0) : 0;
        double smax = (b < alg.lst("src-max").size()) ? StrDbl(alg.lst("src-max")[b], 255) : 255;
        double dmin = (b < dstv.size()) ? StrDbl(dstv[b], 0) : 0;
        double dmax = (b < alg.lst("dst-max").size()) ? StrDbl(alg.lst("dst-max")[b], 255) : 255;
        size_t n = (size_t)ds->nx * ds->ny;
        double mn = 1e300, mx = -1e300;
        for (size_t i = 0; i < n; ++i) {
            double v = sb.GetValue(i);
            if (sb.noDataSet && v == sb.nodata) continue;
            if (v < mn) mn = v;
            if (v > mx) mx = v;
        }
        if (mn > mx) { mn = 0; mx = 1; }
        double s0 = src.empty() ? mn : smin;
        double s1 = alg.lst("src-max").empty() ? mx : smax;
        if (s1 == s0) s1 = s0 + 1;
        for (size_t i = 0; i < n; ++i) {
            double v = sb.GetValue(i);
            double o = dmin + (v - s0) * (dmax - dmin) / (s1 - s0);
            db.SetValue(i, o);
        }
        db.hasScale = true;
        db.scale = (s1 - s0) / (dmax - dmin);
        db.offset = s0 - dmin * db.scale;
    }
    WriteRaster(ods);
    delete ods;
    delete ds;
    return 0;
}

