static int DoRasterMosaicOrStack(Alg &alg, bool stack)
{
    auto inputs = alg.lst("input");
    GDALDataset *first = nullptr;
    VectorDataset *v = nullptr;
    if (inputs.empty()) return NotRecognized("");
    if (!OpenAnyRasterOrVector(inputs[0], first, v, alg.lst("open-option"))) return NotRecognized(inputs[0]);
    if (v) { delete v; return NotRecognized(inputs[0]); }
    int nb = stack ? (int)inputs.size() : first->nbands;
    /* compute the union extent */
    double minX = 1e300, minY = 1e300, maxX = -1e300, maxY = -1e300;
    double resx = first->hasGeoTransform ? std::fabs(first->geoTransform[1]) : 1.0;
    double resy = first->hasGeoTransform ? std::fabs(first->geoTransform[5]) : 1.0;
    for (auto &nm : inputs) {
        GDALDataset *d = nullptr;
        VectorDataset *vv = nullptr;
        if (!OpenAnyRasterOrVector(nm, d, vv, alg.lst("open-option"))) { delete first; return NotRecognized(nm); }
        if (vv) { delete vv; continue; }
        if (!d->hasGeoTransform) { minX = 0; minY = 0; maxX = d->nx; maxY = d->ny; resx = 1; resy = 1; }
        else {
            double x0 = d->geoTransform[0];
            double y0 = d->geoTransform[3];
            double x1 = x0 + d->nx * d->geoTransform[1];
            double y1 = y0 + d->ny * d->geoTransform[5];
            if (x0 < minX) minX = x0;
            if (y1 < minY) minY = y1;
            if (x1 > maxX) maxX = x1;
            if (y0 > maxY) maxY = y0;
            if (std::fabs(d->geoTransform[1]) < resx) resx = std::fabs(d->geoTransform[1]);
            if (std::fabs(d->geoTransform[5]) < resy) resy = std::fabs(d->geoTransform[5]);
        }
        if (d != first) delete d;
    }
    if (minX > maxX) { minX = 0; minY = 0; maxX = first->nx; maxY = first->ny; }
    int nx = (int)std::ceil((maxX - minX) / resx);
    int ny = (int)std::ceil((maxY - minY) / resy);
    GDALDataset *ods = CreateRaster(alg.str("output"), alg.str("output-format") == "GDALG" ? "GTiff" : alg.str("output-format"),
                                    nx, ny, nb, GDT_Byte, alg.lst("creation-option"));
    ods->hasGeoTransform = true;
    ods->geoTransform[0] = minX;
    ods->geoTransform[1] = resx;
    ods->geoTransform[2] = 0;
    ods->geoTransform[3] = maxY;
    ods->geoTransform[4] = 0;
    ods->geoTransform[5] = -resy;
    ods->srsWkt = first->srsWkt;
    int outBand = 0;
    for (auto &nm : inputs) {
        GDALDataset *d = nullptr;
        VectorDataset *vv = nullptr;
        if (!OpenAnyRasterOrVector(nm, d, vv, alg.lst("open-option"))) continue;
        if (vv) { delete vv; continue; }
        int nbIn = d->nbands;
        for (int b = 0; b < nbIn; ++b) {
            if (outBand >= nb) break;
            RasterBand &db = ods->bands[outBand];
            db.interp = d->bands[b].interp;
            db.noDataSet = d->bands[b].noDataSet;
            db.nodata = d->bands[b].nodata;
            for (int y = 0; y < d->ny; ++y) {
                for (int x = 0; x < d->nx; ++x) {
                    double wx, wy;
                    if (d->hasGeoTransform) {
                        wx = d->geoTransform[0] + (x + 0.5) * d->geoTransform[1];
                        wy = d->geoTransform[3] + (y + 0.5) * d->geoTransform[5];
                    } else { wx = x + 0.5; wy = y + 0.5; }
                    int ox, oy;
                    if (ods->hasGeoTransform) {
                        ox = (int)((wx - ods->geoTransform[0]) / ods->geoTransform[1]);
                        oy = (int)((wy - ods->geoTransform[3]) / ods->geoTransform[5]);
                    } else { ox = x; oy = y; }
                    if (ox < 0 || oy < 0 || ox >= nx || oy >= ny) continue;
                    db.SetValue((size_t)oy * nx + ox, d->bands[b].GetValue((size_t)y * d->nx + x));
                }
            }
            outBand++;
            if (!stack) break;
        }
        delete d;
    }
    WriteRaster(ods);
    delete ods;
    delete first;
    return 0;
}

static int DoRasterEdit(Alg &alg)
{
    std::string in = alg.str("input");
    bool update = alg.flag("update");
    GDALDataset *ds = nullptr;
    VectorDataset *v = nullptr;
    if (!OpenAnyRasterOrVector(in, ds, v, alg.lst("open-option"))) return NotRecognized(in);
    if (v) { delete v; return NotRecognized(in); }
    if (!update && !FileExists(in)) return NotRecognized(in);
    if (!alg.str("crs").empty()) {
        CRS c = CRS::FromUserInput(alg.str("crs"));
        ds->srsWkt = c.wkt;
        ds->metadata[""]["AREA_OR_POINT"] = "Area";
    }
    auto bb = alg.lst("bbox");
    if (bb.size() >= 4) {
        ds->hasGeoTransform = true;
        ds->geoTransform[0] = StrDbl(bb[0], 0);
        ds->geoTransform[1] = (StrDbl(bb[2], 0) - StrDbl(bb[0], 0)) / ds->nx;
        ds->geoTransform[2] = 0;
        ds->geoTransform[3] = StrDbl(bb[3], 0);
        ds->geoTransform[4] = 0;
        ds->geoTransform[5] = -(StrDbl(bb[3], 0) - StrDbl(bb[1], 0)) / ds->ny;
    }
    if (!alg.str("units").empty()) {}
    for (auto &kv : alg.lst("metadata")) {
        size_t q = kv.find('=');
        if (q == std::string::npos) continue;
        ds->metadata[""][kv.substr(0, q)] = kv.substr(q + 1);
    }
    for (auto &s : alg.lst("unset-metadata")) ds->metadata[""].erase(s);
    for (auto &s : alg.lst("unset-metadata-domain")) ds->metadata.erase(s);
    WriteRaster(ds);
    delete ds;
    return 0;
}

static int DoRasterNodataToAlpha(Alg &alg)
{
    std::string in = alg.str("input");
    GDALDataset *ds = nullptr;
    VectorDataset *v = nullptr;
    if (!OpenAnyRasterOrVector(in, ds, v, alg.lst("open-option"))) return NotRecognized(in);
    if (v) { delete v; return NotRecognized(in); }
    int nb = ds->nbands + 1;
    GDALDataset *ods = CreateRaster(alg.str("output"), alg.str("output-format") == "GDALG" ? "GTiff" : alg.str("output-format"),
                                    ds->nx, ds->ny, nb, GDT_Byte, alg.lst("creation-option"));
    CopyRasterAll(ds, ods);
    for (size_t b = 0; b < ds->bands.size(); ++b) ods->bands[b] = ds->bands[b];
    RasterBand &alpha = ods->bands[ds->bands.size()];
    alpha.interp = GCI_Alpha;
    alpha.data.assign((size_t)ds->nx * ds->ny, 255);
    size_t n = (size_t)ds->nx * ds->ny;
    for (size_t i = 0; i < n; ++i) {
        bool nodata = false;
        for (auto &sb : ds->bands) {
            if (sb.noDataSet && sb.GetValue(i) == sb.nodata) nodata = true;
        }
        if (nodata) alpha.SetValue(i, 0);
    }
    WriteRaster(ods);
    delete ods;
    delete ds;
    return 0;
}

