        std::string drv = IdentifyDriver(nm, files);
        if (drv.empty()) {
            CPLLError(4, "`" + nm + "' not recognized as being in a supported file format.");
            continue;
        }
        printf("%s: %s\n", nm.c_str(), drv.c_str());
    }
    return 0;
}

static int DoDatasetDelete(Alg &alg)
{
    for (auto &nm : alg.lst("filename")) {
        std::vector<std::string> files;
        std::string drv = IdentifyDriver(nm, files);
        if (IsDirectory(nm) && !drv.empty()) {
            for (auto &f : ListDir(nm)) RemoveFile(nm + "/" + f);
            if (::rmdir(nm.c_str()) != 0) CPLLError(3, "Cannot delete directory '" + nm + "'");
            continue;
        }
        for (auto &f : files) {
            if (::remove(f.c_str()) != 0) CPLLError(3, "Cannot delete file '" + f + "'");
        }
        if (files.empty() && FileExists(nm)) {
            if (::remove(nm.c_str()) != 0) CPLLError(3, "Cannot delete file '" + nm + "'");
        }
    }
    return 0;
}

static int DoDatasetCopyOrRename(Alg &alg, bool rename)
{
    std::string src = alg.str("source");
    std::string dst = alg.str("destination");
    std::vector<std::string> files;
    std::string drv = IdentifyDriver(src, files);
    if (drv.empty()) return NotRecognized(src);
    if (FileExists(dst) && !alg.flag("overwrite")) {
        CPLLError(1, "Dataset '" + dst + "' already exists. You may specify the --overwrite option.");
        fputs(RenderUsageForError(alg.cmd).c_str(), stderr);
        fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
        return 1;
    }
    std::string dstBase = dst;
    size_t q = dstBase.rfind('.');
    std::string ext = (q == std::string::npos) ? "" : ToLower(dstBase.substr(q + 1));
    if (ext == "shp" || ext == "dbf" || ext == "shx" || ext == "prj") dstBase = dstBase.substr(0, q);
    std::string srcBase = src;
    q = srcBase.rfind('.');
    std::string sext = (q == std::string::npos) ? "" : ToLower(srcBase.substr(q + 1));
    if (sext == "shp" || sext == "dbf" || sext == "shx" || sext == "prj") srcBase = srcBase.substr(0, q);
    bool isShp = (drv == "ESRI Shapefile");
    for (auto &f : files) {
        std::string target;
        if (isShp) {
            std::string fe = f.substr(srcBase.size());
            target = dstBase + fe;
        } else target = dst;
        if (rename) {
            if (::rename(f.c_str(), target.c_str()) != 0)
                CPLLError(3, "Cannot rename '" + f + "' to '" + target + "'");
        } else {
            bool ok = false;
            std::string data = ReadWholeFile(f, ok);
            if (!ok || !WriteWholeFile(target, data))
                CPLLError(3, "Cannot copy '" + f + "' to '" + target + "'");
        }
    }
    return 0;
}

static int DoDatasetCheck(Alg &alg)
{
    std::string in = alg.str("input");
    GDALDataset *ds = nullptr;
    VectorDataset *vds = nullptr;
    if (!OpenAnyRasterOrVector(in, ds, vds, alg.lst("open-option"))) return NotRecognized(in);
    int errors = 0;
    if (ds) {
        size_t n = (size_t)ds->nx * ds->ny;
        for (auto &b : ds->bands) {
            for (size_t i = 0; i < n; ++i) {
                double v = b.GetValue(i);
                if (std::isnan(v) && !b.noDataSet) { errors++; CPLLError(1, "NaN value in band"); break; }
            }
        }
        delete ds;
    } else {
        for (auto &ly : vds->layers) {
            for (auto &f : ly.features) {
                if (f.geom.IsEmpty() && f.geom.type != "UNKNOWN") {
                    CPLLError(1, "Empty geometry in feature " + std::to_string(f.fid));
                    errors++;
                }
            }
        }
        delete vds;
    }
    return 0;
}

