static int DoVsiList(Alg &alg)
{
    std::string nm = alg.str("filename");
    if (!FileExists(nm)) {
        CPLLError(4, "'" + nm + "' does not exist in the file system");
        return 1;
    }
    if (IsDirectory(nm)) {
        for (auto &f : ListDir(nm)) printf("%s\n", (nm + "/" + f).c_str());
        return 0;
    }
    printf("%s\n", nm.c_str());
    return 0;
}

static int DoVsiCopyOrMove(Alg &alg, bool move)
{
    std::string src = alg.str("source");
    std::string dst = alg.str("destination");
    if (IsDirectory(src)) {
        /* copy a directory tree */
        if (!FileExists(dst)) {
#ifdef __linux__
            mkdir(dst.c_str(), 0755);
#endif
        }
        for (auto &f : ListDir(src)) {
            std::string s2 = src + "/" + f, d2 = dst + "/" + f;
            if (IsDirectory(s2)) continue;
            bool ok = false;
            std::string data = ReadWholeFile(s2, ok);
            if (!ok || !WriteWholeFile(d2, data)) CPLLError(3, "Cannot copy '" + s2 + "'");
        }
        return 0;
    }
    if (!FileExists(src)) {
        CPLLError(4, "'" + src + "' does not exist in the file system");
        return 1;
    }
    if (FileExists(dst) && !alg.flag("overwrite")) {
        CPLLError(1, "File '" + dst + "' already exists. You may specify the --overwrite option.");
        return 1;
    }
    bool ok = false;
    std::string data = ReadWholeFile(src, ok);
    if (!ok || !WriteWholeFile(dst, data)) {
        CPLLError(3, "Cannot copy '" + src + "' to '" + dst + "'");
        return 1;
    }
    if (move && ::remove(src.c_str()) != 0) CPLLError(3, "Cannot delete '" + src + "'");
    return 0;
}

static int DoVsiDelete(Alg &alg)
{
    for (auto &nm : alg.lst("filename")) {
        if (IsDirectory(nm)) {
            if (::rmdir(nm.c_str()) != 0) CPLLError(3, "Cannot delete directory '" + nm + "'");
            continue;
        }
        if (::remove(nm.c_str()) != 0) CPLLError(3, "Cannot delete file '" + nm + "'");
    }
    return 0;
}

static int DoVsiSozip(Alg &alg)
{
    std::string p = alg.cmd->path;
    if (p == "vsi/sozip/list") {
        std::string nm = alg.str("input");
        if (!FileExists(nm)) {
            CPLLError(4, "`" + nm + "' not recognized as being in a supported file format.");
            return 1;
        }
        bool ok = false;
        std::string d = ReadWholeFile(nm, ok);
        if (!ok || d.size() < 4 || d.substr(0, 2) != "PK") {
            CPLLError(1, "Not a ZIP file");
            return 1;
        }
        printf("%s\n", nm.c_str());
        return 0;
    }
    if (p == "vsi/sozip/validate") {
        std::string nm = alg.str("input");
        if (!FileExists(nm)) {
            CPLLError(4, "`" + nm + "' not recognized as being in a supported file format.");
            return 1;
        }
        bool ok = false;
        std::string d = ReadWholeFile(nm, ok);
        if (!ok || d.size() < 4 || d.substr(0, 2) != "PK") {
            CPLLError(1, "Not a ZIP file");
            return 1;
        }
        printf("%s is a valid ZIP file\n", nm.c_str());
        return 0;
    }
    return 0;
}

