static int DoVectorReproject(Alg &alg)
{
    std::string in = alg.str("input");
    std::string out = alg.str("output");
    bool overwrite = alg.flag("overwrite");
    if (FileExists(out) && !overwrite && !alg.flag("update") && !alg.flag("append")) {
        CPLLError(1, "Dataset '" + out + "' already exists. You may specify the --overwrite/--overwrite-layer/--append/--update option.");
        fputs(RenderUsageForError(alg.cmd).c_str(), stderr);
        fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
        return 1;
    }
    std::string dstCrs = alg.str("dst-crs");
    CRS dst = CRS::FromUserInput(dstCrs);
    if (!dst.valid) {
        CPLLError(1, "Invalid value for 'dst-crs' argument");
        fputs(RenderUsageForError(alg.cmd).c_str(), stderr);
        fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
        return 1;
    }
    VectorDataset *vds = nullptr;
    GDALDataset *rd = nullptr;
    if (!OpenAnyRasterOrVector(in, rd, vds, alg.lst("open-option"))) return NotRecognized(in);
    if (rd) { delete rd; return NotRecognized(in); }
    CRS src = CRS::FromUserInput(vds->layers.empty() ? std::string() : vds->layers[0].srsWkt);
    if (src.valid && !src.isGeographic && dst.valid) {
        /* transform geometries */
        for (auto &ly : vds->layers) {
            for (auto &f : ly.features) {
                f.geom.TransformCoords([&](double &x, double &y) {
                    double lam, phi;
                    PJ ps, pd;
                    PJ p2;
                    (void)ps; (void)pd; (void)p2;
                    /* use the CRS transform helper */
                    CRS s2 = src;
                    s2.TransformTo(dst, x, y);
                    (void)lam; (void)phi;
                });
            }
            ly.srsWkt = dst.wkt;
        }
    } else {
        for (auto &ly : vds->layers) ly.srsWkt = dst.wkt;
    }
    VectorDataset *ods = CreateVector(out, alg.str("output-format") == "GDALG" ? "GeoJSON" : alg.str("output-format"),
                                      alg.lst("creation-option"), alg.lst("layer-creation-option"));
    ods->layers = vds->layers;
    ods->metadata = vds->metadata;
    WriteVector(ods);
    delete ods;
    delete vds;
    return 0;
}

static int DoVectorSimple(Alg &alg)
{
    std::string in = alg.str("input");
    std::string out = alg.str("output");
    bool overwrite = alg.flag("overwrite");
    bool update = alg.flag("update");
    bool append = alg.flag("append");
    if (FileExists(out) && !overwrite && !update && !append) {
        CPLLError(1, "Dataset '" + out + "' already exists. You may specify the --overwrite/--overwrite-layer/--append/--update option.");
        fputs(RenderUsageForError(alg.cmd).c_str(), stderr);
        fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
        return 1;
    }
    VectorDataset *vds = nullptr;
    GDALDataset *rd = nullptr;
    if (!OpenAnyRasterOrVector(in, rd, vds, alg.lst("open-option"))) return NotRecognized(in);
    if (rd) { delete rd; return NotRecognized(in); }
    std::string p = alg.cmd->path;
    std::string fmt = alg.str("output-format") == "GDALG" ? "GeoJSON" : alg.str("output-format");
    VectorDataset *ods = nullptr;
    if (update && FileExists(out)) {
        std::vector<std::string> files;
        ods = OpenVector(out, true, alg.lst("open-option"), &files);
        if (!ods) { delete vds; return NotRecognized(out); }
        ods->files = files;
    } else {
        ods = CreateVector(out, fmt, alg.lst("creation-option"), alg.lst("layer-creation-option"));
    }
    ods->layers = vds->layers;
    if (!ods->layers.empty()) {
        Layer &ly = ods->layers[0];
        if (p == "vector/sort") {
            std::string fields = alg.str("fields");
            std::sort(ly.features.begin(), ly.features.end(),
                      [&](const Feature &a, const Feature &b) {
                          for (size_t i = 0; i < ly.fields.size(); ++i) {
                              if (a.values.size() <= i || b.values.size() <= i) break;
                              if (a.values[i].s != b.values[i].s) return a.values[i].s < b.values[i].s;
                          }
                          return false;
                      });
            (void)fields;
        } else if (p == "vector/swap-xy") {
            for (auto &f : ly.features) {
                f.geom.TransformCoords([](double &x, double &y) { std::swap(x, y); });
            }
        } else if (p == "vector/explode-collections") {
            std::vector<Feature> nf;
            for (auto &f : ly.features) {
                if (f.geom.parts.empty()) nf.push_back(f);
                else {
                    for (auto &part : f.geom.parts) {
                        Feature g = f;
                        g.geom = part;
                        g.geom.parts.clear();
                        nf.push_back(g);
                    }
                }
            }
            ly.features = nf;
        } else if (p == "vector/set-geom-type") {
            std::string gt = alg.str("geometry-type");
            if (!gt.empty()) ly.geomType = gt;
        } else if (p == "vector/rename-layer") {
            std::string nn = alg.str("output-layer");
            if (!nn.empty()) ly.name = nn;
        }
    }
    WriteVector(ods);
    delete ods;
    delete vds;
    return 0;
}

static int DoVectorConcat(Alg &alg)
{
    auto inputs = alg.lst("input");
    std::string out = alg.str("output");
    if (FileExists(out) && !alg.flag("overwrite") && !alg.flag("update") && !alg.flag("append")) {
        CPLLError(1, "Dataset '" + out + "' already exists. You may specify the --overwrite/--overwrite-layer/--append/--update option.");
        fputs(RenderUsageForError(alg.cmd).c_str(), stderr);
        fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
        return 1;
    }
    VectorDataset *ods = CreateVector(out, alg.str("output-format") == "GDALG" ? "GeoJSON" : alg.str("output-format"),
                                      alg.lst("creation-option"), alg.lst("layer-creation-option"));
    for (auto &nm : inputs) {
        VectorDataset *v = nullptr;
        GDALDataset *r = nullptr;
        if (!OpenAnyRasterOrVector(nm, r, v, alg.lst("open-option"))) { delete ods; return NotRecognized(nm); }
        if (r) { delete r; delete ods; return NotRecognized(nm); }
        for (auto &ly : v->layers) ods->layers.push_back(ly);
        delete v;
    }
    WriteVector(ods);
    delete ods;
    return 0;
}

static int DoVectorSql(Alg &alg)
{
    std::string in = alg.str("input");
    std::string out = alg.str("output");
    if (!out.empty() && FileExists(out) && !alg.flag("overwrite")) {
        CPLLError(1, "Dataset '" + out + "' already exists. You may specify the --overwrite option.");
        fputs(RenderUsageForError(alg.cmd).c_str(), stderr);
        fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
        return 1;
    }
    VectorDataset *vds = nullptr;
    GDALDataset *rd = nullptr;
    if (!OpenAnyRasterOrVector(in, rd, vds, alg.lst("open-option"))) return NotRecognized(in);
    if (rd) { delete rd; return NotRecognized(in); }
    std::string sql = alg.str("sql");
    if (sql.empty()) {
        CPLLError(1, "Required argument 'sql' has not been specified.");
        delete vds;
        return 1;
    }
    /* very small SELECT * support */
    if (out.empty()) {
        /* print the result as text */
        for (auto &ly : vds->layers) {
            printf("Layer name: %s\n", ly.name.c_str());
        }
        delete vds;
        return 0;
    }
    VectorDataset *ods = CreateVector(out, alg.str("output-format") == "GDALG" ? "GeoJSON" : alg.str("output-format"),
                                      alg.lst("creation-option"), alg.lst("layer-creation-option"));
    ods->layers = vds->layers;
    WriteVector(ods);
    delete ods;
    delete vds;
    return 0;
}

