            return 1;
        }
        bool ok = false;
        std::string d = ReadWholeFile(nm, ok);
        if (!ok || d.size() < 4 || d.substr(0, 2) != "PK") {
            CPLLError(1, "Not a ZIP file");
            return 1;
        }
        printf("%s is a valid ZIP file\n", nm.c_str());
        return 0;
    }
    return 0;
}

