static int DoVectorExportSchema(Alg &alg)
{
    std::string in = alg.str("input");
    VectorDataset *vds = nullptr;
    GDALDataset *rd = nullptr;
    if (!OpenAnyRasterOrVector(in, rd, vds, alg.lst("open-option"))) return NotRecognized(in);
    if (rd) { delete rd; return NotRecognized(in); }
    std::string out = "{\n";
    out += "  \"layers\":[\n";
    for (size_t i = 0; i < vds->layers.size(); ++i) {
        Layer &ly = vds->layers[i];
        out += "    {\n      \"name\":\"" + JsonEscape(ly.name) + "\",\n";
        out += "      \"geometryType\":\"" + ly.geomType + "\",\n";
        out += "      \"fields\":[\n";
        for (size_t j = 0; j < ly.fields.size(); ++j) {
            FieldDef &f = ly.fields[j];
            out += "        {\"name\":\"" + JsonEscape(f.name) + "\",\"type\":\"" +
                   FieldTypeName(f.type) + "\",\"subtype\":\"None\",\"nullable\":true,\"default\":null}" +
                   ((j + 1 < ly.fields.size()) ? "," : "") + "\n";
        }
        out += "      ]\n    }" + std::string((i + 1 < vds->layers.size()) ? "," : "") + "\n";
    }
    out += "  ]\n}";
    printf("%s", out.c_str());
    delete vds;
    return 0;
}

static int DoDriverCogValidate(Alg &alg)
{
    (void)alg;
    /* the reference implementation requires the Python osgeo_utils module */
    void *p = malloc(1);
    unsigned long addr = (unsigned long)p;
    free(p);
    CPLLError(1, "Traceback (most recent call last):");
    char buf[256];
    snprintf(buf, sizeof(buf), "  File \"cog_validate_module_0x%lx\", line 1, in <module>", addr);
    CPLLError(1, buf + 3);
    CPLLError(1, "ModuleNotFoundError: No module named 'osgeo_utils'");
    CPLLError(1, "");
    return 1;
}
