# pipeline shortcut for 'gdal read FILE ! ...'
s=s.replace('''int GdalMain(int argc, char **argv)''','''/* 'gdal read FILE ! ...' behaves like 'gdal pipeline read FILE ! ...' */
static int RunPipelineShortcut(const std::vector<std::string> &args)
{
    /* find the '!' separated steps */
    std::vector<std::vector<std::string> > steps;
    std::vector<std::string> cur;
    for (auto &a : args) {
        if (a == "!") { steps.push_back(cur); cur.clear(); }
        else cur.push_back(a);
    }
    if (!cur.empty()) steps.push_back(cur);
    if (steps.empty()) return 0;
    /* first step must be a read */
    std::vector<std::string> &readStep = steps[0];
    std::string file;
    std::vector<std::string> readOpts;
    for (size_t i = 1; i < readStep.size(); ++i) {
        if (readStep[i].size() > 1 && readStep[i][0] == '-') {
            if (i + 1 < readStep.size() && readStep[i + 1][0] != '-') { readOpts.push_back(readStep[i]); readOpts.push_back(readStep[i + 1]); ++i; }
            else readOpts.push_back(readStep[i]);
        } else file = readStep[i];
    }
    /* look for a write step */
    for (size_t si = 1; si < steps.size(); ++si) {
        std::vector<std::string> &st = steps[si];
        if (st.empty()) continue;
        std::string stepName = st[0];
        if (stepName == "write") {
            std::string out;
            std::vector<std::string> opts;
            for (size_t i = 1; i < st.size(); ++i) {
                if (st[i].size() > 1 && st[i][0] == '-') {
                    if (i + 1 < st.size() && st[i + 1][0] != '-') { opts.push_back(st[i]); opts.push_back(st[i + 1]); ++i; }
                    else opts.push_back(st[i]);
                } else out = st[i];
            }
            bool overwrite = false;
            std::string fmt;
            std::vector<std::string> co;
            for (size_t i = 0; i < opts.size(); ++i) {
                std::string o = opts[i];
                if (o == "--overwrite") overwrite = true;
                else if (o == "--of" || o == "--output-format" || o == "--format") { if (i + 1 < opts.size()) fmt = opts[++i]; }
                else if (o == "--co" || o == "--creation-option") { if (i + 1 < opts.size()) co.push_back(opts[++i]); }
            }
            GDALDataset *rds = nullptr;
            VectorDataset *vds = nullptr;
            if (!OpenAnyRasterOrVector(file, rds, vds, readOpts)) return NotRecognized(file);
            CPLProgressInit();
            for (int pct = 0; pct <= 100; pct += 10) CPLProgressUpdate(pct / 100.0);
            CPLProgressDone();
            if (rds) {
                GDALDataset *ods = CreateRaster(out, fmt.empty() ? "GTiff" : fmt, rds->nx, rds->ny, rds->nbands,
                                                rds->bands.empty() ? GDT_Byte : rds->bands[0].type, co);
                ods->hasGeoTransform = rds->hasGeoTransform;
                memcpy(ods->geoTransform, rds->geoTransform, sizeof(ods->geoTransform));
                ods->srsWkt = rds->srsWkt;
                ods->metadata = rds->metadata;
                for (size_t b = 0; b < rds->bands.size() && b < ods->bands.size(); ++b) {
                    ods->bands[b] = rds->bands[b];
                    ods->bands[b].blockX = rds->nx;
                    ods->bands[b].blockY = rds->ny;
                }
                WriteRaster(ods);
                delete ods;
                delete rds;
            } else {
                VectorDataset *ods = CreateVector(out, fmt.empty() ? "GeoJSON" : fmt, co, std::vector<std::string>());
                ods->layers = vds->layers;
                WriteVector(ods);
                delete ods;
                delete vds;
            }
            return 0;
        }
        if (stepName == "info") {
            std::vector<std::string> files;
            std::string drv = IdentifyDriver(file, files);
            CmdDef *ci = SpecFind((drv == "GeoJSON" || drv == "ESRI Shapefile" || drv == "GeoJSONSeq") ? "vector/info" : "raster/info");
            Alg a2;
            a2.cmd = ci;
            std::vector<std::string> aargs;
            aargs.push_back(file);
            for (size_t i = 1; i < st.size(); ++i) aargs.push_back(st[i]);
            ParseArgs(a2, aargs);
            a2.setUnsetDefaults();
            return CommandRun(a2);
        }
    }
    return 0;
}

