/* ------------------------------------------------------------------ */
/* additional raster/vector commands                                   */
/* ------------------------------------------------------------------ */
static int DoRasterClip(Alg &alg)
{
    std::string in = alg.str("input");
    GDALDataset *ds = nullptr;
    VectorDataset *v = nullptr;
    if (!OpenAnyRasterOrVector(in, ds, v, alg.lst("open-option"))) return NotRecognized(in);
    if (v) { delete v; return NotRecognized(in); }
    auto bb = alg.lst("bbox");
    auto win = alg.lst("window");
    if (bb.empty() && win.empty()) {
        CPLLError(1, "--bbox, --geometry or --like must be specified");
        fputs(RenderUsageForError(alg.cmd).c_str(), stderr);
        fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
        delete ds;
        return 1;
    }
    int xoff = 0, yoff = 0, xsize = ds->nx, ysize = ds->ny;
    if (win.size() >= 4) {
        xoff = (int)StrDbl(win[0], 0);
        yoff = (int)StrDbl(win[1], 0);
        xsize = (int)StrDbl(win[2], ds->nx);
        ysize = (int)StrDbl(win[3], ds->ny);
    } else if (bb.size() >= 4 && ds->hasGeoTransform) {
        double x0 = StrDbl(bb[0], 0), y0 = StrDbl(bb[1], 0);
        double x1 = StrDbl(bb[2], 0), y1 = StrDbl(bb[3], 0);
        double gx0 = ds->geoTransform[0], gy0 = ds->geoTransform[3];
        double px = ds->geoTransform[1], py = ds->geoTransform[5];
        int a = (int)((x0 - gx0) / px);
        int b = (int)((y1 - gy0) / py);
        int c = (int)((x1 - gx0) / px);
        int d = (int)((y0 - gy0) / py);
        xoff = std::max(0, std::min(a, c));
        yoff = std::max(0, std::min(b, d));
        xsize = std::min(ds->nx, std::max(a, c)) - xoff;
        ysize = std::min(ds->ny, std::max(b, d)) - yoff;
        if (xsize <= 0 || ysize <= 0) { xsize = ds->nx; ysize = ds->ny; xoff = 0; yoff = 0; }
    }
    if (xoff < 0 || yoff < 0 || xoff + xsize > ds->nx || yoff + ysize > ds->ny) {
        CPLLError(1, "Clipping box is outside the source dataset");
        delete ds;
        return 1;
    }
    GDALDataset *ods = CreateRaster(alg.str("output"), alg.str("output-format") == "GDALG" ? "GTiff" : alg.str("output-format"),
                                    xsize, ysize, ds->nbands, ds->bands.empty() ? GDT_Byte : ds->bands[0].type,
                                    alg.lst("creation-option"));
    ods->srsWkt = ds->srsWkt;
    ods->metadata = ds->metadata;
    if (ds->hasGeoTransform) {
        ods->hasGeoTransform = true;
        ods->geoTransform[0] = ds->geoTransform[0] + xoff * ds->geoTransform[1];
        ods->geoTransform[1] = ds->geoTransform[1];
        ods->geoTransform[2] = 0;
        ods->geoTransform[3] = ds->geoTransform[3] + yoff * ds->geoTransform[5];
        ods->geoTransform[4] = 0;
        ods->geoTransform[5] = ds->geoTransform[5];
    }
    for (size_t b = 0; b < ds->bands.size(); ++b) {
        ods->bands[b] = ds->bands[b];
        ods->bands[b].blockX = xsize;
        ods->bands[b].blockY = ysize;
        ods->bands[b].data.assign((size_t)xsize * ysize * DataTypeSize(ods->bands[b].type), 0);
        for (int y = 0; y < ysize; ++y)
            for (int x = 0; x < xsize; ++x)
                ods->bands[b].SetValue((size_t)y * xsize + x,
                                       ds->bands[b].GetValue((size_t)(y + yoff) * ds->nx + (x + xoff)));
    }
    WriteRaster(ods);
    delete ods;
    delete ds;
    return 0;
}

static int DoRasterCompare(Alg &alg)
{
    std::string in = alg.str("input");
    std::string ref = alg.str("reference");
    GDALDataset *a = nullptr, *b = nullptr;
    VectorDataset *v = nullptr, *v2 = nullptr;
    if (!OpenAnyRasterOrVector(in, a, v, alg.lst("open-option"))) return NotRecognized(in);
    if (v) { delete v; return NotRecognized(in); }
    if (!OpenAnyRasterOrVector(ref, b, v2, alg.lst("open-option"))) { delete a; return NotRecognized(ref); }
    if (v2) { delete v2; delete a; return NotRecognized(ref); }
    int rc = 0;
    if (a->nx != b->nx || a->ny != b->ny || a->nbands != b->nbands) {
        printf("Datasets differ in size\n");
        rc = 1;
    } else {
        for (size_t band = 0; band < a->bands.size(); ++band) {
            for (size_t i = 0; i < (size_t)a->nx * a->ny; ++i) {
                double va = a->bands[band].GetValue(i);
                double vb = b->bands[band].GetValue(i);
                double eps = 1e-9;
                if (std::fabs(va - vb) > eps) {
                    printf("Band %d differs at pixel %d\n", (int)band + 1, (int)i);
                    rc = 1;
                    break;
                }
            }
        }
    }
    delete a;
    delete b;
    return rc;
}

