/* very small expression evaluator for 'raster calc' */
struct CalcTok {
    enum Kind { NUM, VAR, OP, LP, RP, END } kind = END;
    double num = 0;
    std::string var;
    char op = 0;
};
static void CalcLex(const std::string &s, std::vector<CalcTok> &out)
{
    size_t i = 0;
    while (i < s.size()) {
        char c = s[i];
        if (isspace((unsigned char)c)) { ++i; continue; }
        CalcTok t;
        if (isdigit((unsigned char)c) || c == '.') {
            char *end = nullptr;
            t.num = strtod(s.c_str() + i, &end);
            t.kind = CalcTok::NUM;
            i = (size_t)(end - s.c_str());
        } else if (isalpha((unsigned char)c)) {
            size_t st = i;
            while (i < s.size() && (isalnum((unsigned char)s[i]) || s[i] == '_')) ++i;
            t.kind = CalcTok::VAR;
            t.var = s.substr(st, i - st);
        } else if (c == '(') { t.kind = CalcTok::LP; ++i; }
        else if (c == ')') { t.kind = CalcTok::RP; ++i; }
        else { t.kind = CalcTok::OP; t.op = c; ++i; }
        out.push_back(t);
    }
    CalcTok e;
    e.kind = CalcTok::END;
    out.push_back(e);
}

struct CalcParser {
    std::vector<CalcTok> t;
    size_t p = 0;
    const std::vector<double> *vals = nullptr;
    size_t npix = 0;
    CalcParser(const std::vector<CalcTok> &toks) : t(toks) {}
    double Expr();
    double Term();
    double Primary();
};

double CalcParser::Primary()
{
    if (t[p].kind == CalcTok::NUM) return t[p++].num;
    if (t[p].kind == CalcTok::VAR) {
        std::string v = t[p++].var;
        if (v.size() >= 1 && (tolower(v[0]) == 'a' || tolower(v[0]) == 'b') && vals) {
            int band = (int)(tolower(v[0]) - 'a');
            if (v.size() > 1) {
                long long idx = 0;
                if (ParseInt(v.substr(1), idx)) band = (int)idx - 1;
            }
            if (band >= 0 && band < (int)vals->size()) return (*vals)[band];
        }
        return 0;
    }
    if (t[p].kind == CalcTok::LP) {
        ++p;
        double v = Expr();
        if (t[p].kind == CalcTok::RP) ++p;
        return v;
    }
    if (t[p].kind == CalcTok::OP && t[p].op == '-') { ++p; return -Primary(); }
    if (t[p].kind == CalcTok::OP && t[p].op == '+') { ++p; return Primary(); }
    return 0;
}

double CalcParser::Term()
{
    double v = Primary();
    while (t[p].kind == CalcTok::OP && (t[p].op == '*' || t[p].op == '/')) {
        char o = t[p++].op;
        double r = Primary();
        if (o == '*') v *= r;
        else v = (r == 0) ? 0 : v / r;
    }
    return v;
}

double CalcParser::Expr()
{
    double v = Term();
    while (t[p].kind == CalcTok::OP && (t[p].op == '+' || t[p].op == '-')) {
        char o = t[p++].op;
        double r = Term();
        if (o == '+') v += r;
        else v -= r;
    }
    return v;
}

static int DoRasterCalc(Alg &alg)
{
    auto inputs = alg.lst("input");
    if (inputs.empty()) return NotRecognized("");
    std::vector<GDALDataset *> dss;
    for (auto &nm : inputs) {
        GDALDataset *d = nullptr;
        VectorDataset *v = nullptr;
        if (!OpenAnyRasterOrVector(nm, d, v, alg.lst("open-option"))) {
            for (auto *x : dss) delete x;
            return NotRecognized(nm);
        }
        if (v) { delete v; for (auto *x : dss) delete x; return NotRecognized(nm); }
        dss.push_back(d);
    }
    auto exprs = alg.lst("calc");
    GDALDataset *first = dss[0];
    GDALDataset *ods = CreateRaster(alg.str("output"), alg.str("output-format") == "GDALG" ? "GTiff" : alg.str("output-format"),
                                    first->nx, first->ny, (int)exprs.size(), GDT_Byte, alg.lst("creation-option"));
    ods->hasGeoTransform = first->hasGeoTransform;
    memcpy(ods->geoTransform, first->geoTransform, sizeof(ods->geoTransform));
    ods->srsWkt = first->srsWkt;
    size_t n = (size_t)first->nx * first->ny;
    for (size_t e = 0; e < exprs.size(); ++e) {
        std::vector<CalcTok> toks;
        CalcLex(exprs[e], toks);
        RasterBand &dst = ods->bands[e];
        dst.type = GDT_Byte;
        dst.data.assign(n, 0);
        std::vector<double> vals(dss.size(), 0);
        for (size_t i = 0; i < n; ++i) {
            for (size_t b = 0; b < dss.size(); ++b) {
                int band = (int)(e % (dss[b]->bands.empty() ? 1 : dss[b]->bands.size()));
                vals[b] = dss[b]->bands[band].GetValue(i);
            }
            CalcParser pr(toks);
            pr.vals = &vals;
            dst.SetValue(i, pr.Expr());
        }
    }
    WriteRaster(ods);
    delete ods;
    for (auto *d : dss) delete d;
    return 0;
}

static int DoVectorSelect(Alg &alg)
{
    std::string in = alg.str("input");
    std::string out = alg.str("output");
    if (FileExists(out) && !alg.flag("overwrite") && !alg.flag("update") && !alg.flag("append")) {
        CPLLError(1, "Dataset '" + out + "' already exists. You may specify the --overwrite/--overwrite-layer/--append/--update option.");
        fputs(RenderUsageForError(alg.cmd).c_str(), stderr);
        fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
        return 1;
    }
    VectorDataset *vds = nullptr;
    GDALDataset *r = nullptr;
    if (!OpenAnyRasterOrVector(in, r, vds, alg.lst("open-option"))) return NotRecognized(in);
    if (r) { delete r; return NotRecognized(in); }
    auto fields = alg.lst("fields");
    if (fields.empty()) {
        CPLLError(1, "Required argument 'fields' has not been specified.");
        delete vds;
        return 1;
    }
    for (auto &ly : vds->layers) {
        std::vector<FieldDef> nf;
        std::vector<size_t> idx;
        for (auto &fn : fields)
            for (size_t i = 0; i < ly.fields.size(); ++i)
                if (ly.fields[i].name == fn) { nf.push_back(ly.fields[i]); idx.push_back(i); }
        ly.fields = nf;
        for (auto &f : ly.features) {
            std::vector<Value> nv;
            for (size_t i : idx) nv.push_back(i < f.values.size() ? f.values[i] : Value());
            f.values = nv;
        }
    }
    VectorDataset *ods = CreateVector(out, alg.str("output-format") == "GDALG" ? "GeoJSON" : alg.str("output-format"),
                                      alg.lst("creation-option"), alg.lst("layer-creation-option"));
    ods->layers = vds->layers;
    WriteVector(ods);
    delete ods;
    delete vds;
    return 0;
}

static int DoRasterPixelInfo(Alg &alg)
{
    std::string in = alg.str("input");
    GDALDataset *ds = nullptr;
    VectorDataset *v = nullptr;
    if (!OpenAnyRasterOrVector(in, ds, v, alg.lst("open-option"))) return NotRecognized(in);
    if (v) { delete v; return NotRecognized(in); }
    auto pos = alg.lst("position");
    double px = 0, py = 0;
    if (pos.size() >= 2) { px = StrDbl(pos[0], 0); py = StrDbl(pos[1], 0); }
    int col = (int)px, line = (int)py;
    if (!pos.empty() && ds->hasGeoTransform) {
        /* position may be georeferenced */
        double x = px, y = py;
        col = (int)((x - ds->geoTransform[0]) / ds->geoTransform[1]);
        line = (int)((y - ds->geoTransform[3]) / ds->geoTransform[5]);
    }
    if (col < 0 || line < 0 || col >= ds->nx || line >= ds->ny) {
        printf("Requested pixel is outside of the dataset\n");
        delete ds;
        return 0;
    }
    size_t i = (size_t)line * ds->nx + col;
    printf("Column: %d, Line: %d\n", col, line);
    printf("Georeferenced position: (%s, %s)\n",
           FormatReal(ds->hasGeoTransform ? ds->geoTransform[0] + col * ds->geoTransform[1] : (double)col).c_str(),
           FormatReal(ds->hasGeoTransform ? ds->geoTransform[3] + line * ds->geoTransform[5] : (double)line).c_str());
    for (size_t b = 0; b < ds->bands.size(); ++b) {
        printf("Band %d:\n", (int)b + 1);
        printf("  Value: %s\n", FormatReal(ds->bands[b].GetValue(i)).c_str());
    }
    delete ds;
    return 0;
}
