    GDALDataset *r = nullptr;
    if (!OpenAnyRasterOrVector(in, r, vds, alg.lst("open-option"))) return NotRecognized(in);
    if (r) { delete r; return NotRecognized(in); }
    auto fields = alg.lst("fields");
    if (fields.empty()) {
        CPLLError(1, "Required argument 'fields' has not been specified.");
        delete vds;
        return 1;
