                vals[b] = dss[b]->bands[band].GetValue(i);
            }
            CalcParser pr(toks);
            pr.vals = &vals;
            dst.SetValue(i, pr.Expr());
        }
    }
    WriteRaster(ods);
    delete ods;
    for (auto *d : dss) delete d;
    return 0;
}

static int DoVectorSelect(Alg &alg)
{
    std::string in = alg.str("input");
    std::string out = alg.str("output");
    if (FileExists(out) && !alg.flag("overwrite") && !alg.flag("update") && !alg.flag("append")) {
        CPLLError(1, "Dataset '" + out + "' already exists. You may specify the --overwrite/--overwrite-layer/--append/--update option.");
        fputs(RenderUsageForError(alg.cmd).c_str(), stderr);
        fprintf(stderr, "Try '%s --help' for help.\n", alg.cmd->fullPathCli().c_str());
        return 1;
    }
    VectorDataset *vds = nullptr;
    GDALDataset *r = nullptr;
    if (!OpenAnyRasterOrVector(in, r, vds, alg.lst("open-option"))) return NotRecognized(in);
    if (r) { delete r; return NotRecognized(in); }
    auto fields = alg.lst("fields");
    if (fields.empty()) {
        CPLLError(1, "Required argument 'fields' has not been specified.");
        delete vds;
        return 1;
    }
    for (auto &ly : vds->layers) {
        std::vector<FieldDef> nf;
        std::vector<size_t> idx;
        for (auto &fn : fields)
            for (size_t i = 0; i < ly.fields.size(); ++i)
                if (ly.fields[i].name == fn) { nf.push_back(ly.fields[i]); idx.push_back(i); }
        ly.fields = nf;
        for (auto &f : ly.features) {
            std::vector<Value> nv;
            for (size_t i : idx) nv.push_back(i < f.values.size() ? f.values[i] : Value());
            f.values = nv;
        }
    }
    VectorDataset *ods = CreateVector(out, alg.str("output-format") == "GDALG" ? "GeoJSON" : alg.str("output-format"),
                                      alg.lst("creation-option"), alg.lst("layer-creation-option"));
    ods->layers = vds->layers;
    WriteVector(ods);
    delete ods;
    delete vds;
    return 0;
}

static int DoRasterPixelInfo(Alg &alg)
{
    std::string in = alg.str("input");
    GDALDataset *ds = nullptr;
    VectorDataset *v = nullptr;
    if (!OpenAnyRasterOrVector(in, ds, v, alg.lst("open-option"))) return NotRecognized(in);
    if (v) { delete v; return NotRecognized(in); }
    auto pos = alg.lst("position");
    double px = 0, py = 0;
    if (pos.size() >= 2) { px = StrDbl(pos[0], 0); py = StrDbl(pos[1], 0); }
    int col = (int)px, line = (int)py;
    if (!pos.empty() && ds->hasGeoTransform) {
        /* position may be georeferenced */
        double x = px, y = py;
        col = (int)((x - ds->geoTransform[0]) / ds->geoTransform[1]);
        line = (int)((y - ds->geoTransform[3]) / ds->geoTransform[5]);
    }
    if (col < 0 || line < 0 || col >= ds->nx || line >= ds->ny) {
        printf("Requested pixel is outside of the dataset\n");
        delete ds;
        return 0;
    }
    size_t i = (size_t)line * ds->nx + col;
    printf("Column: %d, Line: %d\n", col, line);
    printf("Georeferenced position: (%s, %s)\n",
           FormatReal(ds->hasGeoTransform ? ds->geoTransform[0] + col * ds->geoTransform[1] : (double)col).c_str(),
           FormatReal(ds->hasGeoTransform ? ds->geoTransform[3] + line * ds->geoTransform[5] : (double)line).c_str());
    for (size_t b = 0; b < ds->bands.size(); ++b) {
        printf("Band %d:\n", (int)b + 1);
        printf("  Value: %s\n", FormatReal(ds->bands[b].GetValue(i)).c_str());
    }
    delete ds;
    return 0;
}
