            if (a->type != "boolean" && !a->type.empty()) {
                if (t.size() > 2) {
                    std::string msg = "Invalid argument '" + t + "'. Option '" + sh + "' is not a boolean option.";
                    ReportOptionError(alg, 5, msg);
                    return -1;
